/* Base de perguntas e respostas da 3BRAIN + motor de busca local.
   As respostas saem EXCLUSIVAMENTE daqui: nada e gerado, nada e inventado. */
window.BASE_3BRAIN = {"versao":"1","sugestoes":[{"pt":"O que vocês fazem?","en":"What do you do?","id":"o-que-a-3brain-faz"},{"pt":"Isso já funciona?","en":"Does this already work?","id":"estagio-produtos"},{"pt":"Quanto custa?","en":"How much does it cost?","id":"precos-resumo"},{"pt":"Quem são os fundadores?","en":"Who are the founders?","id":"fundadores-quem"},{"pt":"Quanto estão captando?","en":"How much are you raising?","id":"rodada"},{"pt":"Qual o maior risco?","en":"What is the biggest risk?","id":"maior-risco"}],"semResposta":{"naoSei":{"pt":["Não tenho essa resposta aqui. O fundador responde direto, e leva vinte minutos.","Isso não está no material desta página. Prefiro dizer que não sei a inventar.","Não sei. Se quiser, deixo essa pergunta com o fundador e ele responde na conversa."],"en":["I do not have that answer here. The founder answers it directly, and it takes twenty minutes.","That is not in this page's material. I would rather say I do not know than invent it.","I do not know. If you like, I can leave that question with the founder and he answers it on a call."]},"foraEscopo":{"pt":["Isso está fora do que esta página cobre. Aqui é a 3BRAIN: o SAVI, o BarberGO, o motor de aquisição e a rodada.","Não é assunto desta página. Posso responder sobre os produtos, o mercado, os números e o time.","Fora de escopo aqui. Se tiver relação com a 3BRAIN, reformule e eu tento."],"en":["That is outside what this page covers. This page is 3BRAIN: SAVI, BarberGO, the acquisition engine and the round.","Not a subject for this page. I can answer on the products, the market, the numbers and the team.","Out of scope here. If it relates to 3BRAIN, rephrase it and I will try."]},"numeroInexistente":{"pt":["Esse número não existe medido do nosso lado, e não vou estimar.","Não temos essa medição com janela e denominador declarados. Publicar um valor aqui seria premissa, não dado.","Não há número aceito por comprador nem lido em produção para isso. É lacuna declarada desta página."],"en":["That number does not exist measured on our side, and I will not estimate it.","We do not have that measurement with a declared window and denominator. Publishing a figure here would be an assumption, not data.","There is no figure accepted by a buyer or read in production for that. It is a gap this page declares."]}},"entradas":[{"id":"o-que-a-3brain-faz","perguntas":["o que vocês fazem?","o que é a 3BRAIN","me explica a empresa","quais são os produtos de vocês","3brain","what do you do","do que se trata isso aqui","qual é o negócio de vocês"],"pt":"A 3BRAIN tem dois produtos e um canal. O SAVI captura o registro clínico no momento do cuidado e vigia o que ficou em branco ou fora de faixa; o BarberGO conecta barbeiro e barbearia e já está publicado nas duas lojas; o HuntAI não é vendido, é o motor de prospecção por onde os outros dois chegam ao comprador. São dois fundadores, sem funcionário, e a empresa é pré-receita (3BRAIN, ago/2026).","en":"3BRAIN has two products and one channel. SAVI captures the clinical record at the moment of care and watches for what was left blank or out of range; BarberGO connects barbers and barbershops and is already published on both app stores; HuntAI is not sold, it is the prospecting engine through which the other two reach buyers. Two founders, no employees, and the company is pre-revenue (3BRAIN, Aug/2026).","fonte":"Estrutura declarada da 3BRAIN, ago/2026","tags":["empresa","produtos","posicionamento"],"encaminha":"ver-secao","secao":"#porque"},{"id":"o-que-e-savi","perguntas":["o que é o SAVI?","o que o savi faz","me explica o savi em uma frase","o que exatamente vocês vendem","savi","o que e o savi saude","what does SAVI do?","pra que serve isso","pra que serve o savi","para que serve o savi"],"pt":"O SAVI captura o registro no momento do cuidado e vigia o que ficou em branco ou fora de faixa, para que a informação chegue inteira a quem decide. Não é mais um prontuário: entra sobre o sistema que a instituição já tem. O problema não é falta de sistema, porque 92 de cada 100 estabelecimentos já têm sistema eletrônico e, onde há internação, 85 de cada 100 continuam produzindo papel (TIC Saúde 2025, Cetic.br/NIC.br, indicadores B0 e B1). É o dado que morre no caminho entre quem observa e quem decide.","en":"SAVI captures the record at the moment of care and watches for what was left blank or out of range, so the information reaches whoever decides, intact. It is not another medical record system: it sits on top of the one the institution already runs. The problem is not a missing system: 92 of every 100 facilities already run an electronic record and, where there are inpatient beds, 85 of every 100 still produce paper (TIC Saúde 2025, Cetic.br/NIC.br, indicators B0 and B1). It is the data that dies in transit between whoever observes and whoever decides.","fonte":"TIC Saúde 2025 (Cetic.br/NIC.br), indicadores B0 e B1","tags":["produto","savi","posicionamento"],"encaminha":"ver-secao","secao":"#savi"},{"id":"por-que-ilpi","perguntas":["por que começar por ILPI?","por que casa de repouso e não hospital","se o alvo é hospital por que falam de asilo","cabeça de ponte","beachhead","porque ilpi primeiro","não é um mercado pequeno demais?","why start with nursing homes","why long-term care first"],"pt":"Pelo formato da decisão, não pelo tamanho: na ILPI o cheque é assinado pelo proprietário, sem comitê de TI, sem diretoria técnica e sem licitação. E o campo está tecnicamente vazio: entre os 66 certificados SBIS/CFM vigentes, zero são de prontuário assistencial para ILPI ou cuidado continuado (SBIS/CFM, lista pública, ago/2026). O mercado é pequeno de propósito, com 3.548 casas contadas (IPEA, coleta 2007-2009, que é piso porque ILPI não é tipo de estabelecimento no CNES). A cabeça de ponte serve para produzir o desfecho medido que abre a porta do hospital.","en":"Because of the shape of the decision, not the size of the market: in a care home the owner signs the cheque, with no IT committee, no medical board and no public tender. And the field is technically empty: of the 66 SBIS/CFM certificates in force, zero cover a clinical record for long-term or continued care (SBIS/CFM public list, Aug/2026). The market is deliberately small, at 3,548 homes (IPEA, 2007-2009 collection, a floor, since care homes are not an establishment type in CNES). The beachhead exists to produce the measured outcome that opens the hospital door.","fonte":"SBIS/CFM, lista pública ago/2026; IPEA","tags":["mercado","savi","estrategia"],"encaminha":"ver-secao","secao":"#savi"},{"id":"camada-preditiva","perguntas":["o que é a camada preditiva?","o savi prevê piora do paciente?","tem IA que antecipa risco","como funciona a parte preditiva","camada preditiva","predictive layer","isso é alerta de deterioração?"],"pt":"Toda tabela de sinais vitais descreve uma população, nenhuma descreve a pessoa naquela cama. A camada preditiva lê a série temporal de cada indivíduo, aprende a faixa normal dele e assinala quando o padrão dele muda: frequência respiratória de 22 não cruza limite de tabela nenhuma, mas se aquela pessoa vive em 14, o padrão já mudou. Ela não é o que está disponível hoje; o registro sanitário do módulo como software de apoio à decisão clínica é etapa planejada, anterior à comercialização. O princípio já foi provado por terceiros: estruturar apenas a passagem de plantão levou o evento adverso evitável de 4,7 para 3,3 por 100 admissões (Starmer et al., NEJM 2014, 10.740 admissões).","en":"Every vital-signs table describes a population, none describes the person in that bed. The predictive layer reads each individual's time series, learns their normal range and flags it when their pattern shifts: a respiratory rate of 22 crosses no threshold on any table, but if that person lives at 14, their pattern has already changed. It is not what ships today; sanitary registration of the module as clinical decision-support software is a planned milestone ahead of commercialisation. The principle has been proven by others: structuring the shift handoff alone moved preventable adverse events from 4.7 to 3.3 per 100 admissions (Starmer et al., NEJM 2014, 10,740 admissions).","fonte":"Starmer et al., NEJM 2014;371:1803-1812 (I-PASS)","tags":["produto","savi","preditiva","regulacao"],"encaminha":"ver-secao","secao":"#savi"},{"id":"substitui-prontuario","perguntas":["isso substitui o prontuário que eu já tenho?","preciso trocar de sistema?","e o meu Tasy / MV?","integra com o sistema que já temos","vai duplicar o que eu já pago","does it replace our EHR?","convive com prontuario","tem integração?"],"pt":"Convive, não substitui. 92 de cada 100 estabelecimentos já têm sistema eletrônico (TIC Saúde 2025, indicador B0), então vender informatização é vender o que o comprador já comprou. O SAVI entra na camada de captura, em cima da base instalada, e a integração com o sistema instalado faz parte do escopo de hospital. A dor que a própria equipe declara não é interface: dos 11 itens avaliados, o pior é o dado não trafegar entre sistemas, com 42 de cada 100 médicos discordando que os sistemas troquem informação (TIC Saúde 2024, indicador F2A).","en":"It coexists, it does not replace. 92 of every 100 facilities already run an electronic record (TIC Saúde 2025, indicator B0), so selling digitisation means selling what the buyer already bought. SAVI sits in the capture layer, on top of the installed base, and integration with the installed system is part of the hospital scope. The pain staff themselves report is not the interface: of 11 items rated, the worst is data not moving between systems, with 42 of every 100 doctors disagreeing that their systems exchange information (TIC Saúde 2024, indicator F2A).","fonte":"TIC Saúde 2025, indicador B0; TIC Saúde 2024, indicador F2A","tags":["produto","savi","integracao"],"encaminha":"nao","secao":""},{"id":"como-entra-o-dado","perguntas":["como o dado entra sem a equipe digitar?","minha equipe não vai usar","vai aumentar a digitação?","como funciona a captura","cuidador não tem tempo de digitar","how does data get in","o profissional vai ter que preencher tudo de novo?"],"pt":"A ideia é o registro deixar de ser tarefa de digitação e virar subproduto do cuidado: captura curta no ponto do cuidado, o sistema monta o registro estruturado e quem cuidou confirma. Isso responde à objeção mais comum do setor, que não é preconceito e sim memória de sistema que aumentou digitação. O tamanho do problema está medido: 48 de cada 100 minutos que o enfermeiro passa registrando não chegam ao prontuário (Diniz et al., Rev. Enferm. UERJ 2021, 216 h de observação direta). O que ainda não temos é a nossa própria medição por log, e sem log número de economia de tempo não vale.","en":"The idea is that the record stops being a typing task and becomes a by-product of care: short capture at the point of care, the system assembles the structured record, and whoever gave the care confirms it. That answers the sector's most common objection, which is not prejudice but the memory of a system that increased typing. The size of the problem is measured: 48 of every 100 minutes a nurse spends documenting never reach the chart (Diniz et al., Rev. Enferm. UERJ 2021, 216 h of direct observation). What we do not have yet is our own audit-log measurement, and without a log a time-saving number is worth nothing.","fonte":"Diniz et al., Rev. Enferm. UERJ 2021;29:e61926","tags":["produto","savi","adocao"],"encaminha":"nao","secao":""},{"id":"quanto-economiza","perguntas":["quanto tempo isso economiza?","qual o ROI?","vocês têm prova de que funciona?","tem estudo clínico?","qual o resultado medido","prova de eficacia","roi savi","tem evidencia publicada?","how much time does it save","what is the ROI","do you measure the savings"],"pt":"Não temos medição própria, e preferimos dizer isso. A régua publicada para assistente de documentação é menos 16,0 minutos por 8 horas de atendimento (JAMA / Mass General Brigham, 8.581 clínicos): quem alega muito acima disso sem log de auditoria não mostra resultado melhor, mostra medida pior. A prova que existe é da categoria, não nossa, com 4,7 para 3,3 eventos adversos evitáveis por 100 admissões só por estruturar a passagem de plantão (Starmer et al., NEJM 2014). E vale para todo mundo: dos 12 produtos concorrentes examinados, nenhum tem estudo de desfecho indexado sob o nome do produto, o SAVI incluído.","en":"We have no measurement of our own, and we would rather say so. The published yardstick for AI documentation assistants is minus 16.0 minutes per 8 hours of care (JAMA / Mass General Brigham, 8,581 clinicians): anyone claiming far more without an audit log is not showing a better result, they are showing worse measurement. The proof that exists belongs to the category, not to us: 4.7 to 3.3 preventable adverse events per 100 admissions from structuring the handoff alone (Starmer et al., NEJM 2014). And it cuts both ways: of 12 competing products examined, none has an outcome study indexed under the product's own name, SAVI included.","fonte":"JAMA / Mass General Brigham; Starmer et al., NEJM 2014","tags":["evidencia","savi","honestidade"],"encaminha":"ver-secao","secao":"#fontes"},{"id":"dano-e-mortes","perguntas":["por que vocês não citam as 250 mil mortes por erro médico?","e o número do Makary?","quantas mortes por erro médico","to err is human","cadê o número de mortes","erro medico mata quanta gente","qual é a dor que vocês atacam","quantos dias a mais o paciente fica internado","quanto custa um paciente com dano evitavel","how many extra days does a harmed patient stay"],"pt":"Porque os números famosos não sobrevivem à conferência: as 44.000 a 98.000 mortes por ano do IOM (1999) são duas amostras estaduais de 1984 e 1992 extrapoladas para o país, e as 251.454 de Makary e Daniel (BMJ 2016) saíram de uma seção Analysis, combinaram metodologias diferentes sem meta-análise e foram desmontadas por Shojania e Dixon-Woods (BMJ Qual Saf 2017). Usamos o dano, com intervalo declarado: 6 de cada 100 pacientes sofrem dano que não precisava ter acontecido (Panagioti et al., BMJ 2019, 337.025 pacientes, 70 estudos). Se um número de morte for necessário, é o de Rodwin et al. (J Gen Intern Med 2020): 3,1% de mortalidade evitável, cerca de 22.165 mortes por ano, onze vezes menos que o número famoso. Os que usamos são os que sobrevivem: quem sofre dano evitável custa **3 vezes mais e fica 4,6 dias a mais internado** (Porto et al., 2010, sobre **622 prontuários**), e o enfermeiro passa **18,4% do turno** em registro — quase um quinto do plantão a documentar em vez de assistir.","en":"Because the famous numbers do not survive checking: the IOM's 44,000 to 98,000 deaths a year (1999) come from two state samples, 1984 and 1992, extrapolated to the whole country, and Makary and Daniel's 251,454 (BMJ 2016) appeared in an Analysis section, combined different methodologies without meta-analysis and were publicly dismantled by Shojania and Dixon-Woods (BMJ Qual Saf 2017). We use harm instead, with a stated interval: 6 of every 100 patients suffer harm that did not have to happen (Panagioti et al., BMJ 2019, 337,025 patients, 70 studies). If a mortality figure is needed, it is Rodwin et al. (J Gen Intern Med 2020): 3.1% preventable mortality, about 22,165 deaths a year, eleven times fewer than the famous number. The ones we use are the ones that survive scrutiny: a patient who suffers preventable harm costs **3 times more and stays 4.6 days longer** (Porto et al., 2010, over **622 charts**), and the nurse spends **18.4% of the shift** on recording — nearly a fifth of the duty documenting instead of caring.","fonte":"Panagioti et al., BMJ 2019; Rodwin et al., J Gen Intern Med 2020","tags":["dano","evidencia","credibilidade"],"encaminha":"ver-secao","secao":"#dano"},{"id":"quem-usa-savi","perguntas":["quem já usa?","quem já usa o savi?","tem cliente?","quantas instituições usam","tem case?","posso falar com um cliente de vocês","any customers","tem piloto rodando?","who uses savi","does savi have any customer","any paying customer for savi"],"pt":"Hoje há um piloto rodando sobre prontuário real e nenhum cliente pagante: o SAVI não está em produção comercial. Não publicamos nome de instituição nem contagem de pacientes numa página aberta. A natureza do piloto, ou seja, o que é pago, o que está assinado, desde quando e quanto tempo de equipe a instituição aloca, o fundador responde numa conversa de vinte minutos. Enquanto não houver proposta aceita, tudo que dissermos sobre preço e adoção é premissa nossa, e é assim que marcamos.","en":"Today there is one pilot running over a real medical record and no paying customer: SAVI is not in commercial production. We do not publish the institution's name or a patient count on an open page. The nature of the pilot, meaning what is paid, what is signed, since when and how much staff time the institution allocates, is something the founder answers in a twenty-minute call. Until a proposal is accepted, anything we say about price and adoption is our own assumption, and we label it that way.","fonte":"Estado declarado da 3BRAIN, ago/2026","tags":["tracao","savi","piloto"],"encaminha":"falar-com-fundador","secao":"#contato"},{"id":"estagio-produtos","perguntas":["isso já funciona?","o que está no ar de verdade?","em que estágio está o savi?","já está em produção?","tem cliente pagando?","é MVP?","is it live?","estagio dos produtos","tração","o savi já vende","o huntai já vende","que produto já está vendendo","qual deles gera receita"],"pt":"O BarberGO está publicado nas duas lojas. O SAVI não está em produção comercial: roda piloto sobre prontuário real, e é isso que afirmamos, nem uma palavra a mais. O HuntAI não é vendido, opera como canal interno da 3BRAIN e já produziu uma contratação real ponta a ponta. Número de receita, assinante ou download não aparece aqui porque, neste estágio, diria mais sobre marketing do que sobre negócio.","en":"BarberGO is published on both app stores. SAVI is not in commercial production: it runs a pilot over a real medical record, and that is exactly what we claim, not a word more. HuntAI is not sold, it operates as 3BRAIN's internal channel and has already produced one real hire end to end. Revenue, subscriber and download counts do not appear here because, at this stage, they would say more about marketing than about the business.","fonte":"Estágio declarado dos produtos, 3BRAIN, ago/2026","tags":["estagio","produtos","tracao"],"encaminha":"falar-com-fundador","secao":"#savi"},{"id":"concorrentes-savi","perguntas":["quem são os concorrentes do SAVI?","concorrência savi","e o Robô Laura?","já não existe isso no mercado?","vocês competem com MV e Tasy?","tem concorrente em ILPI?","competitors"],"pt":"O concorrente número um é o status quo, ou seja, papel, WhatsApp e o deixa que eu anoto depois, que custa zero e, sem certificação NGS2, em parte é legalmente obrigatório. Nos sistemas, Philips Tasy e MV ocupam o hospital grande, a Laura Networks é a promessa mais próxima da nossa, a NoHarm.aí é a única com literatura própria relevante, e na cabeça de ponte geriátrica aparecem Gerifácil, ILPI360, Medlogic, IW Senior Care e Gero360. De 12 produtos examinados, nenhum tem estudo de desfecho clínico indexado sob o nome do produto, e essa frase vale contra nós também, porque o SAVI também não tem.","en":"Competitor number one is the status quo, meaning paper, WhatsApp and I will write it up later, which costs nothing and, without NGS2 certification, is in part legally required. Among systems, Philips Tasy and MV hold the large hospital, Laura Networks is the closest promise to ours, NoHarm.ai is the only one with relevant literature of its own, and in the geriatric beachhead there are Gerifácil, ILPI360, Medlogic, IW Senior Care and Gero360. Of 12 products examined, none has a clinical outcome study indexed under the product's name, and that sentence cuts against us too, because SAVI has none either.","fonte":"Levantamento próprio ago/2026; lista pública SBIS/CFM; Europe PMC","tags":["concorrencia","savi","evidencia"],"encaminha":"ver-secao","secao":"#savi"},{"id":"precos-concorrentes-savi","perguntas":["quanto os concorrentes cobram?","preço de mercado de software para ILPI","quanto custa um sistema desses hoje","preço por leito no Brasil","quanto o mercado paga por isso","quanto cobra a concorrência","what do competitors charge","competitor pricing in this category"],"pt":"Em ILPI o costume brasileiro é cobrar por casa inteira: R$ 149 (Scaelife), R$ 199 (Os Idosos), R$ 200 (SmarterLar) e R$ 269,90 (Silpi) por mês, em páginas oficiais de ago/2026. Em hospital, o preço público mais firme por leito é o do Epimed no INTO: R$ 166,13 por leito/mês, 48 leitos, cinco anos (contrato 200/2024). Em clínica, os sistemas cobrados por profissional vão de R$ 89 a R$ 299 por mês. E existe um piso de R$ 0,00 que ninguém pode ignorar: AGHU/EBSERH nos hospitais federais e e-SUS APS na atenção básica. Do lado da implantação, a faixa medida em contrato público vai de **1,6% do contrato anual** quando é só configuração (Epimed, R$ 1.500 / US$ 290) a **298%** quando é reescrita de processo cobrada por hora (Philips Tasy, R$ 498 mil / US$ 96 mil). Nossa régua é 1 a 2 mensalidades. Para chegar a R$ 1 milhão de receita recorrente (US$ 193 mil) bastam 2 de cada 1.000 hospitais do registro oficial.","en":"In care homes the Brazilian custom is to charge per house: R$149 (Scaelife), R$199 (Os Idosos), R$200 (SmarterLar) and R$269.90 (Silpi) per month, from official pricing pages, Aug/2026. In hospitals the firmest public per-bed price is Epimed's at INTO: R$166.13 per bed per month, 48 beds, five years (contract 200/2024). In clinics, per-practitioner systems run from R$89 to R$299 a month. And there is a R$0.00 floor nobody can ignore: AGHU/EBSERH in federal hospitals and e-SUS APS in primary care. On the implementation side, the range measured in public contracts runs from **1.6% of the annual contract** when it is configuration only (Epimed, US$ 290) to **298%** when it is a process rewrite billed by the hour (Philips Tasy, US$ 96k). Our rule is 1 to 2 monthly fees. Reaching **US$ 193k** in recurring revenue takes 2 of every 1,000 hospitals in the official registry.","fonte":"Páginas oficiais e contratos públicos, ago/2026","tags":["concorrencia","preco","savi","ancora"],"encaminha":"ver-secao","secao":"#receita"},{"id":"precos-resumo","perguntas":["quanto custa?","preço","quanto vocês cobram","tem tabela de preço?","pricing","qual o valor","quanto vou pagar","é caro","está caro","é barato","sai caro","tem plano grátis","tem versão grátis","dá pra testar de graça","tem teste grátis","tem período de teste","how much does it cost","what is your pricing","how much do you charge","do you have a price list","is there a free plan","do you have a free tier"],"pt":"Depende do produto. O SAVI custa R$ 99 por leito/mês, com piso de R$ 3.000 por contrato: num hospital médio de 66,6 leitos dão R$ 79 mil por ano. O HuntAI custa R$ 1.290 por mês na base de 8.000 contatos verificados, cobrado por contato e não por envio. O BarberGO tem plano gratuito e dois planos pagos no app, Silver a R$ 14,90 e Gold a R$ 29,90 por mês (preço público no app, ago/2026), e o plano de estabelecimento usado na nossa conta é premissa de R$ 89. Os dois primeiros são preço decidido em agosto de 2026 contra âncora pública, não preço aceito por comprador — e é essa diferença que continua valendo a pena dizer em voz alta.","en":"It depends on the product. SAVI costs R$99 per bed per month, with a R$3,000 floor per contract: in an average 66.6-bed hospital that is R$79,000 a year. HuntAI costs R$1,290 a month for the 8,000-verified-contact base, billed per contact and not per send. BarberGO has a free tier and two paid tiers in the app, Silver at R$14.90 and Gold at R$29.90 per month (public in-app price, Aug/2026), and the establishment plan used in our model is an assumption of R$89. The first two are prices settled in August 2026 against a public anchor, not prices a buyer has accepted — and that difference is still worth saying out loud.","fonte":"Decisão de preço 3BRAIN, ago/2026; preço público no app; contrato 200/2024 INTO-MS","tags":["preco","honestidade","premissa"],"encaminha":"ver-secao","secao":"#receita"},{"id":"preco-savi","perguntas":["quanto custa o SAVI?","qual o preço do savi","preço por leito de vocês","quanto custa pra uma casa de 30 residentes","quanto custa por residente","modelo de cobrança do savi","já tem preço definido?","how much in dollars","what is the price in USD","price per bed in dollars"],"pt":"R$ 99 por leito/mês, com piso de R$ 3.000 por contrato e implantação em linha separada. A unidade é o leito, todos e não só os ocupados: cobrar por usuário faz a instituição racionar login, e vigilância só vale se a equipe inteira registrar. Num hospital médio de 66,6 leitos são R$ 6.593 por mês, R$ 79 mil por ano, com 77,2% de margem de contribuição — e R$ 1 milhão de receita recorrente sai com 13 contratos. A âncora é contrato público: R$ 166,13 por leito/mês, cinco anos, por inexigibilidade de licitação (Epimed/INTO-MS, contrato 200/2024), e o nosso preço fica 40% abaixo do que o Estado já paga. Nenhuma proposta foi aceita por um comprador real ainda, e essa continua sendo a lacuna mais cara do estudo.","en":"R$99 per bed per month (US$ 19), with a R$3,000 floor per contract (US$ 580) and deployment on a separate line. The page converts at US$ 1 = R$ 5.17, a rate fixed on 19 Aug 2026, not a live quote. The unit is the bed, all of them and not only the occupied ones: charging per user makes the institution ration logins, and surveillance is only worth anything if the whole team records. In an average 66.6-bed hospital that is R$6,593 a month and R$79,000 a year (US$ 15.3k), at a 77.2% contribution margin — and R$1 million of recurring revenue takes 13 contracts. The anchor is a public contract: R$166.13 per bed per month, five years, awarded without price competition (Epimed/INTO-MS, contract 200/2024), which puts our price 40% below what the State already pays. No proposal has been accepted by a real buyer yet, and that is still the most expensive gap in the study.","fonte":"Decisão de preço 3BRAIN, ago/2026; contrato 200/2024, INTO-MS (Epimed)","tags":["preco","savi","lacuna"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"implantacao","perguntas":["tem taxa de implantação?","a implantação é cobrada à parte?","quanto custa implantar","setup fee","setup entra no ARR?","por que separar implantação da mensalidade","tem custo de onboarding","is there an onboarding fee","what is the setup cost","do you charge for implementation"],"pt":"Sim, em linha separada da mensalidade: 1 a 2 mensalidades em ILPI, clínica e home care, e 3 a 6 em hospital. Implantação é trabalho não recorrente, migrar registro, adaptar processo e treinar em três turnos, e paga o custo de pôr o produto de pé, por isso não entra em ARR nem em churn. Isso importa para valuation, porque ARR com setup, consultoria ou hardware dentro está na lista escrita do que a a16z desconta na leitura. O setor mostra a amplitude: a Epimed cobrou R$ 1.500 de implantação além de R$ 160 por leito ativo/mês (contrato 034/2020), enquanto num contrato público do Tasy a implantação chegou a 298,7% do valor anual da licença (contrato 41/2021). Quando a avaliação da casa indica, a implantação cobre também o equipamento de ambiente, microfone de sala e pulseira de sinais vitais, dimensionado por leito e por área de risco. Não é obrigatório: o SAVI opera com o que a instituição já tem, e o aparelho entra só onde paga a própria conta.","en":"Yes, on a separate line from the subscription: 1 to 2 monthly fees in care homes, clinics and home care, and 3 to 6 in hospitals. Implementation is non-recurring work, migrating records, adapting the process and training across three shifts, and it pays the cost of standing the product up, which is why it never enters ARR or churn. That matters for valuation, because ARR with setup, consulting or hardware inside is on a16z's written list of things they discount. The sector shows the spread: Epimed charged R$1,500 for implementation on top of R$160 per active bed per month (contract 034/2020), while in one public Tasy contract implementation reached 298.7% of the annual licence value (contract 41/2021). Where the site survey calls for it, deployment also covers the ambient equipment, room microphone and vital-sign wristband, sized per bed and per risk area. It is not mandatory: SAVI runs on what the institution already has, and hardware goes in only where it pays for itself.","fonte":"Contratos públicos 034/2020 (Epimed) e 41/2021 (Philips Tasy); modelo 3BRAIN","tags":["preco","implantacao","arr"],"encaminha":"ver-secao","secao":"#receita"},{"id":"lgpd-savi","perguntas":["como fica a LGPD?","e a proteção de dados do paciente?","vocês tratam dado sensível","o dado do residente sai da instituição?","lgpd dado de saude","data protection","vocês têm DPO","e a privacidade?","é seguro","isso é seguro","meus dados estão seguros","que segurança vocês têm","é seguro usar","is it secure","is my data safe","how secure is it"],"pt":"Dado de saúde é dado pessoal sensível (LGPD, art. 11): a instituição é a controladora e a 3BRAIN atua como operadora, com contrato de tratamento, encarregado e registro das operações. O risco material hoje no Brasil não é a multa, já que o total efetivamente cobrado de empresa privada pela ANPD foi R$ 14.400, em 2023, e sim o contratual: a instituição exige a documentação pronta, e quando ela não está, a assinatura atrasa semanas. Em Portugal a conta se inverte, porque dado de saúde é categoria especial do RGPD e cai no teto máximo de coima. E um ponto que nos atinge direto: inteligência artificial é um dos quatro eixos declarados de fiscalização da ANPD (Resolução CD/ANPD nº 30/2025).","en":"Health data is sensitive personal data (LGPD, art. 11): the institution is the controller and 3BRAIN acts as processor, under a data processing agreement, with a designated officer and records of processing. The material risk in Brazil today is not the fine, since the total ever actually levied on a private company by the ANPD was R$14,400, in 2023, but the contractual one: the institution demands the paperwork up front, and when it is missing, signature slips by weeks. In Portugal it inverts, because health data is a special category under GDPR and sits at the maximum fine ceiling. And one point that hits us directly: artificial intelligence is one of the four declared enforcement priorities of the ANPD (Resolution CD/ANPD no. 30/2025).","fonte":"LGPD art. 11 e 52; Resolução CD/ANPD nº 30/2025","tags":["lgpd","risco","juridico","savi"],"encaminha":"falar-com-fundador","secao":"#savi"},{"id":"anvisa-regulatorio","perguntas":["tem registro na ANVISA?","isso é dispositivo médico?","qual a via regulatória","precisa de registro sanitário?","anvisa savi","regulatory pathway","vocês são SaMD?","risco regulatório","do you need anvisa approval","is it a regulated medical device","what is your regulatory status"],"pt":"Não temos registro, e hoje o produto não exige: pela RDC 657/2022, art. 1º, §2º, software usado exclusivamente para registro e visualização de prontuário fica fora do escopo de dispositivo médico. O enquadramento decorre da finalidade declarada, não da tecnologia, e por isso a página não diz em lugar nenhum que o SAVI prevê deterioração: o que ele faz é captura, registro e vigilância do que ficou em branco. As camadas de apoio à decisão clínica são candidatas a Classe II, com registro planejado antes de comercializar (RDC 657/2022 e RDC 751/2022). Custo, prazo e classe dessa regularização são lacuna declarada nossa, e não estimamos.","en":"We hold no registration, and as it stands the product does not require one: under ANVISA RDC 657/2022, art. 1, §2, software used exclusively to record and display a patient chart falls outside the medical device scope. Classification follows the declared intended use, not the technology, which is why this page never says SAVI predicts deterioration: what it does is capture, record and surveillance of what was left blank. The clinical decision-support layers are candidates for Class II, with registration planned before commercialisation (RDC 657/2022 and RDC 751/2022). Cost, timeline and class of that filing are a gap we declare, and we do not estimate them.","fonte":"ANVISA, RDC 657/2022 (art. 1º, §2º) e RDC 751/2022","tags":["regulacao","anvisa","savi","risco"],"encaminha":"falar-com-fundador","secao":"#savi"},{"id":"certificacao-sbis","perguntas":["vocês são certificados SBIS?","tem NGS2?","dá pra eliminar o papel?","certificação CFM","sbis ngs2","posso parar de imprimir","o savi é certificado?","are you certified","do you have SBIS certification","any healthcare certification"],"pt":"Não somos certificados SBIS/CFM, e isso vem com o que precisa vir junto: sem NGS2 nenhuma instituição pode dispensar o registro em papel (Resolução CFM 1.821/2007, vigência a confirmar antes de virar cláusula de contrato). No país inteiro, 5 dos 66 certificados vigentes cobrem internação, e em ILPI e cuidado continuado são zero (SBIS/CFM, lista pública, ago/2026). É isso que explica os 55 de cada 100 estabelecimentos que mantêm o mesmo registro no papel e na tela (TIC Saúde 2025, indicador B1). A trilha para NGS2 está no escopo do produto de hospital e não é promessa de hoje.","en":"We are not SBIS/CFM certified, and that comes with what has to come with it: without NGS2 no institution may drop the paper record (CFM Resolution 1,821/2007, validity to be confirmed before it becomes a contract clause). Across the whole country, 5 of the 66 certificates in force cover inpatient care, and for long-term and continued care it is zero (SBIS/CFM public list, Aug/2026). That is what explains the 55 of every 100 facilities keeping the same record on paper and on screen (TIC Saúde 2025, indicator B1). The path to NGS2 is in scope for the hospital product and is not a promise for today.","fonte":"SBIS/CFM, lista pública ago/2026; Resolução CFM 1.821/2007; TIC Saúde 2025","tags":["regulacao","certificacao","savi"],"encaminha":"nao","secao":""},{"id":"quem-paga-reembolso","perguntas":["quem paga por isso?","tem reembolso?","sai da verba de TI?","o SUS paga?","plano de saúde reembolsa software?","quem assina o cheque","de que orçamento sai","is there reimbursement for this","does insurance pay for it","who pays for it in healthcare"],"pt":"Não existe reembolso de software clínico no Brasil: o cheque sai do caixa da própria instituição. Em cada 100 estabelecimentos, 48 têm rubrica de TI, 37 não têm e 14 não sabem (TIC Saúde 2024, indicador A13). Como não há pagador terceiro, o preço é limitado pelo resultado da instituição, e em ILPI, onde 52,9% do custo é gente (IPEA), o argumento é hora de equipe devolvida e registro que existe quando alguém pergunta. Ressalva que vai junto: não conseguimos fonte primária confirmando a ausência de reembolso na ANS e na CONITEC, então tratamos isso como hipótese de trabalho declarada.","en":"There is no reimbursement for clinical software in Brazil: the cheque comes out of the institution's own cash. Of every 100 facilities, 48 have an IT budget line, 37 do not and 14 do not know (TIC Saúde 2024, indicator A13). With no third-party payer, price is capped by the institution's own economics, and in care homes, where 52.9% of cost is people (IPEA), the argument is staff hours returned and a record that exists when someone asks. Caveat attached: we could not obtain a primary source confirming the absence of reimbursement at ANS and CONITEC, so we treat it as a stated working hypothesis.","fonte":"TIC Saúde 2024, indicador A13; IPEA","tags":["dinheiro","quem-paga","savi"],"encaminha":"ver-secao","secao":"#receita"},{"id":"mercado-savi","perguntas":["TAM do savi","quantos clientes possíveis existem","quantos hospitais tem no brasil","qual o mercado endereçável","tam sam som","mercado em reais"],"pt":"Contado em registro público, de baixo para cima: 6.612 hospitais, 92.356 clínicas e centros de especialidade e 2.084 serviços de atenção domiciliar isolados (CNES/DATASUS, jul/2026); a ILPI entra por fora, com 3.548 casas (IPEA, coleta 2007-2009). Aplicado o filtro de quem tem rubrica de TI, que são 48 de cada 100 estabelecimentos (TIC Saúde 2024, indicador A13), sobram 50.806 unidades com como comprar. São contagens de estabelecimento e não de decisor: parte pertence a redes, e 59 de cada 100 hospitais privados têm até 50 leitos. Não publicamos TAM em reais, porque o preço ainda não está fechado e multiplicar contagem por preço suposto é o erro que derruba um estudo de mercado. Somados, são **98.968 hospitais e clínicas especializadas** contados no registro oficial. E o que separa quem compra não é porte, é internação: **3.270 gestores** ouvidos pela TIC Saúde 2025 (Cetic.br/NIC.br, fev–nov/2025) mostram que 92 de cada 100 estabelecimentos já têm sistema, mas onde há internação **85 ainda produzem papel**.","en":"Counted bottom-up on public registers: 6,612 hospitals, 92,356 clinics and specialty centres and 2,084 standalone home-care services (CNES/DATASUS, Jul/2026); care homes sit outside that, at 3,548 (IPEA, 2007-2009 collection). Applying the filter of who has an IT budget line, 48 of every 100 facilities (TIC Saúde 2024, indicator A13), leaves 50,806 units able to buy. These are counts of facilities, not of decision-makers: some belong to chains, and 59 of every 100 private hospitals have up to 50 beds. We publish no TAM in reais, because the price is not settled and multiplying a count by an assumed price is the error that sinks a market study. Added up, that is **98,968 hospitals and specialised clinics** counted in the official registry. And what separates the buyer is not size but inpatient care: **3,270 managers** surveyed by TIC Saúde 2025 (Cetic.br/NIC.br, Feb–Nov 2025) show that 92 of every 100 facilities already have a system, but where there are inpatients **85 still produce paper**.","fonte":"CNES/DATASUS jul/2026; TIC Saúde 2024, indicador A13; IPEA","tags":["mercado","savi","metodo"],"encaminha":"ver-secao","secao":"#receita"},{"id":"metodo-tam","perguntas":["por que vocês não publicam um TAM em reais?","cadê o mercado de bilhões","de onde vem esse número de mercado","vocês usaram Euromonitor ou Gartner?","metodologia do tamanho de mercado","como vocês contaram o mercado"],"pt":"Porque a conta que produz esses bilhões não fecha, e o investidor derruba em dois minutos. O método é bottom-up, número de clientes contados vezes preço por cliente, com a contagem vindo de censo administrativo (CNES, Mapa de Empresas, IBGE/CEMPRE) e não de relatório de consultoria. Quando conferimos os TAMs que já tínhamos escrito, eles multiplicavam universos de amostragem diferentes, um percentual de pesquisa por amostra vezes uma contagem de registro. Foi assim que caiu um TAM de R$ 128 bilhões do BarberGO: preferimos publicar a contagem e o preço separados e deixar a multiplicação à vista. O número do LinkedIn é derivado, não colhido: parte do limite medido da conta (**240 pedidos por hora**, seguros) vezes o rendimento medido de **0,352 e-mail por perfil**, numa jornada de 8 horas — dá **84 e-mails por hora** e **~14.800 e-mails novos**, 100% inéditos contra a base. E a origem muda o rendimento: perfil achado por post rende **5,8×** o achado por busca.","en":"Because the arithmetic behind those billions does not hold, and an investor takes it apart in two minutes. The method is bottom-up, number of counted customers times price per customer, with the count coming from administrative census data (CNES, Mapa de Empresas, IBGE/CEMPRE) rather than from a consultancy report. When we audited the TAMs we had already written, they multiplied different sampling universes: a survey percentage times a registry count. That is how a R$128 billion BarberGO TAM fell: we prefer to publish the count and the price separately and leave the multiplication in plain sight. The LinkedIn figure is derived, not harvested: it takes the account's measured ceiling (**240 requests per hour**, safe) times the measured yield of **0.352 e-mails per profile**, over an 8-hour day — giving **84 e-mails per hour** and **~14,800 new e-mails**, 100% previously unseen against the base. And the source changes the yield: a profile found via post yields **5.8×** one found via search.","fonte":"Método declarado, estudo 3BRAIN, ago/2026","tags":["metodo","mercado","credibilidade"],"encaminha":"ver-secao","secao":"#fontes"},{"id":"cambio-usado","secao":"#fontes","tags":["metodo","moeda","fonte"],"perguntas":["qual o cambio usado","como converteram para dolar","de quanto e o dolar da pagina","os valores em dolar sao de quando","what exchange rate","how did you convert to dollars","is the dollar figure current"],"pt":"**US$ 1 = R$ 5,17**, pela PTAX de 19/08/2026 (R$ 5,18). A conversão é **fixada nessa data, não é cotação ao vivo** — a página em português publica em real e a versão em inglês converte por esse valor. Dizemos isto porque número em moeda estrangeira sem data é número sem sentido: quem lê daqui a seis meses precisa saber que a régua é de agosto de 2026, e não achar que acompanha o mercado.","en":"**US$ 1 = R$ 5.17**, from the PTAX rate of 19 Aug 2026 (R$ 5.18). The conversion is **fixed at that date, not a live quote** — the Portuguese page publishes in reais and the English version converts at that value. We say so because a figure in foreign currency without a date is a meaningless figure: whoever reads this in six months needs to know the rule is from August 2026, and not assume it tracks the market.","fonte":"PTAX/Banco Central, 19/08/2026"},{"id":"penetracao-conservadora","perguntas":["que penetração vocês assumem?","vocês assumem quantos % do mercado","penetração de mercado","e se pegarem só 1%?","cenário conservador ou otimista","por que a conta é tão conservadora"],"pt":"O caso principal é sempre o conservador: 5% do universo filtrado, com 1% como piso e 10% como teto. A regra é literal, ou seja, se existe espaço para 30%, a conta se faz em 5%, o otimista fica em coluna à direita e toda tabela declara a penetração assumida. Não é modéstia: empresas de tecnologia chegam ao IPO com 0,1% a 2% do mercado endereçável, então escrever 1% de um mercado de R$ X bilhões como se fosse humildade denuncia que ninguém olhou a distribuição. E inflar um número não custa aquele número, custa a credibilidade de todos os outros da página.","en":"The base case is always the conservative one: 5% of the filtered universe, with 1% as the floor and 10% as the ceiling. The rule is literal: if there is room for 30%, the calculation is done at 5%, the optimistic case sits in the right-hand column, and every table states the penetration assumed. This is not modesty: technology companies reach IPO holding 0.1% to 2% of their addressable market, so writing 1% of an R$X billion market as though it were humility shows nobody looked at the distribution. And inflating one number does not cost you that number, it costs the credibility of every other number on the page.","fonte":"Regra editorial declarada, estudo 3BRAIN, ago/2026","tags":["metodo","mercado","conservador"],"encaminha":"ver-secao","secao":"#fontes"},{"id":"imposto-simples","perguntas":["que imposto vocês consideraram?","simples nacional anexo","anexo III ou anexo V","alíquota de imposto","vocês põem imposto na margem?","fator r","imposto simples nacional","what taxes do you pay","what is your tax regime"],"pt":"Simples Nacional, e no cenário provável o Anexo V, que é o mais caro. O anexo depende do fator R: com folha abaixo de 28% da receita cai no Anexo V, que começa em 15,5%, e acima disso vale o Anexo III, que começa em 6% (LC 123/2006). Com dois sócios e pouca folha, o Anexo V é o cenário realista, e a alíquota efetiva sobe por faixa de receita, chegando perto de 21,3%. Todas as margens publicadas já estão com esse imposto dentro, porque margem apresentada sem linha de imposto foi o primeiro achado dos revisores do nosso próprio estudo.","en":"Simples Nacional, and in the likely case Annex V, the most expensive one. The annex depends on the payroll ratio: with payroll below 28% of revenue the company falls into Annex V, which starts at 15.5%, and above that it falls into Annex III, which starts at 6% (LC 123/2006). With two partners and a small payroll, Annex V is the realistic case, and the effective rate rises with the revenue band, approaching 21.3%. Every margin we publish already has that tax inside, because a margin shown without a tax line was the first finding of our own study's reviewers.","fonte":"LC 123/2006, Anexos III e V","tags":["dinheiro","imposto","margem"],"encaminha":"nao","secao":""},{"id":"margem-por-cliente","perguntas":["quanto vocês ganham por cliente?","qual a margem de vocês","margem bruta","quanto sobra por cliente depois do imposto","unit economics","a margem fecha?","economia unitária"],"pt":"Depois do imposto, cada cliente do SAVI deixa R$ 309 por mês (51,6%), cada assinatura do BarberGO deixa R$ 38 (42,6%) e cada conta B2B do HuntAI deixa R$ 104 (34,7%), em conta própria com Simples Anexo V e taxa de loja de 15% no BarberGO. Se a taxa de loja for de 30%, a margem do BarberGO cai para 27,6%. Nenhuma dessas margens foi medida em produção: são modeladas, e a premissa mais sensível, a taxa de acerto de cache, ainda não foi lida em operação. Publicamos a versão com imposto e taxa de loja dentro, não a versão bruta.","en":"After tax, each SAVI customer leaves R$309 a month (51.6%), each BarberGO subscription leaves R$38 (42.6%) and each HuntAI B2B account leaves R$104 (34.7%), on our own model under Simples Annex V with a 15% app-store fee for BarberGO. At a 30% store fee, BarberGO's margin falls to 27.6%. None of these margins has been measured in production: they are modelled, and the most sensitive assumption, the prompt-cache hit rate, has not yet been read in live operation. We publish the version with tax and store fee already inside, not the gross one.","fonte":"Conta própria 3BRAIN, Simples Anexo V, ago/2026","tags":["dinheiro","margem","unit-economics"],"encaminha":"ver-secao","secao":"#receita"},{"id":"clientes-para-1-milhao","perguntas":["quantos clientes para chegar a R$ 1 milhão?","quanto falta pra 1 mi de ARR","clientes para 1 milhão de receita recorrente","quantos clientes vocês precisam","1 milhão quantos clientes","how many customers to reach 1 million","customers needed for 1m of revenue"],"pt":"Para chegar a R$ 1 milhão de receita anual recorrente seriam precisos, em cálculo de meta: 13 hospitais no SAVI, a R$ 99 por leito/mês, e 65 clientes no HuntAI, a R$ 1.290 por mês na base de 8.000 contatos verificados. Mesma meta, dois esforços de venda que não se parecem: 13 vendas consultivas de ciclo longo contra 65 contratos de ferramenta. Para calibrar, 13 hospitais são 2 de cada 1.000 dos 6.612 hospitais contados no CNES. O BarberGO fica fora desta conta enquanto a tabela do app está em revisão. Os preços estão decididos, mas nenhum foi validado em proposta assinada.","en":"For R$1 million of annual recurring revenue: 13 hospitals on SAVI, at R$99 per bed per month, and 65 clients on HuntAI, at R$1,290 a month for the 8,000-verified-contact base. Same target, two sales efforts that look nothing alike: 13 long-cycle consultative sales against 65 tool contracts. For calibration, 13 hospitals is 2 of every 1,000 of the 6,612 hospitals counted in CNES. BarberGO stays out of this arithmetic while the app's rate card is under review. The prices are settled, but none has been validated in a signed proposal.","fonte":"Conta própria 3BRAIN, premissas declaradas, ago/2026","tags":["dinheiro","arr","metas"],"encaminha":"ver-secao","secao":"#receita"},{"id":"break-even","perguntas":["quando vocês se pagam?","break even","quando fica no azul","quantos clientes para se sustentar","ponto de equilíbrio","when do you break even","where is your break-even point"],"pt":"Pela conta interna, o equilíbrio operacional do SAVI fica em 16 lares, cerca de 608 leitos, ou R$ 23.641 de receita recorrente mensal. A revisão adversarial do próprio estudo põe esse ponto entre 30 e 40 lares, depois de entrar suporte humano no custo, o pacote regulatório completo e o imposto correto, e é essa a versão que usamos, porque é a que sobrevive à diligência. Junto vai a leitura honesta: os primeiros R$ 4.560 de receita recorrente são marco de validação, não de sustentabilidade, e não pagam um pró-labore.","en":"On our internal calculation, SAVI's operating break-even sits at 16 care homes, roughly 608 beds, or R$23,641 of monthly recurring revenue. The adversarial review of our own study puts that point between 30 and 40 homes once human support enters cost, the full regulatory package is included and the correct tax is applied, and that is the version we use, because it is the one that survives diligence. The honest reading goes with it: the first R$4,560 of recurring revenue is a validation milestone, not sustainability, and does not cover one founder's pay.","fonte":"Conta própria 3BRAIN e revisão adversarial, ago/2026","tags":["dinheiro","break-even","savi"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"receita-hoje","perguntas":["vocês têm receita?","qual a receita hoje?","quanto vocês faturam","vocês têm ARR?","qual o MRR","tem faturamento","já tem cliente pagando?","o barbergo já vende","o barbergo vende","o produto já vende","já vendem para cliente","já tem venda","já monetiza","o app gera receita","are you selling yet","do you have revenue","are you profitable","voces dao lucro hoje","voces ja tem cliente","voces ja tem algum cliente"],"pt":"Não há receita: a 3BRAIN é pré-receita, e não adianta enfeitar. O BarberGO está publicado nas duas lojas, o SAVI não está em operação comercial, e o HuntAI opera como canal interno, tendo produzido uma contratação real ponta a ponta sem ser vendido a terceiros. Pré-receita é o padrão do estágio no Brasil: a faixa publicada de pré-seed é de R$ 0 a 1 milhão (Astella, Napkin 2025-2026), e metade das rodadas semente de SaaS de 2025 não tinha receita recorrente nenhuma (Point Nine, 95 rodadas). No lugar de ARR inventado, oferecemos burn, tempo de caixa e um marco declarado.","en":"There is no revenue: 3BRAIN is pre-revenue, and there is no point dressing that up. BarberGO is published on both app stores, SAVI is not in commercial operation, and HuntAI runs as an internal channel, having produced one real hire end to end without being sold to third parties. Pre-revenue is standard for the stage in Brazil: the published pre-seed band is R$0 to 1 million (Astella, Napkin 2025-2026), and half of 2025's SaaS seed rounds had no recurring revenue at all (Point Nine, 95 rounds). Instead of an invented ARR we offer burn, runway and one declared milestone.","fonte":"3BRAIN, ago/2026; Astella Napkin 2025-2026; Point Nine","tags":["dinheiro","estagio","pre-receita"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"rodada","perguntas":["quanto estão captando?","qual o tamanho da rodada","quanto querem levantar","estão captando?","vocês buscam investimento?","qual o instrumento da rodada","captação","valuation","posso investir em vocês","quero investir","como faço para investir","aceitam investimento","how much are you raising","what are you raising","how big is the round","are you fundraising right now","what instrument is the round","quanto voces estao captando","can I invest in you","how can I invest"],"pt":"R$ 600 a 800 mil, em mútuo conversível com teto de R$ 4 a 6 milhões, e não em rodada precificada (plano financeiro 3BRAIN, ago/2026). O dinheiro é para o SAVI: os dois fundadores em tempo integral, o pacote regulatório, infraestrutura e a venda consultiva das primeiras instituições. O marco é único e verificável: três instituições pagantes com cobrança recorrente rodando, a margem medida em produção e o preço por leito validado contra três concorrentes cotados. Não há valuation pré-money definido, porque o instrumento é conversível com teto, e os termos finais se conversam.","en":"R$600,000 to R$800,000, as a convertible note with a R$4 to 6 million cap, not a priced round (3BRAIN financial plan, Aug/2026). The money is for SAVI: both founders full-time, the regulatory package, infrastructure, and consultative selling into the first institutions. The milestone is single and verifiable: three paying institutions with recurring billing running, margin measured in production, and the per-bed price validated against three quoted competitors. There is no defined pre-money valuation, because the instrument is a capped convertible, and final terms are a conversation.","fonte":"Plano financeiro 3BRAIN, ago/2026","tags":["rodada","dinheiro","conversivel"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"tempo-de-caixa","perguntas":["quanto tempo de caixa isso compra?","runway","quantos meses de caixa","quanto tempo dura o dinheiro","qual o burn de vocês","uso dos recursos","what is your runway","how many months of runway","how long does the money last"],"pt":"Dezesseis meses: doze meses de plano mais quatro de folga. O plano de 12 meses custa cerca de R$ 473 mil e a maior linha dele é pró-labore, com 41% do orçamento, ou seja, a necessidade de capital é em boa medida o custo de o fundador parar de procurar emprego CLT. Se os fundadores operarem com metade do pró-labore, o plano de 12 meses cai para cerca de R$ 377 mil. O plano de 24 meses custaria R$ 1,09 milhão, o que exigiria um cheque no limite superior do que o mercado brasileiro dá a uma empresa pré-receita.","en":"Sixteen months: twelve months of plan plus four of slack. The 12-month plan costs about R$473,000 and its largest line is founder pay, at 41% of the budget, meaning the capital need is largely the cost of the founder stopping his search for a salaried job. If the founders run at half that pay, the 12-month plan falls to about R$377,000. A 24-month plan would cost R$1.09 million, which would require a cheque at the top end of what the Brazilian market gives a pre-revenue company.","fonte":"Plano financeiro 3BRAIN, ago/2026","tags":["rodada","runway","burn"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"macro-captacao","perguntas":["o Brasil está bom para captar?","por que vocês pedem tão pouco","por que conversível e não equity","como está o venture capital no Brasil","e o macro","por que não pedem mais dinheiro","how is the venture funding market","is it a good moment to raise in brazil"],"pt":"Não está bom, e não vale fingir. As rodadas de venture capital no Brasil caíram de 227 em 2023 para 96 em 2025 (ABVCAP e TTR Data, 1T2026), e o estágio semente foi o único que encolheu na região naquele ano. Com a Selic em 14%, qualquer investidor brasileiro tem alternativa líquida rendendo isso sem risco. Por isso pedimos pouco, em instrumento conversível e com um marco único, e por isso a sequência começa pelo que não dilui: programas sem participação acionária.","en":"It is not, and there is no point pretending. Venture rounds in Brazil fell from 227 in 2023 to 96 in 2025 (ABVCAP and TTR Data, Q1 2026), and seed was the only stage that shrank in the region that year. With the policy rate at 14%, any Brazilian investor has a liquid, risk-free alternative paying that. That is why we ask for little, through a convertible instrument, against a single milestone, and why the sequence starts with what does not dilute: equity-free programmes.","fonte":"ABVCAP e TTR Data, 1T2026","tags":["rodada","macro","captacao"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"aceleradoras-investidor","perguntas":["vocês têm investidor?","estão em alguma aceleradora?","quem já investiu?","tem aporte?","backed by?","vocês são acelerados?","já captaram?","tem anjo","do you have investors already","were you accepted in any accelerator","ja recusaram voces","foram rejeitados em algum programa"],"pt":"Ainda não. Nenhum programa de aceleradora tem resultado registrado, nem aceito nem rejeitado, e por isso a página não exibe logo nenhum: usar marca de programa sem vínculo é risco jurídico, e essa audiência confere. Até aqui a empresa foi bancada pelos dois fundadores, desde a abertura em abril/2026 (CNPJ 66.447.959/0001-88). Termos de rodada e uso do capital são conversa direta, não linha de página.","en":"Not yet. No accelerator programme has a recorded outcome, neither accepted nor rejected, which is why no logo appears on this page: displaying a programme's brand without a real relationship is a legal risk, and this audience checks. Up to now the company has been funded by the two founders, since incorporation in April 2026 (CNPJ 66.447.959/0001-88). Round terms and use of proceeds are a direct conversation, not a page item.","fonte":"Situação de programas e captação da 3BRAIN, ago/2026","tags":["captacao","empresa","transparencia"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"o-que-e-barbergo","perguntas":["o que é o BarberGO?","barbergo é o quê","me explica o barbergo em uma frase","que produto é esse","barbergo","como funciona o app de vocês","é um app de agendamento?","what is barbergo"],"pt":"O BarberGO conecta barbeiro e barbearia: o profissional monta um perfil com histórico e portfólio, a casa procura quem pode ocupar a cadeira, e a descoberta é por swipe. O perfil só passa a valer depois que a identidade é conferida, com um modelo de visão comparando a foto do documento com uma selfie. Não é agenda para o dono: é o lado do trabalho, que nenhum dos concorrentes brasileiros que levantamos vende (levantamento próprio de produtos e preços, ago/2026).","en":"BarberGO connects barbers and barbershops: the professional builds a profile with work history and portfolio, the shop looks for someone to fill the chair, and discovery works by swipe. A profile only counts once identity is checked, with a vision model comparing the ID photo against a selfie. It is not a booking calendar for the owner: it is the labour side, which none of the Brazilian competitors we surveyed sells (our own product and pricing survey, Aug/2026).","fonte":"Produto publicado; levantamento próprio de concorrentes, ago/2026","tags":["produto","barbergo","posicionamento"],"encaminha":"ver-secao","secao":"#barbergo"},{"id":"onde-publicado","perguntas":["onde eu baixo?","está publicado?","tem na play store?","tem na app store?","já está no ar?","link do app","barbergo play store","já lançaram","funciona no iphone","funciona no android","tem para ios","preciso instalar alguma coisa","precisa instalar","tem versão web","roda no navegador","é aplicativo ou site","só tem app","tem site ou app","vai ter versão web","o savi é app ou web"],"pt":"Está publicado nas duas lojas, Google Play e App Store, sob o nome BarberGO. É produto no ar, não protótipo, e é ele que responde à pergunta sobre conseguir entregar até a loja. Para efeito de comparação dentro da 3BRAIN: o SAVI, o produto de saúde, ainda não está em operação comercial. Sobre plataforma: hoje o BarberGO é **só aplicativo**, e a versão web está no plano — plano, não produto no ar. O SAVI está previsto para os dois, aplicativo e web, e também é plano.","en":"It is live on both stores, Google Play and the App Store, under the name BarberGO. It is a shipped product, not a prototype, and it is the one that answers whether we can actually ship to a store. For comparison inside 3BRAIN: SAVI, the healthcare product, is not in commercial operation yet. On platforms: BarberGO is **app-only** today, and the web version is planned — planned, not shipped. SAVI is planned for both, app and web, and that is a plan too.","fonte":"Google Play (com.barbergo.app) e App Store (BarberGO); roteiro de produto declarado pela 3BRAIN, ago/2026","tags":["status","barbergo","lojas"],"encaminha":"ver-secao","secao":"#barbergo"},{"id":"problema-barbergo","perguntas":["que problema o barbergo resolve","qual a dor","por que alguém usaria isso","dor do barbeiro","por que barbearia precisa disso","falta barbeiro ou falta canal?","o setor não resolveu isso sozinho?","por que uma barbearia pagaria por isso"],"pt":"O setor quase não emprega: foram 210 contratações de barbeiro com carteira assinada no Brasil inteiro em doze meses (Novo CAGED/MTE, CBO 516105, jul/25 a jun/26). No mesmo país, 768.830 pessoas mantêm um MEI ativo na atividade de cabeleireiro, barbeiro e manicure (Mapa de Empresas, 2º quad./2025). O trabalho acontece por parceria, não por vaga, e todo canal de contratação que existe pressupõe vaga, currículo e contrato, apontados para um mercado que não emprega. Some-se que em dois anos o setor abriu 15.522 estabelecimentos formais e perdeu 2.975 empregos assalariados (IBGE/CEMPRE, SIDRA 9528, 2022-2024): mais lojas, cada uma menor.","en":"The sector barely employs: 210 barbers were hired on formal contracts in all of Brazil over twelve months (CAGED/MTE, occupation code 516105, Jul/25 to Jun/26). In the same country, 768,830 people keep an active sole-trader registration in hairdressing, barbering and manicure (Mapa de Empresas, Q2 2025). The work happens through partnership, not through job openings, and every hiring channel that exists assumes a vacancy, a CV and a contract, pointed at a market that does not hire. On top of that, in two years the sector opened 15,522 formal establishments and lost 2,975 salaried jobs (IBGE/CEMPRE, SIDRA 9528, 2022-2024): more shops, each one smaller.","fonte":"Novo CAGED/MTE, CBO 516105; Mapa de Empresas 2º quad./2025; IBGE/CEMPRE","tags":["dor","barbergo","trabalho"],"encaminha":"ver-secao","secao":"#barbergo"},{"id":"modelo-receita-barbergo","perguntas":["como ganham dinheiro","modelo de receita","monetização","de onde vem a receita","vocês cobram de quem","quem paga a conta","modelo de negócio","what is your business model","how do you make money","what is your revenue model","quanto vale um assinante por ano","quanto rende cada assinante","receita por assinante","how much is a subscriber worth"],"pt":"Assinatura, e a intenção é que quem pague seja o estabelecimento. É o único lado com preço revelado: uma barbearia já paga R$ 79,90 por mês, na mediana, por um software que só faz agenda (Trinks, AppBarber, Avec e Belasis, páginas oficiais, ago/2026). Do lado do profissional o preço-piso do mercado é R$ 0,00, então cobrar dele é a hipótese frágil, e nós a tratamos como hipótese. Comissão sobre a colocação não fecha, e explicamos por quê em outra pergunta. Por assinante e por ano isso dá **R$ 1.068 (US$ 207)**, com **42,6% de margem de contribuição** já contando a taxa de loja. Os quatro planos de entrada do mercado vão de **R$ 39,95 a R$ 189,00** (US$ 7,70 a 36,55) — Trinks, AppBarber, Avec e Belasis. E o setor sustenta o reajuste: o preço de cabeleireiro e barbeiro subiu **36,0%** entre 2022 e 2025, contra **20,97%** do IPCA cheio (IBGE/SIDRA 7060), com **236 mil** aberturas no ano.","en":"Subscription, and the intent is that the establishment is the one paying. It is the only side with a revealed price: a barbershop already pays R$79.90 a month, at the median, for software that only books appointments (Trinks, AppBarber, Avec and Belasis, official pricing pages, Aug/2026). On the professional's side the market floor price is R$0.00, so charging them is the fragile hypothesis, and we treat it as a hypothesis. A commission on placements does not work, and we explain why under a separate question. Per subscriber per year that is **US$ 207**, at a **42.6% contribution margin** already net of store fees. The four entry plans in the market run from **US$ 7.70 to US$ 36.55** — Trinks, AppBarber, Avec and Belasis. And the sector supports the increase: hairdressing and barbering prices rose **36.0%** between 2022 and 2025, against **20.97%** headline inflation (IBGE/SIDRA 7060), with **236,000** openings in the year.","fonte":"Páginas oficiais Trinks, AppBarber, Avec e Belasis, ago/2026","tags":["receita","barbergo","modelo"],"encaminha":"ver-secao","secao":"#barbergo"},{"id":"preco-barbergo","perguntas":["quanto custa o barbergo","qual o preço da assinatura","plano quanto é","quanto custa o app","ticket médio da assinatura","preço barbergo","how much does the app cost","what does the subscription cost"],"pt":"Hoje o app tem um plano gratuito e dois pagos: Silver a R$ 14,90 e Gold a R$ 29,90 por mês (preço público no app, ago/2026). O plano de estabelecimento que a nossa conta de receita usa é de R$ 89 por mês, ancorado no que a barbearia já paga por agenda, com mediana de R$ 79,90 e faixa de R$ 39,95 a R$ 189,00 (quatro páginas oficiais de preço, ago/2026). Esse R$ 89 é premissa declarada, não preço aceito por um comprador, e converter essa premissa em dado é exatamente o trabalho de agora.","en":"The app currently has a free tier and two paid ones: Silver at R$14.90 and Gold at R$29.90 per month (public in-app price, Aug/2026). The establishment plan our revenue model uses is R$89 a month, anchored on what a barbershop already pays for scheduling software, a median of R$79.90 across a range of R$39.95 to R$189.00 (four official pricing pages, Aug/2026). That R$89 is a stated assumption, not a price a buyer has accepted, and turning that assumption into data is exactly the work in front of us.","fonte":"Preço público no app; páginas oficiais de preço, ago/2026","tags":["preco","barbergo","validacao"],"encaminha":"falar-com-fundador","secao":"#barbergo"},{"id":"mercado-barbergo","perguntas":["qual o tamanho do mercado do barbergo","quantas barbearias tem no brasil","mercado de barbearia brasil","quantos clientes potenciais o barbergo tem","TAM barbergo","quantos CNPJ tem nesse setor"],"pt":"Contado, não estimado: 900.868 CNPJs ativos na atividade de cabeleireiro, barbeiro e manicure, a segunda maior do Brasil em número de empresas, atrás só do varejo de vestuário (Mapa de Empresas, 2º quad./2025). Desses, 85 de cada 100 são MEI, ou seja, uma pessoa só, sem sócio. Não publicamos TAM em reais porque o CNAE 9602-5/01 junta barbearia, salão e manicure, então a fração que é barbearia seria premissa nossa e não medição. Fechar isso é contagem direta, e o começo é a Grande Florianópolis, com 1.251 barbearias e salões formais endereçáveis um a um (IBGE/CEMPRE, SIDRA 9528, 2024).","en":"Counted, not estimated: 900,868 active company registrations in hairdressing, barbering and manicure, the second largest activity in Brazil by number of firms, behind only clothing retail (Mapa de Empresas, Q2 2025). Of those, 85 out of every 100 are sole traders, meaning one person, no partner. We publish no TAM in reais because activity code 9602-5/01 lumps barbershops, salons and manicurists together, so the barbershop share would be our assumption, not a measurement. Closing that is direct counting, and it starts in Greater Florianópolis, with 1,251 formal barbershops and salons addressable one by one (IBGE/CEMPRE, SIDRA 9528, 2024).","fonte":"Mapa de Empresas 2º quad./2025; IBGE/CEMPRE, SIDRA 9528, 2024","tags":["mercado","barbergo","beachhead"],"encaminha":"ver-secao","secao":"#barbergo"},{"id":"concorrentes-barbergo","perguntas":["quem são os concorrentes do barbergo","e a trinks?","e o appbarber","quem mais faz isso no setor de beleza","vocês competem com quem","concorrência barbergo"],"pt":"Do lado do software: Trinks (R$ 76 por mês na faixa de 1 a 2 profissionais, 100% da Stone desde maio de 2024), Avec (R$ 88,90), Belasis (R$ 99 a R$ 189), AppBarber, e com capital estrangeiro Fresha (R$ 39,95 no plano autônomo) e Booksy, em páginas oficiais de ago/2026. Todos vendem agenda e financeiro para o dono do estabelecimento, e os dois marketplaces existentes são cliente para barbearia. Nenhum vende a conexão barbeiro para barbearia. O vazio corta dos dois lados: a Trinks declara 40 a 44 mil negócios de beleza e nunca lançou esse produto, e vale saber se não viu valor ou se testou e não funcionou.","en":"On the software side: Trinks (R$76 a month in the 1 to 2 professional tier, fully owned by Stone since May 2024), Avec (R$88.90), Belasis (R$99 to R$189), AppBarber, and with foreign capital Fresha (R$39.95 on the solo plan) and Booksy, from official pricing pages, Aug/2026. All of them sell scheduling and finance to the shop owner, and the two existing marketplaces run customer to shop. None sells the barber to shop connection. The empty space cuts both ways: Trinks claims 40,000 to 44,000 beauty businesses and never launched this product, and it is worth knowing whether they saw no value or tried it and it failed.","fonte":"Páginas oficiais de preço dos players, ago/2026","tags":["concorrencia","barbergo"],"encaminha":"nao","secao":""},{"id":"concorrente-status-quo-barbergo","perguntas":["quem é o maior concorrente","por que o whatsapp é concorrente","concorrente número 1","e a indicação","status quo","o cara não contrata pelo grupo do zap?"],"pt":"É a indicação e o grupo de WhatsApp. De cada 100 jovens ocupados no Brasil, 77 conseguiram o emprego atual por indicação (Fundação Itaú com Datafolha e Instituto Locomotiva, 1.816 jovens, mai/2026, que é proxy porque a pesquisa não tem recorte de barbearia). Esse concorrente é grátis, instantâneo e já chega com a confiança embutida, que é justamente o que um marketplace novo leva anos para construir. A mesma pesquisa aponta o público real do produto: a indicação decide para 32% da classe A/B e 16% da D/E, ou seja, quem tem menos rede é quem mais precisa de um lugar para ser encontrado.","en":"It is referral and the WhatsApp group. Of every 100 employed young Brazilians, 77 got their current job through a referral (Fundação Itaú with Datafolha and Instituto Locomotiva, 1,816 respondents, May/2026, a proxy since the survey has no barbershop segment). That competitor is free, instant and arrives with trust already built in, which is precisely what a new marketplace takes years to earn. The same survey points to the product's real audience: referral is decisive for 32% of the top income brackets and 16% of the bottom ones, so those with the least network are the ones who most need somewhere to be found.","fonte":"Fundação Itaú, Datafolha e Instituto Locomotiva, mai/2026 (proxy)","tags":["concorrencia","barbergo","status-quo"],"encaminha":"nao","secao":""},{"id":"ia-no-barbergo","perguntas":["o que a IA faz no app","para que serve a ia ali","vocês usam ia como?","ia do barbergo","qual o papel da inteligência artificial","é só um chatzinho?"],"pt":"Ela resolve confiança e apresentação, que é onde o barbeiro perde trabalho. A verificação de identidade compara a foto do documento com uma selfie, e o perfil só vale depois disso, funcionando como substituto do eu conheço o cara, que hoje só a indicação oferece. E a IA ajuda o profissional a transformar o que ele digita em um perfil que a barbearia consegue ler e comparar com o do lado. Não contamos quantos modelos usamos: o que decide é o que sai do caminho do barbeiro.","en":"It solves trust and presentation, which is where barbers lose work. Identity verification compares the ID photo against a selfie, and the profile only counts after that, standing in for I know the guy, which today only a referral provides. And the AI helps the professional turn what he types into a profile a shop can actually read and compare against the next one. We do not count how many models we use: what matters is what gets out of the barber's way.","fonte":"Produto publicado (verificação de identidade por visão)","tags":["ia","barbergo","produto"],"encaminha":"nao","secao":""},{"id":"usuarios-barbergo","perguntas":["quantos usuários vocês têm","qual a base","quantos barbeiros cadastrados","quantas barbearias usam","MAU","números de tração","how many users does barbergo have","do you publish downloads","what are your user numbers"],"pt":"Agora dá, e é o que esta resposta prometia: com denominador e janela declarada. **75 contas criadas**, das quais 70 já entraram alguma vez; **7 ativas nos últimos 30 dias** e 4 nos últimos 7. **Uma assinatura ativa.** Medido em 29/08/2026, direto no banco, não estimado.\n\nÉ pequeno e não maquiamos. O que os números mostram é que o produto **foi usado de verdade** — 315 curtidas, 18 matches, 120 avaliações e 77 resenhas saíram de gente real, não de semente — e que **não há tração comercial**. Chamar 75 cadastros de tração seria exatamente a métrica de vaidade que recusamos usar. O que falta não é produto: é canal e preço, e é nisso que estamos.","en":"Now we can, and it is what this answer promised: with a denominator and a stated window. **75 accounts created**, of which 70 have signed in at least once; **7 active in the last 30 days** and 4 in the last 7. **One active subscription.** Measured on 29 Aug 2026, straight from the database, not estimated.\n\nIt is small and we do not dress it up. What the numbers show is that the product **was genuinely used** — 315 likes, 18 matches, 120 ratings and 77 reviews came from real people, not from seeding — and that **there is no commercial traction**. Calling 75 sign-ups traction would be exactly the vanity metric we refuse to use. What is missing is not the product: it is channel and price, and that is what we are working on.","fonte":"Firebase Auth e Firestore do BarberGO, contagem de 29/08/2026","tags":["tracao","barbergo","honestidade"],"encaminha":"falar-com-fundador","secao":"#barbergo"},{"id":"barbergo-e-healthtech","perguntas":["por que uma healthtech tem app de barbearia","qual a relação entre savi e barbergo","por que manter o barbergo","isso não dispersa?","qual é o carro chefe","why healthcare and barbershops together","how do the two products fit"],"pt":"Os dois produtos atacam a mesma coisa: trabalho que ainda é registrado no papel e no WhatsApp, num mercado em que o comprador já paga por software. E cada um tem um fundador que viveu o problema, já que o SAVI saiu do prontuário que um preenchia no fim do plantão e o BarberGO saiu da cadeira vazia que o outro fechava no fim do mês, como dono da própria barbearia. O BarberGO tem ainda uma função que nenhum slide substitui: está publicado nas duas lojas e é onde aprendemos preço, cobrança e retenção com usuário real, antes de fazer o mesmo na saúde.","en":"Both products attack the same thing: work still recorded on paper and over WhatsApp, in a market where the buyer already pays for software. And each has a founder who lived the problem, since SAVI came out of the chart one of them filled in at the end of a shift and BarberGO came out of the empty chair the other closed the month with, as the owner of his own shop. BarberGO also does something no slide replaces: it is live on both stores, and it is where we learn pricing, billing and retention with real users before doing the same in healthcare.","fonte":"Estrutura declarada da 3BRAIN; produto publicado nas duas lojas","tags":["3brain","foco","barbergo"],"encaminha":"ver-secao","secao":"#porque"},{"id":"por-que-nao-comissao","perguntas":["por que não cobram comissão","take rate","por que não cobrar por contratação","modelo de comissão","e se o par sair pelo whatsapp?","desintermediação","why not charge a commission","why no take rate"],"pt":"Porque a transação não se repete. O barbeiro troca de cadeira raramente, o encontro acontece uma vez e depois o relacionamento continua fora do app por construção, então não existe segunda transação para taxar. Há evidência revisada por pares na direção mais incômoda possível: quanto mais a plataforma faz os dois lados confiarem um no outro, mais eles saem dela (Gu e Zhu, Management Science 67(2), 2021). As duas maiores plataformas de serviço local do mundo já precificaram assumindo isso, com a TaskRabbit cobrando o dobro na primeira interação e a Thumbtack desistindo da comissão para vender o encontro. Assinatura é a receita que sobra de pé.","en":"Because the transaction does not repeat. A barber changes chairs rarely, the match happens once, and after that the relationship continues outside the app by construction, so there is no second transaction to tax. There is peer-reviewed evidence pointing in the most uncomfortable direction: the more a platform makes both sides trust each other, the more they leave it (Gu and Zhu, Management Science 67(2), 2021). The two largest local-services platforms in the world already priced around this, with TaskRabbit charging double on the first interaction and Thumbtack giving up on commission to sell the introduction. Subscription is the revenue model left standing.","fonte":"Gu e Zhu, Management Science 67(2), 2021; preços públicos TaskRabbit e Thumbtack","tags":["modelo","barbergo","take-rate"],"encaminha":"nao","secao":""},{"id":"fosso-barbergo","perguntas":["o que impede a Trinks de copiar","qual o fosso do barbergo","defensabilidade do barbergo","e se um concorrente grande fizer igual","tem efeito de rede?","barreira de entrada no barbergo"],"pt":"Três coisas, e nenhuma delas é o chat. O perfil profissional verificado é um ativo do indivíduo, não do estabelecimento: viaja com o barbeiro quando ele troca de cadeira e sobrevive ao fechamento da casa. O lado da colocação não é servido por nenhum player brasileiro que levantamos. E a Lei 13.352/2016 obriga contrato escrito e nota fiscal sobre o repasse entre salão e profissional parceiro, então um app que gera o contrato e a nota resolve obrigação com prazo e multa, não conveniência. Sobre o resto somos diretos: agenda, mecânica de swipe e preço não são defensáveis, e se o produto provar o mercado, um incumbente com distribuição pronta liga o recurso rápido.","en":"Three things, and none of them is the chat. The verified professional profile is an asset of the individual, not of the shop: it travels with the barber when he changes chairs and survives the shop closing. The placement side is served by none of the Brazilian players we surveyed. And Law 13,352/2016 requires a written contract and an invoice on the revenue split between shop and partner professional, so an app that generates the contract and the invoice solves an obligation with a deadline and a fine attached, not a convenience. On everything else we are blunt: scheduling, swipe mechanics and price are not defensible, and if the product proves the market, an incumbent with distribution already in place turns the feature on fast.","fonte":"Lei 13.352/2016 (Salão Parceiro); levantamento próprio de concorrentes, ago/2026","tags":["fosso","barbergo","risco"],"encaminha":"falar-com-fundador","secao":"#barbergo"},{"id":"churn-barbergo","perguntas":["e o churn","retenção","esse cliente não some?","quanto tempo o cliente fica","churn de assinatura","o cliente cancela rápido?","what is your churn","what is the churn rate"],"pt":"É alto por natureza, e dizemos antes de perguntarem. De cada 100 MEIs de serviços, 37 fecham antes de dois anos (SEBRAE, coorte de 13.756.779 empresas, Kaplan-Meier, mar/2026), o que dá cerca de 1,9% ao mês de saída que nenhum trabalho de produto elimina, porque não é cancelamento e sim o cliente deixando de existir. E em assinatura de aplicativo, 15 a 40 de cada 100 assinantes mensais saem já na primeira renovação (RevenueCat, State of Subscription Apps 2026, 115 mil apps). Por isso a conta que decide o produto é a base de equilíbrio, vendas brutas por mês dividido pelo churn, e não o tamanho do mercado.","en":"It is structurally high, and we say so before being asked. Of every 100 sole traders in services, 37 shut down before two years (SEBRAE, cohort of 13,756,779 firms, Kaplan-Meier, Mar/2026), roughly 1.9% monthly attrition that no product work removes, because it is not a cancellation but the customer ceasing to exist. And in app subscriptions, 15 to 40 of every 100 monthly subscribers leave at the first renewal (RevenueCat, State of Subscription Apps 2026, 115,000 apps). That is why the equation that decides this product is the steady-state base, gross sales per month divided by churn, not the size of the market.","fonte":"SEBRAE, sobrevivência de empresas, mar/2026; RevenueCat 2026","tags":["churn","barbergo","risco"],"encaminha":"nao","secao":""},{"id":"aquisicao-e-canal","perguntas":["como vocês adquirem cliente","CAC","canal de aquisição","vão fazer tráfego pago?","como chegam nas barbearias","go to market","estratégia de venda","how do you acquire customers","what is your CAC","what is your go to market"],"pt":"Não por mídia paga. Com a conversão e o churn públicos da categoria, a conta de tráfego pago fecha negativa no ticket de app de consumo, e a conta é nossa, então dizemos isso em vez de esconder. Os dois canais que fecham são lista finita e porta: a Grande Florianópolis tem 1.251 barbearias e salões formais endereçáveis um a um, sem leilão de mídia (IBGE/CEMPRE, SIDRA 9528, 2024), e a lista de CNPJs recém-abertos sai dos dados abertos da Receita Federal, de graça, com atualização mensal. No lado saúde o comprador é institucional e está contado no CNES, e é lá que o e-mail frio é a régua.","en":"Not through paid media. With the category's public conversion and churn figures, the paid-traffic math comes out negative at a consumer-app price point, and the math is ours, so we say it rather than hide it. The two channels that do close are a finite list and a doorbell: Greater Florianópolis has 1,251 formal barbershops and salons addressable one by one, with no media auction (IBGE/CEMPRE, SIDRA 9528, 2024), and the list of newly registered businesses comes free from the federal open-data files, updated monthly. On the healthcare side the buyer is institutional and counted in CNES, and that is where cold email is the yardstick.","fonte":"IBGE/CEMPRE, SIDRA 9528, 2024; Receita Federal, Dados Abertos CNPJ","tags":["cac","canal","gtm"],"encaminha":"ver-secao","secao":"#motor"},{"id":"capacidade-de-pagamento","perguntas":["o barbeiro tem dinheiro pra pagar isso?","esse cliente paga software?","quanto uma barbearia pode pagar","não é cliente pobre demais?","capacidade de pagamento","teto do MEI"],"pt":"É a pergunta certa, e a resposta tem os dois lados. 85 de cada 100 CNPJs da atividade são MEI, e o MEI fatura, por lei, no máximo R$ 6.750 por mês (Mapa de Empresas, 2º quad./2025; LC 123/2006), e é essa a caixa dentro da qual qualquer preço tem de caber. Do outro lado, a disposição a pagar não é hipótese: quatro páginas oficiais de preço mostram uma barbearia pagando R$ 79,90 por mês, na mediana, por um software que só faz agenda (ago/2026). O cliente paga software. A pergunta é por qual pedaço.","en":"That is the right question, and the answer has two sides. 85 of every 100 registered businesses in the activity are sole traders, and by law a sole trader may bill at most R$6,750 a month (Mapa de Empresas, Q2 2025; LC 123/2006), and that is the box any price has to fit inside. On the other side, willingness to pay is not a hypothesis: four official pricing pages show a barbershop paying R$79.90 a month, at the median, for software that only books appointments (Aug/2026). The customer does pay for software. The question is for which piece.","fonte":"Mapa de Empresas 2º quad./2025; LC 123/2006; páginas oficiais de preço","tags":["preco","barbergo","cliente"],"encaminha":"nao","secao":""},{"id":"precedente-squire","perguntas":["alguém já tentou isso","existe caso parecido","e a Squire","precedente internacional","por que ninguém fez antes","tem comparável no exterior?","what happened to squire","is there a precedent for this"],"pt":"Foi feito, e a trajetória é pública. A Squire, americana e exclusiva de barbearia, levantou cerca de US$ 167 milhões e chegou a mais de 3.000 estabelecimentos, e desde julho de 2021 não divulga captação nova (Contrary Research e imprensa do setor, valores reportados e não auditados). A leitura que tiramos é dupla: existe negócio real de barbearia, e ele não suporta aquisição paga por capital, já que a receita por cliente dela só cresceu quando virou empresa de pagamento. No Brasil, o caminho que funcionou foi o do Trinks: treze anos de crescimento lento até ser comprado por uma empresa de pagamento.","en":"It has been done, and the trajectory is public. Squire, an American barbershop-only company, raised roughly US$167 million and reached over 3,000 shops, and has announced no new round since July 2021 (Contrary Research and trade press, reported figures, not audited). We read that two ways: a real barbershop business exists, and it does not support capital-funded paid acquisition, since their revenue per customer only grew once they became a payments company. In Brazil the path that worked was Trinks': thirteen years of slow growth until it was acquired by a payments company.","fonte":"Contrary Research e imprensa do setor; histórico público Trinks/Stone","tags":["precedente","barbergo","risco"],"encaminha":"nao","secao":""},{"id":"o-que-e-huntai","perguntas":["o que é o HuntAI","huntai","o que faz o huntai?","para que serve o huntai","explica o huntai pra mim","what is HuntAI","o que é o motor de aquisição"],"pt":"O HuntAI é o motor de prospecção da própria 3BRAIN: monta a lista a partir de registro público, dispara o contato frio e acompanha resposta e descadastro. Hoje opera como canal interno, por onde o SAVI e o BarberGO chegam ao comprador. A base extraída hoje soma 2.126.099 e-mails únicos de 15 registros públicos — a soma das fontes daria 3.782.070, mas 43,8% se repete entre elas e somar seria inflar em 1,6 milhão. A prova saiu em saúde, porque é o setor que conhecemos: 275.919 endereços diretos de 518.604 estabelecimentos varridos, e 49.763 contatos alcançados, com 0,008% de reclamação — 12× abaixo do limite que faz provedor banir. Mas o que se prova ali não é um dado de saúde, é um rendimento de extração — o registro público é o mesmo para todos os setores, e por isso o alcance do motor é a economia formal inteira.","en":"HuntAI is 3BRAIN's own prospecting engine: it builds the list from public registries, sends the cold contact and tracks replies and opt-outs. Today it runs as an internal channel, the way SAVI and BarberGO reach their buyers. The base extracted so far comes to 2,126,099 unique e-mails from 15 public registers — the sources would add up to 3,782,070, but 43.8% overlaps between them and adding them would inflate it by 1.6 million. The proof came out of healthcare, because that is the sector we know: 275,919 direct addresses from 518,604 facilities swept, and 49,763 contacts reached, at a 0.008% complaint rate — 12× below the threshold that gets a sender banned. But what that proves is not a healthcare figure, it is an extraction yield — the public register is the same one for every sector, which is why the engine's reach is the whole formal economy.","fonte":"Operação HuntAI sobre CNES/DATASUS, 2026","tags":["huntai","canal","definicao"],"encaminha":"ver-secao","secao":"#motor"},{"id":"foco-tres-frentes","perguntas":["como duas pessoas tocam três produtos?","não é muita coisa pra duas pessoas?","vocês têm três produtos?","o huntai é produto ou canal","qual é o foco de vocês?","3 produtos 2 fundadores","foco","why three products","are you spread too thin"],"pt":"Não são três produtos disputando o mesmo tempo. O HuntAI não é produto: é o motor de aquisição por onde os outros dois chegam ao comprador, e opera como canal interno. O BarberGO já está publicado nas duas lojas e hoje consome manutenção, não construção. O SAVI é onde o trabalho de fato está, e é a prioridade. Ainda assim, três frentes com duas pessoas é uma bandeira que um investidor levanta com razão, e a primeira contratação existe para tirar carga de uma só cabeça.","en":"They are not three products competing for the same hours. HuntAI is not a product: it is the acquisition engine through which the other two reach buyers, and it runs as an internal channel. BarberGO is already published on both stores and now takes maintenance, not construction. SAVI is where the work actually sits, and it is the priority. Even so, three fronts with two people is a flag an investor is right to raise, and the first hire exists to take load off a single head.","fonte":"Estrutura declarada da 3BRAIN, 2026","tags":["time","foco","huntai"],"encaminha":"ver-secao","secao":"#time"},{"id":"prova-do-canal","perguntas":["o que o HuntAI já entregou de resultado?","isso já funcionou de verdade?","tem resultado real ou é só tese?","qual a prova de que o canal funciona?","isso já é motor ou ainda é tese?","does it actually work?"],"pt":"Uma contratação real, ponta a ponta: a vaga foi extraída pelo motor, a candidatura foi montada e enviada por ele, e o processo terminou em contratação - rastreada até a caixa exata, com data e hora, e os 13 ledgers de plataforma descartando o resto. E o funil agora está medido e publicado: **12.368 candidaturas** de 26.811 tentativas, **49.763 e-mails** com 89,4% de entrega e 0,008% de reclamação, e **86 empregadores distintos** com conversa de entrevista - 60 deles portugueses. O que continua sem número auditável é o WhatsApp, contado por captura de tela e declarado como piso.","en":"One real hire, end to end: the posting was extracted by the engine, the application was assembled and sent by it, and the process ended in a hire - traced to the exact inbox, with date and time, and the 13 platform ledgers ruling out everything else. And the funnel is now measured and published: **12,368 applications** out of 26,811 attempts, **49,763 e-mails** at 89.4% delivery and a 0.008% complaint rate, and **86 distinct employers** in interview conversations - 60 of them Portuguese. What still has no auditable figure is WhatsApp, counted from screenshots and declared as a floor.","fonte":"Ledgers da operação HuntAI e API do Elastic Email, medidos em 22-23/08/2026","tags":["huntai","tracao","lacuna"],"encaminha":"falar-com-fundador","secao":"#motor"},{"id":"frente-candidato-encerrada","perguntas":["por que encerraram a frente do candidato?","o huntai não era pra quem procura emprego?","se funcionou por que pararam?","por que mataram o produto de emprego","why did you kill the job-seeker side?"],"pt":"Porque a conta não fechava: R$ 3,90 por assinante/mês depois do imposto, a um preço de R$ 49 (conta própria, Simples Anexo V). Há ainda dois defeitos estruturais: o produto dá certo quando o cliente consegue emprego e cancela, e o risco de banimento nas plataformas cai sobre quem paga, não sobre nós. A linha foi encerrada por conta, não por opinião, e a contratação real que ela produziu ficou como prova de que o motor executa ponta a ponta.","en":"Because the arithmetic did not close: R$3.90 per subscriber per month after tax, at a R$49 price (our own calculation, Simples Annex V). Two structural defects sat underneath it: the product succeeds when the customer lands a job and cancels, and the platform-ban risk falls on the person paying, not on us. The line was closed by arithmetic, not by opinion, and the real hire it produced remains the proof that the engine runs end to end.","fonte":"Conta própria 3BRAIN, preço R$ 49, Simples Anexo V","tags":["huntai","julgamento","margem"],"encaminha":"nao","secao":""},{"id":"custo-chegar-comprador","perguntas":["como isso reduz o custo de chegar ao comprador?","por que ter o motor em casa importa?","qual a vantagem de canal próprio","isso baixa o custo de aquisição?","how does owning the channel cut cost?","quanto custa conseguir um cliente novo","quanto custa comparado com linkedin ads","quanto custa comparado com anuncio","e mais barato que trafego pago","how does it compare to paid ads"],"pt":"Quem compra a ferramenta pronta paga por cada envio, para sempre, e a régua pública diz que sai R$ 5,3 a 6,2 mil por mês em folha de prospecção, ou R$ 80 a 400 por lead em mídia frios (Belkins, 2025, sobre 7.530.489 envios). Com o motor em casa, esse volume deixa de ser despesa comprada de fora a cada disparo, e a lista-alvo é contável no registro oficial: 6.612 hospitais e 92.356 clínicas especializadas (CNES/DATASUS, jul/2026). O que ainda não temos é o nosso custo por reunião medido, e quando o funil próprio fechar, ele substitui o benchmark alheio. A página publica a comparação inteira, por reunião gerada: **LinkedIn Ads** custa R$ 275 por lead (US$ 53), o que dá **R$ 1.375 a 2.750** por reunião (US$ 266 a 532); **Google Ads B2B** sai a R$ 825 a 1.650 (US$ 160 a 319). Contra o primeiro o HuntAI ganha de **52% a 76%**, contra o segundo de **20% a 60%**.","en":"Buy the tool off the shelf and you pay for every send, forever, and the public yardstick is one meeting per 6,275 cold emails (Belkins, 2025, across 7,530,489 sends). With the engine in-house that volume stops being an expense bought from outside on every run, and the target list is countable in the official registry: 6,612 hospitals and 92,356 specialised clinics (CNES/DATASUS, Jul/2026). What we still lack is our own measured cost per meeting, and once the in-house funnel closes, it replaces the third-party benchmark. The page publishes the whole comparison, per meeting generated: **LinkedIn Ads** costs US$ 53 per lead, which works out to **US$ 266 to 532** per meeting; **Google Ads B2B** runs US$ 160 to 319. Against the first the HuntAI wins by **52% to 76%**, against the second by **20% to 60%**.","fonte":"Belkins, 2025; CNES/DATASUS, jul/2026","tags":["huntai","aquisicao","custo"],"encaminha":"ver-secao","secao":"#motor"},{"id":"benchmark-belkins","perguntas":["de onde vem esse número de 6.275?","1 reunião a cada 6.275 e-mails, é seu?","taxa de resposta de e-mail frio","belkins","cold email benchmark","esse número é de vocês ou de terceiro","what is the industry benchmark for outbound"],"pt":"É referência de terceiro, não nossa: 4,5 respostas por 1.000 e-mails e R$ 5,3 a 6,2 mil por mês em folha de prospecção (Belkins, 2025, com 34.393 respostas e mais de 1.200 reuniões sobre 7.530.489 envios). O denominador é quem recebeu, não quem abriu, e a mesma campanha vira cerca de 5% se o denominador mudar, ou seja, onze vezes de diferença sem nenhum fato novo. Tratamos o 6.275 como piso, porque o mais de 1.200 pode vir de um subconjunto das campanhas.","en":"It is a third-party reference, not ours: 4.5 replies per 1,000 emails and R$5.3–6.2k a month in prospecting payroll (Belkins, 2025, with 34,393 replies and 1,200 plus meetings across 7,530,489 sends). The denominator is who received, not who opened, and the same campaign reads about 5% if the denominator changes, an elevenfold difference with no new fact. We treat 6,275 as a floor, because the 1,200 plus may come from a subset of the campaigns.","fonte":"Belkins, benchmark de cold outbound, 2025","tags":["benchmark","denominador","outbound"],"encaminha":"ver-secao","secao":"#fontes"},{"id":"entregabilidade","perguntas":["e se cair tudo no spam?","entregabilidade","qual o portão de devolução?","o que impede a conta de ser bloqueada","bounce gate","deliverability","what about email deliverability","what is your bounce rate"],"pt":"O portão é o provedor de envio, não o destinatário: acima de 10 devoluções a cada 100 a AWS pausa o envio, e 5 já põem a conta sob revisão (documentação AWS SES, 2026). Por isso o custo do canal não está no envio e sim na higiene da lista, já que verificar 100 mil endereços custa cerca de US$ 350 contra US$ 194 para enviá-los (tabelas públicas ZeroBounce/NeverBounce e Instantly, 2026). Em agosto de 2026 foram 24.518 envios, com 89,4% de entrega e 0,008% de reclamação, 12× abaixo do limite (operação HuntAI). Ressalva: a entrega de julho é desconhecida, o provedor anterior não a expunha.","en":"The gate is the sending provider, not the recipient: above 10 bounces per 100 AWS suspends sending, and 5 already puts the account under review (AWS SES documentation, 2026). That is why the cost of the channel sits in list hygiene rather than in sending, since verifying 100,000 addresses runs about US$350 against US$194 to send them (public ZeroBounce/NeverBounce and Instantly pricing, 2026). In the campaign closed on 15 Aug 2026, 24,515 emails went out with zero spam complaints (HuntAI operation).","fonte":"Documentação AWS SES, 2026; operação HuntAI","tags":["entregabilidade","risco","operacao"],"encaminha":"ver-secao","secao":"#motor"},{"id":"nossa-devolucao","perguntas":["qual a taxa de devolução de vocês?","qual o seu bounce rate?","vocês já foram pausados pela aws?","vocês já estouraram o limite?","what is your bounce rate?"],"pt":"Não publicamos esse número, e o motivo é técnico: pela documentação da própria AWS, a taxa que aparece no console não é a taxa pela qual se é julgado, porque conta só devolução dura e usa um volume representativo móvel, não uma janela fixa. Do nosso lado, a medição ainda não tem janela e denominador declarados, e número de falha sem denominador não vai para uma página de captação. O que é fixo é o portão: 10 devoluções a cada 100 pausam o envio e 5 põem sob revisão (AWS SES, 2026), e por isso a verificação da lista é a primeira compra do canal.","en":"We do not publish that figure, for a technical reason: by AWS's own documentation the rate shown in the console is not the rate you are judged by, because it counts hard bounces only and uses a moving representative volume rather than a fixed window. On our side the measurement does not yet have a declared window and denominator, and a failure number without a denominator does not belong on a fundraising page. What is fixed is the gate: 10 bounces per 100 suspend sending and 5 put you under review (AWS SES, 2026), which is why list verification is the channel's first purchase.","fonte":"Documentação AWS SES, 2026","tags":["entregabilidade","honestidade","lacuna"],"encaminha":"falar-com-fundador","secao":"#motor"},{"id":"lgpd-email-frio","perguntas":["isso é legal?","pode mandar e-mail sem autorização?","lgpd email frio","é permitido prospectar assim","is cold B2B email legal in Brazil?","e a LGPD no contato frio"],"pt":"Para contato B2B no Brasil a base legal é o legítimo interesse, que dispensa consentimento prévio desde que a finalidade esteja documentada, o dado seja minimizado e o descadastro seja fácil (LGPD art. 7º, IX; Guia Orientativo da ANPD, 02/02/2024). Todo envio carrega saída em um clique e o pedido de descadastro é atendido. A ressalva que tratamos como restrição de projeto vem do mesmo guia: dado vindo de fonte pública ou de terceiro enfraquece a expectativa legítima do titular, então o teste de balanceamento precisa estar escrito antes do disparo, não depois.","en":"For B2B contact in Brazil the legal basis is legitimate interest, which requires no prior consent provided the purpose is documented, the data minimised and opting out easy (LGPD art. 7, IX; ANPD guidance, 02 Feb 2024). Every send carries a one-click exit and opt-out requests are honoured. The caveat we treat as a design constraint comes from the same guidance: data drawn from public sources or third parties weakens the data subject's reasonable expectation, so the balancing test has to be written before the first send, not after.","fonte":"LGPD art. 7º, IX; Guia Orientativo da ANPD, 02/02/2024","tags":["lgpd","juridico","motor"],"encaminha":"nao","secao":""},{"id":"descadastro","perguntas":["como saio da lista?","quero parar de receber e-mail de vocês","descadastro","me tira da lista","unsubscribe","opt out","como cancelo o contato","how do I unsubscribe","is there an opt-out link"],"pt":"Todo e-mail traz link de descadastro em um clique, e responder ao próprio e-mail pedindo a saída também resolve. Isso não é cortesia: o cancelamento em um clique é exigência técnica para quem envia acima de 5.000 mensagens por dia (documentação do Gmail para remetentes, 2026) e é uma das condições que sustentam o legítimo interesse na LGPD. Se o link falhar, fale com o fundador, porque descadastro quebrado é falha nossa, não do destinatário.","en":"Every email carries a one-click unsubscribe link, and simply replying to ask to be removed works too. This is not a courtesy: one-click cancellation is a technical requirement for senders above 5,000 messages a day (Gmail sender documentation, 2026) and it is one of the conditions that hold up legitimate interest under the LGPD. If the link fails, talk to the founder, because a broken opt-out is our fault, not the recipient's.","fonte":"Documentação do Gmail para remetentes, 2026; LGPD art. 7º, IX","tags":["lgpd","descadastro","operacao"],"encaminha":"falar-com-fundador","secao":"#contato"},{"id":"mercado-outbound","perguntas":["existe mercado pra essa capacidade?","quem compraria o motor?","tamanho do mercado de prospecção","outbound tem mercado no brasil?","isso vira empresa grande?"],"pt":"Existe, e é menor do que costuma ser vendido, por isso usamos âncoras de baixo para cima. A maior empresa de outbound puro do Brasil foi vendida inteira por R$ 51 milhões (fato relevante de companhia aberta, 2023, Exact Sales), e a cauda self-serve global onde de fato se compete soma cerca de US$ 92 milhões de ARR (Lemlist, Instantly e Smartlead, 2024-2025). Que a PME brasileira paga por software de vendas está provado em outro lugar: R$ 643 milhões de ARR auditado na RD Station (TOTVS, release do 4T25). A ambição honesta aqui é uma empresa de R$ 5 a 10 milhões por ano, não um unicórnio.","en":"It exists, and it is smaller than it is usually sold as, which is why we anchor bottom-up. Brazil's largest pure-outbound company was sold whole for R$51 million (public-company material fact, 2023, Exact Sales), and the global self-serve tail where competition actually happens adds up to roughly US$92 million in ARR (Lemlist, Instantly and Smartlead, 2024-2025). That Brazilian SMBs pay for sales software is proven elsewhere: R$643 million in audited ARR at RD Station (TOTVS, Q4 2025 release). The honest ambition here is a R$5 to 10 million a year company, not a unicorn.","fonte":"Fato relevante 2023 (Exact Sales); ARR Lemlist/Instantly/Smartlead; TOTVS 4T25","tags":["mercado","outbound","ancoragem"],"encaminha":"nao","secao":""},{"id":"vao-vender-huntai","perguntas":["vocês vão vender o HuntAI?","dá pra contratar o motor?","posso comprar essa ferramenta?","quero usar o motor de vocês","will you sell HuntAI?","é produto comercial?"],"pt":"Hoje não. O HuntAI opera como canal interno da 3BRAIN, e vender a capacidade é direção declarada, não produto no ar. A razão de a frente empresa ser a escolhida é que prospectar é atividade permanente, então a receita se repete, ao contrário da frente candidato. Se você quer usar o motor, isso é conversa direta com o fundador: não existe preço fechado nem contrato-padrão.","en":"Not today. HuntAI runs as 3BRAIN's internal channel, and selling the capability is a stated direction, not a product in the market. The reason the company-facing front is the chosen one is that prospecting is a permanent activity, so the revenue repeats, unlike the job-seeker front. If you want to use the engine, that is a direct conversation with the founder: there is no fixed price and no standard contract.","fonte":"Posição declarada 3BRAIN","tags":["huntai","comercial","roadmap"],"encaminha":"falar-com-fundador","secao":"#motor"},{"id":"preco-huntai","perguntas":["quanto custa o HuntAI?","preço do huntai","quanto vocês cobrariam por isso?","quantos clientes pra 1 milhão no huntai?","how much would the engine cost?"],"pt":"R$ 1.290 por mês na Base 8k — 8.000 contatos verificados mais dois toques de IA —, com R$ 590 na Base 2k, R$ 2.490 na Base 20k e R$ 0,08 por contato excedente. A unidade é o contato verificado, não o envio, e a razão é de incentivo: contato é abundante, envio é a única coisa escassa aqui, e cobrar pelo envio faria os dois lados da mesa empurrarem justamente a variável que destrói a reputação do domínio. O envio gerenciado existe como linha opcional, a R$ 150 por mil. A R$ 15.480 por cliente/ano, com 70,4% de margem de contribuição, R$ 1 milhão de receita recorrente fica a 65 clientes de distância. Não há cliente pagante ainda: o preço está decidido, não praticado.","en":"R$1,290 a month for the 8k base — 8,000 verified contacts plus two AI passes — with R$590 for the 2k base, R$2,490 for the 20k base and R$0.08 per contact beyond it. The unit is the verified contact, not the send, and the reason is incentives: contacts are abundant, sends are the one scarce thing here, and charging per send would have both sides of the table pushing the exact variable that destroys domain reputation. Managed sending exists as an optional line, at R$150 per thousand. At R$15,480 per client per year, on a 70.4% contribution margin, R$1 million of recurring revenue sits 65 clients away. There is no paying customer yet: the price is settled, not practised.","fonte":"Decisão de preço 3BRAIN, ago/2026","tags":["preco","huntai","premissa"],"encaminha":"falar-com-fundador","secao":"#receita"},{"id":"base-de-contatos","perguntas":["de onde vem a base de contatos?","vocês compraram lista?","como montaram a base","277 mil contatos, de onde?","where does the list come from?","a base é válida?"],"pt":"Do registro público, e de 15 registros ao todo: 2.126.099 e-mails únicos. A fatia da saúde são 518.604 estabelecimentos varridos do CNES, de onde saíram 275.919 e-mails únicos contados uma vez só nos dois arquivos — endereço encontrado em 53 de cada 100 estabelecimentos (operação HuntAI sobre CNES/DATASUS, 2026). Nada foi comprado de corretor de lista. Duas ressalvas ditas por nós: a validade dos endereços ainda não foi verificada um a um, e de cada 100 contatos B2B, 22 a 30 mudam de cargo ou de empresa em 12 meses (HubSpot 22,5%; ZoomInfo 25 a 30%, 2026), ou seja, base parada é passivo com prazo de validade, não ativo.","en":"From public registries, 15 of them, comes a base of 2,126,099 unique e-mails. The healthcare slice is 518,604 establishments swept from CNES, yielding 275,919 unique e-mails counted once across both files — an address found for 53 out of every 100 establishments (HuntAI operation over CNES/DATASUS, 2026). Nothing was bought from a list broker. Two caveats we state ourselves: address validity has not yet been verified one by one, and 22 to 30 of every 100 B2B contacts change role or company within 12 months (HubSpot 22.5%; ZoomInfo 25 to 30%, 2026), so a static base is a liability with an expiry date, not an asset.","fonte":"Operação HuntAI sobre CNES/DATASUS, 2026; HubSpot e ZoomInfo, 2026","tags":["base","dados","ressalva"],"encaminha":"nao","secao":""},{"id":"riscos-do-canal","perguntas":["qual o maior risco desse canal?","o que pode dar errado no motor?","riscos do huntai","e se bloquearem vocês?","platform risk do canal","qual o defeito disso"],"pt":"Três, e preferimos levantá-los nós. Primeiro, o portão de entregabilidade: acima de 10 devoluções a cada 100 a AWS pausa o envio, e nenhum texto e nenhum preço abrem uma conta pausada (AWS SES, 2026). Segundo, a base decai sozinha, com 22 a 30 de cada 100 contatos B2B mudando em 12 meses (HubSpot/ZoomInfo, 2026). Terceiro, onde o canal encosta em plataforma de terceiro a regra é contrato, não lei, e por isso o motor trabalha abaixo de limites medidos em operação, não de palpite.","en":"Three, and we would rather raise them ourselves. First, the deliverability gate: above 10 bounces per 100 AWS suspends sending, and no copy and no price open a suspended account (AWS SES, 2026). Second, the base decays on its own, with 22 to 30 of every 100 B2B contacts changing within 12 months (HubSpot/ZoomInfo, 2026). Third, wherever the channel touches a third-party platform the rule is contract, not statute, which is why the engine runs below limits measured in live operation rather than below a guess.","fonte":"AWS SES, 2026; HubSpot e ZoomInfo, 2026","tags":["risco","entregabilidade","plataforma"],"encaminha":"ver-secao","secao":"#motor"},{"id":"fundadores-quem","perguntas":["quem são os fundadores?","quem está por trás da 3BRAIN?","fundadores","quem criou o SAVI?","who are the founders?","quem toca a empresa","time fundador"],"pt":"São dois. Fábio Binho da Silva é técnico de enfermagem (COREN-SC 1305197), com oito anos de UTI, emergência, longa permanência, laboratório e resgate pré-hospitalar antes da primeira linha de código, e o SAVI saiu do prontuário que ele mesmo preenchia no fim do turno. Bruno Nobru é técnico em contabilidade, com oito anos de barbearia e dono da Nobru's Barbershop, e o BarberGO saiu da cadeira parada e da contratação por indicação que ele vivia do lado de quem contrata. Nenhum dos dois produtos nasceu de pesquisa de mercado, e é essa a parte que um concorrente não consegue contratar.","en":"Two. Fábio Binho da Silva is a licensed nurse technician (COREN-SC 1305197) with eight years across ICU, emergency, long-term care, laboratory and pre-hospital rescue before his first line of code, and SAVI came out of the chart he filled in himself at the end of a shift. Bruno Nobru is an accounting technician with eight years in barbering and owner of Nobru's Barbershop, and BarberGO came out of the idle chair and the hire-by-referral routine he lived on the employer side. Neither product started as market research, and that is the part a competitor cannot hire.","fonte":"COREN-SC 1305197; biografias declaradas pelos fundadores","tags":["time","fundadores"],"encaminha":"ver-secao","secao":"#time"},{"id":"tempo-juntos","perguntas":["há quanto tempo vocês trabalham juntos?","vocês se conhecem há quanto tempo?","tempo de sociedade","quando viraram sócios?","how long have you worked together"],"pt":"Nove anos de convivência antes de existir sociedade (declarado pelos fundadores). A empresa é de abril/2026 (CNPJ 66.447.959/0001-88), então a relação entre os dois é bem mais velha que ela. Isso importa por um motivo prático: a briga de sócio que costuma matar empresa de dois fundadores aparece na primeira vez que o dinheiro aperta, e esta não é a primeira vez que estes dois passam aperto juntos. Não é garantia, é histórico.","en":"Nine years of knowing each other before there was any partnership (stated by the founders). The company dates from April 2026 (CNPJ 66.447.959/0001-88), so the relationship is far older than the company. That matters for a practical reason: the co-founder fallout that kills two-person startups tends to arrive the first time money gets tight, and this is not the first tight spot these two have been through together. It is not a guarantee, it is a track record.","fonte":"Declarado pelos fundadores; CNPJ 66.447.959/0001-88, abril/2026","tags":["time","fundadores","risco"],"encaminha":"nao","secao":""},{"id":"tamanho-time","perguntas":["quantas pessoas são?","tamanho do time","quantos funcionários vocês têm?","vocês têm equipe?","how many people are you","tem funcionário?","quantas pessoas trabalham aí","vocês estão contratando","quantos vocês são","estão contratando pessoas","vocês contratam pessoas","how many people work at 3brain"],"pt":"Duas: os dois fundadores, sem funcionário (3BRAIN, ago/2026). Não há agência, freelancer fixo nem organograma maior por trás. É o estágio real da empresa, e preferimos dizer isso a inflar estrutura que a diligência derruba em uma pergunta.","en":"Two: the two founders, no employees (3BRAIN, Aug/2026). There is no agency, no standing contractor and no larger org chart behind it. That is the company's actual stage, and we would rather say so than inflate a structure that one diligence question would knock down.","fonte":"3BRAIN, composição do time, ago/2026","tags":["time","empresa","estagio"],"encaminha":"nao","secao":""},{"id":"quem-escreve-codigo","perguntas":["quem escreve o código?","quem desenvolve?","vocês terceirizam desenvolvimento?","tem dev contratado?","who writes the code","desenvolvimento é interno?"],"pt":"Um dos dois fundadores, o Fábio, escreve o código dos três produtos. Não há agência, freelancer nem fábrica de software no meio. A vantagem é distância curta: quem viveu o problema, quem especifica e quem constrói são a mesma pessoa, então uma correção vista em campo vira produção em horas, não em trimestres. A desvantagem é evidente, e está respondida na pergunta sobre depender de uma pessoa só.","en":"One of the two founders, Fábio, writes the code for all three products. No agency, no freelancer, no outsourced dev shop in between. The upside is short distance: the person who lived the problem, the person who specifies it and the person who builds it are the same, so a fix seen in the field reaches production in hours rather than quarters. The downside is obvious, and it is answered under the single-person dependency question.","fonte":"Estrutura declarada da 3BRAIN, 2026","tags":["time","engenharia","risco"],"encaminha":"nao","secao":""},{"id":"dependencia-uma-pessoa","perguntas":["vocês não dependem de uma pessoa só?","e se o dev sumir?","bus factor","risco de pessoa chave","key person risk","e se ele ficar doente","como vocês reduzem essa dependência","what if the developer leaves","key person dependency","what is the bus factor"],"pt":"Dependem, sim, e essa é hoje a dependência mais concreta da empresa. O que existe contra ela é mecânico, não retórico: todo o código versionado, bateria de testes automatizada rodando a cada mudança, as regras clínicas escritas como regra de sistema com a norma que as originou nomeada ao lado, e um protocolo em que cada bug real vira trava permanente para que a mesma espécie não volte. Isso encurta o tempo de retomada por outra pessoa, mas não zera o risco, porque parte do contexto ainda mora com quem escreveu. O primeiro funcionário é uma das primeiras linhas de uso de capital justamente por isso.","en":"Yes, and it is currently the company's most concrete dependency. What stands against it is mechanical, not rhetorical: all code under version control, an automated test suite running on every change, clinical rules written as system rules with the regulation that produced each one named beside it, and a protocol where every real bug becomes a permanent guard so the same species never returns. That shortens how long a second person needs to take over, but it does not zero the risk, because part of the context still lives with the person who wrote it. The first hire is one of the first planned uses of capital for exactly this reason.","fonte":"Prática de engenharia declarada da 3BRAIN, 2026","tags":["risco","time","engenharia"],"encaminha":"nao","secao":""},{"id":"se-um-sair","perguntas":["o que acontece se um dos dois sair?","e se vocês brigarem?","risco de saída de sócio","what if a founder leaves","e se um desistir","tem acordo de sócios?"],"pt":"Vale separar os dois casos, porque não são simétricos. Se sair o lado de operação, o BarberGO perde o acesso e a leitura de barbearia que o originaram, já que o produto está publicado mas quem valida o que ele faz é aquele lado. Se sair o lado de engenharia, o desenvolvimento dos três para até haver substituição, e esse é o risco de pessoa-chave, o mais caro dos dois. Os termos formais de saída e a estrutura societária são conversa de mesa, com documento à vista, não linha de página pública.","en":"Worth splitting the two cases, because they are not symmetric. If the operations side leaves, BarberGO loses the access and the barbershop judgment that created it, since the product is published but that side is who validates what it does. If the engineering side leaves, development on all three stops until a replacement is in place, and that is the key-person risk, the costlier of the two. Formal exit terms and the ownership structure are a conversation with documents on the table, not a line on a public page.","fonte":"Estrutura declarada da 3BRAIN, 2026","tags":["risco","socios","time"],"encaminha":"falar-com-fundador","secao":"#time"},{"id":"situacao-juridica","perguntas":["vocês têm CNPJ?","qual a situação jurídica da empresa?","que tipo de empresa é a 3BRAIN?","inova simples","empresa aberta quando?","regime tributário","is the company incorporated"],"pt":"CNPJ 66.447.959/0001-88, aberto em abril/2026 sob o regime Inova Simples, com tributação pelo Simples Nacional. O Inova Simples tem uma consequência prática que o investidor precisa saber antes de perguntar: ele abre editais como os da FAPESC e fecha outros, já que a FINEP Mais Inovação veda Empresa Simples de Inovação e a Lei do Bem exige Lucro Real. Se a rodada exigir outro tipo societário, a conversão é assunto do fechamento, não impedimento.","en":"CNPJ 66.447.959/0001-88, incorporated in April 2026 under Brazil's Inova Simples regime, taxed under Simples Nacional. Inova Simples carries a practical consequence an investor should know before asking: it opens some public grants, such as FAPESC's, and closes others, since FINEP Mais Inovação excludes the Inova Simples vehicle and the Lei do Bem incentive requires the Lucro Real tax regime. If a round requires a different corporate vehicle, converting is a closing item, not an obstacle.","fonte":"Cadastro CNPJ 66.447.959/0001-88, abril/2026; regras FINEP e Lei do Bem","tags":["empresa","juridico","captacao"],"encaminha":"nao","secao":""},{"id":"marca-inpi","perguntas":["a marca está registrada?","tem INPI?","vocês registraram a marca 3BRAIN?","propriedade intelectual","patente","trademark registered?","tem patente?","do you have a trademark","is the brand registered"],"pt":"Não. O registro de marca no INPI é pendência aberta, sem depósito feito, então não existe número de processo para mostrar e a página não escreve marca registrada em lugar nenhum. A defesa da tese aqui não repousa em título de propriedade industrial: repousa no acesso ao setor e no dado de operação, que são o que um concorrente não compra pronto.","en":"No. The trademark filing with Brazil's INPI is an open pending item, not a filed application, so there is no case number to show and the word registered appears nowhere on this page. The defensibility argument here does not rest on an industrial property title: it rests on sector access and operating data, which is what a competitor cannot buy off the shelf.","fonte":"Situação de marca da 3BRAIN, ago/2026","tags":["juridico","risco","empresa"],"encaminha":"nao","secao":""},{"id":"sem-foto","perguntas":["por que não tem foto de vocês?","cadê a foto dos fundadores?","por que a página não mostra rosto?","sem foto","why no founder photos","quero ver quem são"],"pt":"Porque as fotos ainda não foram feitas, e a alternativa seria pôr banco de imagem no lugar do rosto de gente real, o que numa página que pede confiança custa mais caro que o espaço vazio. É o primeiro item da própria lista de pendências desta página, e vai ser resolvido com duas fotos simples, não com produção. Enquanto isso, o que identifica os fundadores está escrito e é conferível: COREN-SC 1305197, a barbearia do sócio e o CNPJ da empresa. Quem quiser rosto e voz antes disso, a conversa de 20 minutos resolve na hora.","en":"Because the photos have not been taken yet, and the alternative would be stock imagery standing in for real people, which on a page that asks for trust costs more than the empty space. It is the first item on this page's own list of gaps, and it will be closed with two plain photographs, not a production. Meanwhile, what identifies the founders is written down and checkable: COREN-SC 1305197, the co-founder's barbershop and the company's CNPJ. Anyone who wants a face and a voice before that, the 20-minute call solves it immediately.","fonte":"Lista de pendências da própria página, ago/2026","tags":["time","pagina","transparencia"],"encaminha":"falar-com-fundador","secao":"#contato"},{"id":"maior-risco","perguntas":["qual o maior risco do negócio?","o que pode dar errado?","qual o risco de vocês?","principal risco","biggest risk","o que te tira o sono","riscos","what is the biggest risk","what worries you most"],"pt":"Comercial, não técnico. Os dois produtos já saíram do papel, com o BarberGO publicado nas duas lojas e o SAVI rodando piloto sobre prontuário real, então a pergunta que sobra não é se este time constrói, e sim quantos compram e a que preço. Hoje o SAVI não tem preço aceito por um comprador real: a economia da empresa repousa numa premissa de preço, e é exatamente esse o risco que uma rodada resolve. O segundo maior é a dependência de uma pessoa para escrever o código.","en":"Commercial, not technical. Both products have shipped, with BarberGO published on both stores and SAVI running a pilot over a real medical record, so the remaining question is not whether this team can build it, but how many buy and at what price. SAVI has no price accepted by a real buyer yet: the company's economics rest on a price assumption, and that is precisely the risk a round resolves. The second largest is the dependency on one person to write the code.","fonte":"Estágio declarado dos produtos, ago/2026","tags":["risco","comercial","savi"],"encaminha":"falar-com-fundador","secao":"#time"},{"id":"risco-plataforma","perguntas":["vocês dependem de quem?","risco de plataforma","e se a API de IA subir de preço?","dependência de terceiros","e se a loja banir o app?","dependem da anthropic?","e se o firebase cair","what is your platform risk","what if the app stores ban you"],"pt":"A dependência é dupla e está declarada: modelos de IA de fornecedores externos, e as lojas de aplicativo mais a infraestrutura de nuvem. Contra a primeira, o app usa fornecedores de fabricantes diferentes com fallback em cascata, para que a queda ou o encarecimento de um não pare o produto. Contra a segunda não existe blindagem real, porque quem publica em loja opera sob regra alheia, e por isso a taxa de loja já entra na conta de margem que publicamos, em vez da versão mais bonita sem ela. No canal de e-mail vale o mesmo princípio: o motor trabalha abaixo de limites medidos, porque o provedor pausa quem passa do teto de devolução.","en":"The dependency is twofold and stated: AI models from outside vendors, plus the app stores and cloud infrastructure. Against the first, the app uses providers from different makers with cascading fallback, so one outage or price increase does not stop the product. Against the second there is no real shield, because publishing in a store means operating under someone else's rules, which is why the store fee is already inside the margin figures we publish, rather than the prettier version without it. The same principle governs the email channel: the engine runs below measured limits, because the provider suspends any sender above the bounce ceiling.","fonte":"Arquitetura declarada da 3BRAIN; política do provedor de e-mail, 2026","tags":["risco","plataforma","infra"],"encaminha":"nao","secao":""},{"id":"fosso-savi","perguntas":["o que impede alguém de copiar?","qual é o fosso?","e se um concorrente com dinheiro fizer igual?","defensabilidade","moat","vantagem competitiva","por que vocês e não a MV","what is your moat","what stops a funded competitor"],"pt":"Um concorrente capitalizado reescreve as telas em um trimestre, e admitimos isso em vez de inventar fosso. O que não se copia no mesmo prazo é o prontuário real de 2020 a 2026 que revelou o problema (base do piloto, extração ago/2026), a lista de contato do setor levantada do registro público com histórico de entrega, e o acesso de quem já esteve do outro lado do balcão, porque um técnico de enfermagem com COREN ativo entra numa casa de longa permanência de um jeito que um vendedor não entra. Essa vantagem cresce com tempo de operação, não com tamanho de rodada. Os registos foram **anonimizados antes do uso** — dado anonimizado está fora do alcance da LGPD (art. 12), e dizemos isto porque é a primeira coisa que a diligência pergunta sobre dado de saúde.","en":"A funded competitor rewrites the screens in a quarter, and we say so rather than inventing a moat. What does not copy on that timeline is the real 2020 to 2026 medical record that revealed the problem (pilot dataset, extracted Aug/2026), the sector contact list built from the public registry with delivery history, and the access of someone who has stood on the other side of the counter, because a nurse technician with an active licence walks into a long-term care home in a way a salesperson does not. That advantage compounds with operating time, not with round size. The records were **anonymised before use** — anonymised data falls outside the scope of Brazil's LGPD (art. 12), and we say so because it is the first thing due diligence asks about health data.","fonte":"Base do piloto do SAVI, ago/2026; base de contato levantada do CNES","tags":["risco","defensabilidade","savi"],"encaminha":"nao","secao":""},{"id":"ressalvas-publicas","perguntas":["por que vocês publicam as ressalvas dos próprios números?","por que mostrar o que está errado?","isso não enfraquece a página?","por que tanta ressalva","why publish caveats","vocês mesmos criticam seus números?","método"],"pt":"Porque quem descobre o furo depois cobra caro. Um número sem denominador, sem janela de tempo ou sem fonte não sobrevive à primeira pessoa que abre a fonte primária, e quando cai não cai sozinho: leva junto a credibilidade de todos os outros números da página. Por isso a ressalva vem colada ao número, dizendo qual é a amostra, o que ela não cobre e o que é conta nossa em vez de medição de terceiro. Um estudo que esconde a própria lacuna vale menos que um estudo curto.","en":"Because whoever finds the hole later charges a high price for it. A number with no denominator, no time window and no source does not survive the first person who opens the primary source, and when it falls it does not fall alone: it takes the credibility of every other number on the page with it. So the caveat sits right next to the number, stating what the sample is, what it does not cover, and what is our own arithmetic rather than a third-party measurement. A study that hides its own gap is worth less than a short study.","fonte":"Regra editorial da própria página","tags":["metodo","transparencia","numeros"],"encaminha":"ver-secao","secao":"#fontes"},{"id":"contato","perguntas":["como falo com vocês?","como marco uma demo?","quero ver funcionando","dá pra agendar uma conversa?","quero conversar com o fundador","book a demo","contato","agendar reunião","qual o email de contato","vocês têm email","tem whatsapp para falar com vocês","qual o telefone","como entro em contato","qual o e-mail de vocês","manda o e-mail","how do I contact you","how do I reach the founder","what is your email address","can I book a demo"],"pt":"Pelo botão Conversar com o fundador, de 20 minutos, nesta página. Quem atende é quem escreveu o código e passou oito anos preenchendo prontuário, sem time comercial no meio. Se mandar o contexto antes, ou seja, tipo de instituição, número de leitos ou residentes e qual sistema já roda aí, a conversa começa no assunto certo. Por e-mail, direto com o fundador: fabiocds.silva69@gmail.com ou fabiocds.silva69brasil@gmail.com.","en":"Through the Talk to the founder button, 20 minutes, on this page. The person on the call is the one who wrote the code and spent eight years filling in charts, with no sales team in between. If you send context beforehand, meaning type of institution, number of beds or residents, and which system already runs there, the conversation starts on the right subject. By e-mail, straight to the founder: fabiocds.silva69@gmail.com or fabiocds.silva69brasil@gmail.com.","fonte":"Canal de contato da própria página","tags":["contato","demo"],"encaminha":"falar-com-fundador","secao":"#contato"},{"id":"mercado-huntai","perguntas":["qual o mercado do huntai?","quantas empresas o huntai pode alcançar","tam do huntai","o huntai só serve saúde?","quem compra prospecção","how big is the HuntAI market?"],"pt":"Duas grandezas, e confundi-las é o erro clássico. ALCANCE: 10.607.110 organizações formais ativas no Brasil, todas com endereço em registro público (IBGE, CEMPRE 2024) — é o que o motor consegue extrair, e não tem nada de específico de saúde. COMPRADOR: 316.041 empresas com 10 ou mais pessoas ocupadas em setor que vende para outra empresa (mesma fonte). O corte em 10 pessoas não é arbitrário: abaixo disso não existe alguém cujo trabalho seja receber lead, o dono prospecta sozinho. Excluí o comércio por prudência, o que custa mais 200.274 empresas — se a segmentação do atacado for feita depois no nível de divisão CNAE, o número sobe. Saúde, onde provamos o método, é 36.984 dessas empresas.","en":"Two magnitudes, and confusing them is the classic error. REACH: 10,607,110 formal active organisations in Brazil, every one with an address on a public register (IBGE, CEMPRE 2024) — that is what the engine can extract, and there is nothing healthcare-specific about it. BUYER: 316,041 companies with 10 or more people employed, in sectors that sell to other businesses (same source). The 10-person cut is not arbitrary: below it nobody's job is to receive a lead, the owner prospects alone. I excluded retail for prudence, which costs another 200,274 companies — if wholesale is segmented later at CNAE division level, the number rises. Healthcare, where we proved the method, is 36,984 of them.","fonte":"IBGE, CEMPRE 2024 (tabela 9582 do SIDRA) · Mapa de Empresas jul/2026","tags":["mercado","huntai","tam"],"secao":"#motor"},{"id":"canais-huntai","perguntas":["quais canais o huntai usa?","tem whatsapp?","prospecta por linkedin?","por que multicanal é mais caro","does it do WhatsApp?"],"pt":"Três, e o preço maior do plano multicanal é repasse de custo, não posicionamento. E-MAIL: R$ 0,021 por toque, teto de 50 mil por mês na nossa infraestrutura e sem teto quando o cliente envia pelo próprio domínio — é o chão do produto e o único canal que escala sozinho. LINKEDIN: sem custo por mensagem, teto medido de 240 pedidos por hora (a 260 estrangula), e a bio devolve e-mail em 14% dos perfis com um único pedido, o que faz dele o canal que alimenta o e-mail em vez de competir com ele. WHATSAPP: R$ 0,32 por mensagem entregue, ou 15,6 vezes o custo do e-mail pelo mesmo contato, e exige a API oficial da Business Platform. É por isso que WhatsApp é camada paga à parte e nunca o padrão: quem compra três canais está comprando três faturas.","en":"Three, and the higher price of the multichannel plan is cost pass-through, not positioning. E-MAIL: US$0.004 per touch, a 50k/month ceiling on our own infrastructure and no ceiling when the client sends from their own domain — it is the floor of the product and the only channel that scales on its own. LINKEDIN: no per-message cost, a measured ceiling of 240 requests per hour (260 throttles), and the bio returns an e-mail on 14% of profiles from a single request, which makes it the channel that feeds e-mail rather than competing with it. WHATSAPP: US$0.0625 per delivered message, 15.6 times the cost of e-mail for the same contact, and it requires the official Business Platform API. That is why WhatsApp is a separately paid tier and never the default: buying three channels means buying three invoices.","fonte":"Custo próprio 3BRAIN (Elastic + MillionVerifier + Sonnet 5 Batch) · limite do LinkedIn medido em operação, ago/2026 · WhatsApp Business Platform: modelo por mensagem entregue confirmado na documentação oficial da Meta; a tarifa do Brasil é compilação de terceiros, não verificada na fonte primária","tags":["huntai","canais","whatsapp","linkedin","preco"],"secao":"#motor"},{"id":"dois-setores","perguntas":["por que saúde e beleza?","o que os dois setores têm a ver","por que essa dupla de fundadores","bisturi e navalha","why health and beauty?"],"pt":"Porque os dois fazem a mesma conta: mercado gigante, conta pequena, e nenhuma porta de entrada que se compre com anúncio. Somados são 1,9 milhão de negócios — 605 mil estabelecimentos de saúde (CNES jun/2026) e 1,3 milhão de CNPJ de beleza (Sebrae/Receita 2026) — ou 1 em cada 13 CNPJ ativo do país. E os dois são estruturalmente impossíveis de vender por equipe enterprise: em beleza existem 226 empresas com 20 pessoas ou mais no Brasil inteiro (IBGE, PAS 2023), e em saúde só 1 em cada 19 empresas do ramo tem porte que compra software. Esse mercado não ficou no papel por descuido: ficou porque a conta de ir até ele nunca fechou — vender de porta em porta custa mais do que a porta paga. Só chega nele quem vai sem vendedor, pela tela que o dono já abre todo dia, e quem já esteve do lado de dentro para saber o que pedir: um técnico de enfermagem e um dono de barbearia entram nos dois pela porta de serviço.","en":"Because both run the same arithmetic: an enormous market, a small account, and no way in that money can buy. Together they are 1.9 million businesses — 605,000 healthcare facilities (CNES Jun/2026) and 1.3 million beauty businesses (Sebrae/Receita 2026) — or 1 in every 13 active companies in the country. And both are structurally impossible to sell through an enterprise team: beauty has 226 companies with 20 people or more in all of Brazil (IBGE, PAS 2023), and in healthcare only 1 in every 19 companies in the field has the size to buy software. This market was not left on paper by oversight: it was left there because the cost of reaching it never added up — selling door to door costs more than the door pays. The only way in is without a salesperson, through the screen the owner already opens every day, and having been on the inside to know what to ask for: a nurse technician and a barbershop owner walk into both through the service door.","fonte":"CNES/DATASUS jun/2026 · Agência Sebrae de Notícias sobre base da Receita Federal, 2026 · IBGE, PAS 2023 e CEMPRE 2024 · Mapa de Empresas jul/2026","tags":["mercado","time","savi","barbergo"],"secao":"#time"},{"id":"motor-numeros","secao":"#motor","tags":["huntai","motor","numeros"],"perguntas":["quantos contatos voces tem","qual o tamanho da base","numeros do motor","o que o motor ja fez","how big is your list","engine numbers"],"pt":"O retrato medido em 23/08/2026: **2.126.099 e-mails únicos** extraídos de 15 registros públicos, **240.314 vagas colhidas** das quais **79.828 vieram com o e-mail de quem contrata**, **58 adaptadores que submetem** candidatura (23 deles sistemas de recrutamento abertos por HTTP puro), **12.368 candidaturas** enviadas de 26.811 tentativas, **49.763 e-mails** disparados e **86 empregadores distintos** com conversa de entrevista. Uma contratação real fecha a ponta, rastreada até a caixa exata.","en":"The picture measured on 23 Aug 2026: **2,126,099 unique e-mails** extracted from 15 public registers, **240,314 job postings harvested** of which **79,828 came with the hiring employer's e-mail**, **58 submitting adapters** (23 of them applicant-tracking systems opened by raw HTTP), **12,368 applications** sent out of 26,811 attempts, **49,763 e-mails** dispatched and **86 distinct employers** in interview conversations. One real hire closes the chain, traced to the exact inbox.","fonte":"Ledgers da operação HuntAI, medidos em 23/08/2026"},{"id":"uniao-nao-soma","secao":"#motor","tags":["huntai","base","metodo"],"perguntas":["como contam os contatos","e soma ou uniao","tem contato repetido","por que nao 3,7 milhoes","do you double count","union or sum"],"pt":"Pela **união**, nunca pela soma. As 15 fontes somadas dão 3.782.070 endereços, mas **43,8% se repete entre elas** - o mesmo CNPJ entra pela Receita Federal e pelo CNES. Contar a soma inflaria a base em **1,6 milhão de contatos que não existem**. O número que publicamos, 2.126.099, é a união com duplicata removida. É o tipo de escolha que separa número medido de número de apresentação.","en":"By **union**, never by sum. The 15 sources add up to 3,782,070 addresses, but **43.8% overlaps between them** - the same company enters through both the tax registry and CNES. Counting the sum would inflate the base by **1.6 million contacts that do not exist**. The figure we publish, 2,126,099, is the de-duplicated union. It is the kind of choice that separates a measured number from a pitch number.","fonte":"Ledgers da operação HuntAI, medidos em 23/08/2026"},{"id":"vagas-com-email","secao":"#motor","tags":["huntai","vagas","extracao"],"perguntas":["de onde vem as vagas","quantas vagas voces tem","o anuncio traz e-mail","job postings with employer email","how many vacancies"],"pt":"**240.314 registros de vaga colhidos**, e o que importa neles: **79.828 trouxeram o e-mail do empregador junto do anúncio** - 74% no geral, 79% em tecnologia e **100% em saúde**. É o coração do motor: o anúncio identifica quem contrata **e** entrega como falar com ele, na mesma extração, sem intermediário e sem custo por lead. Ressalva contada: o total inclui portais que **proíbem contato no texto** - o OLX entrega 9.100 vagas e zero e-mails, e está somado assim.","en":"**240,314 job-posting records harvested**, and the part that matters: **79,828 carried the employer's e-mail alongside the ad** - 74% overall, 79% in tech and **100% in healthcare**. That is the heart of the engine: the posting identifies who is hiring **and** hands over how to reach them, in one pass, with no middleman and no cost per lead. Stated caveat: the total includes portals that **forbid contact details in the ad** - OLX yields 9,100 postings and zero e-mails, and is counted that way.","fonte":"Ledgers da operação HuntAI, medidos em 23/08/2026"},{"id":"cobertura-plataformas","secao":"#motor","tags":["huntai","plataformas","ats"],"perguntas":["em quantas plataformas voces enviam","quais ATS","como submetem candidatura","usam RPA ou robo","which platforms","how many integrations"],"pt":"**58 adaptadores que submetem** de verdade, e dentro deles **23 sistemas de recrutamento abertos por HTTP puro** - Greenhouse, Lever, Workable, Workday, iCIMS, SmartRecruiters, Personio, BambooHR e outros. **Sem nenhum serviço pago de automação e sem robô de tela**: robô de tela quebra a cada mudança de layout e cobra por hora; HTTP puro quebra só quando o formulário muda de campo, e o conserto é de minutos. Esta é a capacidade do motor, não o lote já enviado.","en":"**58 adapters that actually submit**, and within them **23 applicant-tracking systems opened by raw HTTP** - Greenhouse, Lever, Workable, Workday, iCIMS, SmartRecruiters, Personio, BambooHR and others. **No paid automation service and no screen robot**: a screen robot breaks on every layout change and bills by the hour; raw HTTP breaks only when a form changes a field, and the fix takes minutes. This is engine capacity, not the batch already sent.","fonte":"Inventário de adaptadores da operação HuntAI, 23/08/2026"},{"id":"candidaturas-conversao","secao":"#motor","tags":["huntai","candidaturas","conversao"],"perguntas":["quantas candidaturas","qual a taxa de sucesso","quantas tentativas","por que algumas falham","application success rate","how many applications were sent","what is the application conversion rate"],"pt":"**12.368 candidaturas enviadas de 26.811 tentativas registradas - 46,1%.** O que falha não é mistério: formulário que mudou de campo entre a colheita e o envio, e vaga fechada no intervalo. Os canais mais produtivos foram formulário genérico (4.018), Trabalha Brasil (2.730), ATS direto (945), Indeed (866) e rotas do LinkedIn (864). O número antigo de 8.615 que circulava era só o lote de Santa Catarina e está **desatualizado**.","en":"**12,368 applications sent out of 26,811 logged attempts - 46.1%.** What fails is no mystery: forms whose fields changed between harvest and submission, and postings closed in the meantime. The most productive channels were generic forms (4,018), Trabalha Brasil (2,730), direct ATS (945), Indeed (866) and LinkedIn routes (864). The older figure of 8,615 that circulated covered only the Santa Catarina batch and is **out of date**.","fonte":"Ledgers da operação HuntAI, medidos em 23/08/2026"},{"id":"entrevistas-medidas","secao":"#motor","tags":["huntai","entrevistas","funil"],"perguntas":["quantas entrevistas","alguem respondeu","o motor gerou entrevista","qual o retorno real","how many interviews","did anyone reply"],"pt":"**154 mensagens de retorno em 86 empregadores distintos**, lidas no **corpo** de 2.881 mensagens pré-filtradas. A medição anterior olhava só o **assunto** e por isso subcontava: o convite mais comum chega como Re: Candidatura para X, com a marcação no corpo. Três famílias de falso positivo foram cortadas à mão - a própria carta do fundador devolvida no acuse de ticket, alerta de portal, e descrição de funil de ATS - e sem esse corte o número **dobrava**. Nenhuma das três saiu de regex: as três apareceram olhando a amostra.","en":"**154 reply messages across 86 distinct employers**, read in the **body** of 2,881 pre-filtered messages. The earlier measurement looked only at the **subject line** and therefore under-counted: the most common invitation arrives as Re: Application for X, with the marker in the body. Three families of false positive were removed by hand - the founder's own letter bounced back in a ticket acknowledgement, portal alerts, and ATS funnel descriptions - and without that cut the figure **doubled**. None of the three was found by regex: all three showed up by reading the sample.","fonte":"Varredura do corpo das mensagens, medida em 23/08/2026"},{"id":"entrevistas-portugal","secao":"#motor","tags":["huntai","portugal","achado"],"perguntas":["onde o motor funcionou melhor","por que Portugal","em que pais","geografia dos resultados","which country","why Portugal"],"pt":"**60 dos 86 empregadores são portugueses e apenas 2 são brasileiros.** O motor produziu entrevista **sobretudo em Portugal**, e a medição vinha olhando para o Brasil. Dois canais que não se falam apontam para o mesmo sítio: a varredura de e-mail e, por caminho independente, mais de 150 contatos profissionais portugueses no WhatsApp. **Ressalva que fica junto:** entre os 86 há endereços de gmail e outlook - recrutador escrevendo de conta pessoal -, então se dois forem da mesma empresa o total de empregadores distintos está um ou dois abaixo.","en":"**60 of the 86 employers are Portuguese and only 2 are Brazilian.** The engine produced interviews **mostly in Portugal**, while the measurement had been looking at Brazil. Two channels that do not talk to each other point the same way: the e-mail sweep and, independently, more than 150 Portuguese professional contacts on WhatsApp. **Caveat kept alongside:** among the 86 there are gmail and outlook addresses - recruiters writing from personal accounts - so if two belong to the same company the distinct-employer total is one or two lower.","fonte":"Varredura do corpo das mensagens, medida em 23/08/2026"},{"id":"contratacao-imas","secao":"#motor","tags":["huntai","contratacao","atribuicao"],"perguntas":["a contratacao foi real","como sabem que veio de voces","qual a prova","atribuicao","was the hire real","how do you attribute it"],"pt":"**Auxiliar de laboratório, no laboratório do hospital infantil do IMAS, em São José/SC**, cerca de 30 dias depois do início do lote. Veio por **e-mail, não por plataforma**: a caixa é nominal de setor, o envio saiu em 14/08 às 20h55, e os 13 ledgers de plataforma têm **zero** IMAS, o que descarta o resto. Não é provavelmente veio daí: é o endereço, a data e a hora. **É o achado que corrige o método:** aquele contato estava na faixa C, 5,7% da fila, que o corte de qualidade teria excluído.","en":"**Laboratory assistant, at the children's hospital laboratory of IMAS, in Sao Jose/SC**, about 30 days after the batch began. It came through **e-mail, not a platform**: the inbox is a named department address, the send went out on 14 Aug at 20:55, and the 13 platform ledgers contain **zero** IMAS, which rules out the rest. It is not it probably came from there: it is the address, the date and the time. **And it is the finding that corrects the method:** that contact sat in tier C, 5.7% of the queue, which the quality filter would have excluded.","fonte":"Ledgers da operação HuntAI e caixa por IMAP, 23/08/2026"},{"id":"custo-unitario-motor","secao":"#motor","tags":["huntai","custo","margem"],"perguntas":["quanto custa rodar isso","qual o custo por contato","quanto gastam por mes","custo por candidatura","unit cost","how much does it cost to run","o que rende uma base de 8 mil","quantas reunioes por mes o motor entrega","quanto eu recebo por mes","what does an 8k base yield"],"pt":"**Cerca de US$ 0,0015 por candidatura e US$ 0,000009 por contato extraído.** O motor inteiro roda com **três assinaturas, nenhuma acima de US$ 19 por mês** - Elastic Email no plano Starter, proxies e o domínio. O preenchimento de formulário custa **quase zero de modelo de linguagem**, porque um livro de respostas cobre 86% das perguntas de triagem sem chamar IA. É por isso que a comparação com equipe de vendas não é apertada: é de outra ordem de grandeza. A conta fechada de um cliente com base de 8 mil: **R$ 662 (US$ 128) de custo** contra **R$ 1.690/mês (US$ 327)** de preço, que rendem 16 mil e-mails, **73 respostas** e **2,55 reuniões** por mês. O estoque não vence: um canal só acrescenta **R$ 2.400/mês (US$ 464)** de base vendável, 12× a taxa de reposição. Já executado pelo motor: **62.131 ações**.","en":"**About US$ 0.0015 per application and US$ 0.000009 per extracted contact.** The whole engine runs on **three subscriptions, none above US$ 19 a month** - Elastic Email Starter, proxies and the domain. Filling in forms costs **almost nothing in language-model calls**, because an answer book covers 86% of screening questions without calling AI. That is why the comparison with a sales team is not close: it is a different order of magnitude. The closed math for a client with an 8k base: **US$ 128 in cost** against **US$ 327/month** in price, yielding 16k e-mails, **73 replies** and **2.55 meetings** per month. Inventory does not expire: one channel alone adds **US$ 464/month** of sellable base, 12× the replacement rate. Already executed by the engine: **62,131 actions**.","fonte":"Custo próprio medido, ago/2026"},{"id":"entrega-email","secao":"#motor","tags":["huntai","email","entrega"],"perguntas":["a entrega e boa","quantos e-mails chegam","taxa de reclamacao","voces sao spam","complaint rate","what is your email delivery rate","how many emails were delivered"],"pt":"Em agosto de 2026 foram **24.518 enviados, 21.920 entregues (89,4%)** e **2 reclamações de spam - 0,008%**, que é **12 vezes abaixo do limite de 0,10%** que faz provedor suspender remetente. A reclamação é a métrica que derruba operação de e-mail, e é justamente a que está sadia. **Ressalva:** a entrega de **julho é desconhecida** - o provedor anterior recebia a devolução no lugar da gente, e só de agosto em diante há medição.","en":"In August 2026 there were **24,518 sent, 21,920 delivered (89.4%)** and **2 spam complaints - 0.008%**, which is **12 times below the 0.10% threshold** that gets a sender suspended. Complaint rate is the metric that kills an e-mail operation, and it is exactly the one that is healthy. **Caveat:** July's delivery is **unknown** - the previous provider received the bounces instead of us, and measurement only exists from August onward.","fonte":"API do Elastic Email, medida ao vivo em 22/08/2026"},{"id":"devolucao-autopsia","secao":"#motor","tags":["huntai","devolucao","lista"],"perguntas":["a lista esta velha","quantos e-mails voltam","bounce","devolucao","a base e boa","how bad are your bounces"],"pt":"A devolução de agosto foi de 10,5%, e a autópsia de 1.890 devoluções diz de quem é a culpa: **37% é reputação do nosso IP** (endereço compartilhado em lista de bloqueio), 11% é caixa cheia do destinatário, e **52% é caixa morta, o que dá cerca de 4,0% da campanha**. Ou seja: **a lista em si está em ~4% de endereço morto**, que é saudável - o resto é problema de IP, e problema de IP se resolve com IP próprio, não com lista nova.","en":"August bounces ran at 10.5%, and the autopsy of 1,890 bounces says where the fault lies: **37% is our own IP reputation** (a shared address on a blocklist), 11% is a full recipient mailbox, and **52% is a dead mailbox, which works out to about 4.0% of the campaign**. In other words: **the list itself sits at ~4% dead addresses**, which is healthy - the rest is an IP problem, and an IP problem is solved with a dedicated IP, not with a new list.","fonte":"Autópsia de devolução da operação HuntAI, 15/08/2026"},{"id":"portao-envio","secao":"#motor","tags":["huntai","operacao","risco"],"perguntas":["voces estao enviando agora","por que pararam","o envio esta ativo","are you sending now","is the channel running"],"pt":"O envio está **pausado por decisão nossa**, não por suspensão: agosto fechou em 10,5% de devolução contra um **teto interno de 8%**, e a regra é parar antes de o provedor parar por nós. A conta segue **ativa, com reputação 96,88**. Vale o que isso diz do método: o portão é nosso e mais apertado que o do mercado, porque reputação de remetente demora meses para recuperar e horas para perder.","en":"Sending is **paused by our own decision**, not by suspension: August closed at 10.5% bounces against an **internal ceiling of 8%**, and the rule is to stop before the provider stops for us. The account remains **active, with a 96.88 reputation**. What that says about the method matters: the gate is ours and tighter than the market's, because sender reputation takes months to rebuild and hours to lose.","fonte":"Operação HuntAI e painel do Elastic Email, ago/2026"},{"id":"ressalva-clique","secao":"#fontes","tags":["ressalva","metrica","huntai"],"perguntas":["qual a taxa de clique","quantos clicaram","engajamento do e-mail","click rate","how many clicked"],"pt":"**Não usamos essa métrica, e a razão importa.** Foram 1.173 cliques para 1.521 aberturas - **77% de quem abriu clicou**. Campanha humana fica entre 5% e 15%. Setenta e sete por cento é a assinatura de **varredor de segurança**: o antivírus corporativo abre a mensagem e visita todo link antes de entregar, e hospital e clínica têm isso ligado por padrão. Citar 5,4% de clique como interesse humano seria um número que **cai no primeiro investidor que perguntar como foi medido**.","en":"**We do not use that metric, and the reason matters.** There were 1,173 clicks against 1,521 opens - **77% of those who opened clicked**. A human campaign runs between 5% and 15%. Seventy-seven per cent is the signature of a **security scanner**: the corporate antivirus opens the message and visits every link before delivering it, and hospitals and clinics have that on by default. Quoting a 5.4% click rate as human interest would be a number that **collapses with the first investor who asks how it was measured**.","fonte":"API do Elastic Email, medida ao vivo em 22/08/2026"},{"id":"ressalva-aberturas","secao":"#fontes","tags":["ressalva","metrica","huntai"],"perguntas":["qual a taxa de abertura","quantos abriram","open rate","what is your open rate"],"pt":"**6,9% dos entregues, e isso é um piso, não um total.** A abertura é medida por pixel de imagem, e quem bloqueia imagem no cliente de e-mail nunca conta. O curioso é que **o mesmo par de números erra para os dois lados**: a abertura é subcontada por bloqueio de imagem, e o clique é superestimado por varredor de segurança. Por isso publicamos os dois com a ressalva, em vez de escolher o que fica bonito.","en":"**6.9% of delivered, and that is a floor, not a total.** Opens are measured by a tracking pixel, and anyone blocking images in their mail client never counts. The interesting part is that **the same pair of numbers errs in both directions**: opens are under-counted by image blocking, and clicks are over-counted by security scanners. That is why we publish both with the caveat, rather than picking the flattering one.","fonte":"API do Elastic Email, medida ao vivo em 22/08/2026"},{"id":"ressalva-whatsapp","secao":"#fontes","tags":["ressalva","whatsapp","metrica"],"perguntas":["e o WhatsApp","quantos contatos no WhatsApp","o canal de WhatsApp funciona","whatsapp results","how many whatsapp contacts do you have"],"pt":"Há **mais de 150 contatos profissionais distintos** contados nas conversas entre janeiro e agosto de 2026, quase todos portugueses - e é o canal com mais conversa humana de toda a operação. **Mas o número não é auditável e por isso não entra na página:** foi contado em captura de tela, não em exportação. Para virar número publicável precisa da exportação da conversa e da contagem no arquivo. **Não existe API para mensagem de conta pessoal** - a da Meta é só Business e só do momento da configuração em diante. E há a conta do canal: o WhatsApp alcança **8,7 milhões** de pequenos negócios, mas é camada paga à parte — custa **R$ 0,32 (US$ 0,062) por mensagem entregue** contra **R$ 0,021 (US$ 0,004) do e-mail**. Quem quer o canal onde se responde paga por ele, e a diferença é de quinze vezes.","en":"There are **more than 150 distinct professional contacts** counted in conversations between January and August 2026, almost all Portuguese - and it is the channel with the most human conversation in the whole operation. **But the figure is not auditable and therefore does not go on the page:** it was counted from screenshots, not from an export. To become publishable it needs the conversation export and a count from the file. **There is no API for personal-account messages** - Meta's is Business-only and only from the moment it is set up. And there is the channel math: WhatsApp reaches **8.7 million** small businesses, but it is a separately paid tier — it costs **US$ 0.062 per delivered message** against **US$ 0.004 for e-mail**. Whoever wants the channel where people reply pays for it, and the gap is fifteenfold.","fonte":"Contagem em captura de tela, 22/08/2026 - piso declarado"},{"id":"metricas-que-nao-usamos","secao":"#fontes","tags":["metodo","investidor","ressalva"],"perguntas":["quantos testes voces tem","quantas linhas de codigo","quantas telas","quantos downloads","quantos cadastrados","vanity metrics","which metrics do you refuse to publish","what about vanity metrics"],"pt":"Não publicamos **métrica de produto no lugar de métrica de mercado**, e essa é uma regra escrita. Ficam de fora: número de testes, cobertura, linhas de código, número de telas ou de rotas, quantidade de modelos de IA integrados, downloads, cadastrados sem uso diário, e gráfico cumulativo. São números que sobem sozinhos com o tempo e não dizem nada sobre quem paga. O que entra é o tamanho da **dor** com denominador, o tamanho do **mercado** contado de baixo para cima, e **quem paga**.","en":"We do not publish **product metrics in place of market metrics**, and that is a written rule. Left out: number of tests, coverage, lines of code, number of screens or routes, how many AI models are integrated, downloads, sign-ups without daily use, and cumulative charts. Those are numbers that rise on their own with time and say nothing about who pays. What goes in is the size of the **pain** with a denominator, the size of the **market** counted bottom-up, and **who pays**.","fonte":"Regra editorial 3BRAIN para material de investidor, ago/2026"},{"id":"ancora-into","secao":"#receita","tags":["savi","preco","ancora"],"perguntas":["como sabem que o preco esta certo","tem comparavel","quem ja paga isso","ancora de preco","price anchor","is there precedent","what does the government pay per bed","how does it compare to the UK"],"pt":"Existe uma âncora pública e verificável acima do nosso preço: o **contrato 200/2024 do INTO**, instituto federal, paga **R$ 166,13 por leito de UTI por mês** em vigilância clínica, por cinco anos, contratado por inexigibilidade de licitação. Nosso preço de **R$ 99 por leito está a 59,6% dessa âncora**. Isso vale mais que qualquer argumento de valor: **o comprador confere sozinho**, no Painel de Preços do governo, sem depender do que a gente diz.","en":"There is a public, verifiable anchor above our price: **contract 200/2024 of INTO**, a federal institute, pays **R$ 166.13 per ICU bed per month (US$ 32.13)** for clinical surveillance, over five years, contracted without tender. For comparison, the UK pays US$ 11 to US$ 12 per bed per month for equivalent clinical scope. Our price of **R$ 99 per bed (US$ 19) sits at 59.6% of that anchor**. That is worth more than any value argument: **the buyer can check it alone**, on the federal price portal, without relying on anything we say.","fonte":"Contrato 200/2024, INTO-MS, Painel de Preços do Governo Federal"},{"id":"savi-unidade-leito","secao":"#receita","tags":["savi","preco","modelo"],"perguntas":["por que cobram por leito","por que nao por usuario","qual a unidade de cobranca","why per bed","pricing unit"],"pt":"Por **leito, e todos eles, não só os ocupados**. Cobrar por usuário cria um incentivo que destrói o produto: a instituição racionaria login, e vigilância clínica só vale se **a equipe inteira registrar**. Um técnico sem acesso é um turno inteiro sem dado. Cobrar por leito também torna a conta previsível para o comprador, que já pensa o orçamento dele por leito, e não por cabeça.","en":"By **bed, and all of them, not only the occupied ones**. Charging per user creates an incentive that destroys the product: the institution would ration logins, and clinical surveillance only works if **the whole team records**. One technician without access is a whole shift without data. Per-bed pricing also makes the bill predictable for the buyer, who already thinks about their budget per bed rather than per head.","fonte":"Decisão de preço 3BRAIN, ago/2026"},{"id":"savi-segmentos","secao":"#savi","tags":["savi","mercado","segmento"],"perguntas":["para quem e o SAVI","e so para ILPI","vende para hospital","qual o alvo do SAVI","who is SAVI for","is it only for care homes","o savi e so para ILPI","savi serve para hospital","savi atende clinica","so lar de idosos","is SAVI only for care homes","quem é o cliente de vocês","quem compra o savi","publico alvo"],"pt":"**Serve qualquer instituição de saúde, porque todas precisam registrar.** O alvo maior são **hospitais e clínicas especializadas**; ILPI também, mas como cabeça de ponte, não como teto. A ordem de prioridade é essa: hospital geral e especializado, depois clínica especializada, depois ILPI, depois home care. E a que cresce é a clínica especializada: **119,2% em dez anos** contra 8,3% dos hospitais, contado no registro e não projetado. O piloto num lar de 38 residentes é a porta de entrada com prova em campo - **não é o mercado principal**, e confundir os dois foi um erro que já corrigimos mais de uma vez.","en":"**It serves any healthcare institution, because all of them have to record.** The main target is **hospitals and specialist clinics**; long-term care homes too, but as a bridgehead rather than a ceiling. The priority order is exactly that: general and specialist hospitals, then specialist clinics, then care homes, then home care. And the one that is growing is the specialty clinic: **up 119.2% in ten years** against 8.3% for hospitals, counted on the register rather than projected. The pilot in a 38-resident home is the way in with field proof - **it is not the main market**, and confusing the two is a mistake we have corrected more than once.","fonte":"Definição de mercado 3BRAIN, ago/2026; CNES/DATASUS jun/2026 e série dez/2015 a dez/2025","encaminha":"ver-secao"},{"id":"savi-ilpi-nao-paga","secao":"#receita","tags":["savi","margem","segmento"],"perguntas":["ILPI da dinheiro","quanto rende uma ILPI","por que hospital e nao ILPI","margem por segmento","care home economics","which segment pays best","is the nursing home the best segment"],"pt":"Números que mudaram a estratégia: a **2% de penetração**, clínica especializada rende cerca de **R$ 157 mil por ano** e ILPI cerca de **R$ 155 mil**. **Nenhum dos dois paga um executivo de contas**, que custa cerca de R$ 154.800 por ano. Hospital, na mesma penetração, rende de **R$ 1,1 a 3,0 milhões**. Pior: no preço atual a ILPI tem **contribuição negativa de cerca de R$ 32 por casa por mês** - cada casa a mais custa dinheiro. Por isso ILPI é prova, e hospital é negócio.","en":"Figures that changed the strategy: at **2% penetration**, a specialist clinic yields about **R$ 157k a year** and a care home about **R$ 155k**. **Neither pays for one account executive**, who costs about R$ 154,800 a year. A hospital, at the same penetration, yields **R$ 1.1m to 3.0m**. Worse: at the current price a care home has a **negative contribution of about R$ 32 per house per month** - each extra house costs money. That is why care homes are proof, and hospitals are the business.","fonte":"Conta própria 3BRAIN, premissas declaradas, ago/2026"},{"id":"savi-incerteza-leito","secao":"#savi","tags":["savi","risco","premissa"],"perguntas":["qual a maior incerteza do SAVI","leito de UTI ou leito comum","o que pode dar errado no preco","biggest unknown","qual a maior incerteza do preco do savi","o preco pode mudar muito","qual premissa pode quebrar","risco da conta do savi"],"pt":"A maior incerteza do modelo não é técnica, é **de unidade**: o hospital paga por **leito operacional** ou só por **leito de UTI**? A diferença move o valor de um contrato em **2,66 vezes** - e nenhuma conta de mercado sobrevive a essa faixa sem resposta. É a primeira pergunta a levar para as três primeiras instituições, e a resposta delas vale mais que qualquer estimativa nossa.","en":"The biggest uncertainty in the model is not technical, it is **the unit**: does a hospital pay per **operational bed** or only per **ICU bed**? The difference moves a contract's value by **2.66 times** - and no market calculation survives that range unanswered. It is the first question to take to the first three institutions, and their answer is worth more than any estimate of ours.","fonte":"Conta própria 3BRAIN, premissas declaradas, ago/2026"},{"id":"savi-modelo-ia","secao":"#savi","tags":["savi","ia","custo"],"perguntas":["que modelo de IA voces usam","qual IA roda o SAVI","e caro rodar a IA","custo de inferencia","which AI model","inference cost","how does the ai work","which model do you use","what llm is behind it","isso e so um chatgpt com outra roupa","e um wrapper de chatgpt","is it just a chatgpt wrapper"],"pt":"Modelo escolhido por **tarefa, não por reputação**: o julgamento clínico roda num modelo de raciocínio forte, e a extração de texto de imagem roda no modelo mais barato disponível, porque ler um documento não exige julgamento. O custo de modelo é a **maior despesa variável por cliente** do SAVI, e a decisão de qual modelo usar em cada etapa mexe mais na margem do que qualquer negociação de fornecedor. Nenhuma chave de API fica no aplicativo: a chamada sai sempre do nosso servidor.","en":"The model is chosen **by task, not by reputation**: clinical judgement runs on a strong reasoning model, and reading text from images runs on the cheapest available one, because reading a document does not require judgement. Model cost is the **largest variable cost per client** in SAVI, and deciding which model handles each step moves the margin more than any supplier negotiation. No API key lives in the app: the call always leaves from our own server.","fonte":"Arquitetura e conta de custo 3BRAIN, ago/2026"},{"id":"savi-piloto","secao":"#savi","tags":["savi","piloto","estagio"],"perguntas":["ja tem cliente","esta em uso","tem piloto","onde esta rodando","any pilot","do you have a pilot running","where is the pilot","what is the pilot status"],"pt":"Há um **piloto em campo num lar de longa permanência com 38 residentes**, que é onde o produto encontrou o problema real: o prontuário preenchido no fim do turno, com o que ficou de fora do papel. Não há operação comercial: o SAVI **ainda não foi vendido**. Chamar piloto de cliente é o tipo de enfeite que derruba a conversa toda quando o investidor pede o contrato.","en":"There is a **pilot in the field at a long-term care home with 38 residents**, which is where the product met the real problem: the chart filled in at the end of a shift, with whatever never made it onto the page. There is no commercial operation: SAVI **has not been sold yet**. Calling a pilot a customer is the kind of dressing-up that collapses the whole conversation when an investor asks for the contract.","fonte":"3BRAIN, ago/2026"},{"id":"capital-proprio","secao":"#receita","tags":["dinheiro","investidor","time","estagio"],"perguntas":["quanto voces ja colocaram do proprio bolso","quanto os fundadores investiram","de onde saiu o dinheiro ate agora","voces ja captaram alguma coisa","how much have the founders put in","is it bootstrapped"],"pt":"**Cerca de R$ 20 mil do próprio bolso**, mais o custo corrente de ferramentas, APIs, provedores e domínios. Não há capital de terceiros: tudo o que está no ar — o BarberGO publicado nas duas lojas, o motor do HuntAI a operar e o SAVI a rodar sobre prontuário real — foi construído com isso. O número é pequeno de propósito e conta uma coisa: **o custo de descobrir se funciona já foi pago**, e o que se pede a seguir não é para começar, é para escalar o que já anda.","en":"**About R$ 20,000 of our own money**, plus the running cost of tools, APIs, providers and domains. There is no outside capital: everything that is live — BarberGO published on both stores, the HuntAI engine operating and SAVI running on real medical records — was built with that. The figure is deliberately small and it says one thing: **the cost of finding out whether it works has already been paid**, and what we ask for next is not to start, it is to scale what already runs.","fonte":"Estado declarado da 3BRAIN, ago/2026","encaminha":"falar-com-fundador"},{"id":"ciclo-de-venda-savi","secao":"#savi","tags":["savi","venda","estagio","honestidade"],"perguntas":["qual o ciclo de venda de um hospital","quanto tempo leva para fechar uma instituicao","quanto demora do contato ate a assinatura","how long is the sales cycle","how long to close a hospital"],"pt":"**Não sabemos, porque ainda não vendemos nenhum** — e é assim que respondemos, em vez de citar uma média de mercado como se fosse nossa. A expectativa declarada é de um ciclo **curto**, e a razão é a unidade de compra: o SAVI entra por leito, com decisão de gestor de operação e não de comité de TI, e não substitui o sistema que já está instalado — compra que não exige troca de fornecedor não passa pelo processo longo. **Isto é expectativa, não medida**, e continua sendo expectativa até o primeiro contrato dizer o contrário.","en":"**We do not know, because we have not sold one yet** — and that is how we answer, rather than quoting a market average as if it were ours. The stated expectation is a **short** cycle, and the reason is the buying unit: SAVI enters per bed, decided by an operations manager rather than an IT committee, and does not replace the system already installed — a purchase that requires no vendor switch does not go through the long process. **This is an expectation, not a measurement**, and it stays an expectation until the first contract says otherwise.","fonte":"Estado declarado da 3BRAIN, ago/2026","encaminha":"falar-com-fundador"},{"id":"savi-responsabilidade","secao":"#savi","tags":["savi","risco","juridico","produto"],"perguntas":["quem responde se a IA errar um dado clinico","de quem e a responsabilidade se o savi errar","e se a IA sugerir algo errado","o savi decide alguma coisa sozinho","quem assina o que o savi produz","who is liable if the AI gets it wrong","does SAVI make clinical decisions"],"pt":"**O SAVI não decide nada.** Ele **sugere e estrutura o que recebe** — organiza o registo, aponta o que falta, devolve no formato certo. Quem decide e quem assina é sempre o profissional, como já é hoje sem ele. Se um dado sair errado, foi porque **alguém aprovou errado ou não conferiu**, e essa é exatamente a mesma responsabilidade que existe no papel. A diferença é que no papel o erro é invisível e aqui fica registado quem confirmou o quê. Dizemos isto antes de perguntarem porque é a primeira pergunta do jurídico de qualquer instituição, e porque produto de saúde que promete decidir sozinho é produto que não passa na porta.","en":"**SAVI decides nothing.** It **suggests and structures what it receives** — it organises the record, flags what is missing, returns it in the right format. The professional always decides and always signs, exactly as they do today without it. If a piece of data comes out wrong, it is because **someone approved it wrongly or did not check**, and that is precisely the same responsibility that already exists on paper. The difference is that on paper the error is invisible, and here it is recorded who confirmed what. We say this before being asked because it is the first question any institution's legal team raises, and because a health product that promises to decide on its own is a product that does not get through the door.","fonte":"Desenho do produto SAVI, ago/2026","encaminha":"nao"},{"id":"dois-setores-numeros","secao":"#time","tags":["mercado","numeros"],"perguntas":["qual o tamanho do mercado","quantas empresas","saude e beleza juntos","market size","how many businesses"],"pt":"Somados, **1,9 milhão de negócios**: 605 mil estabelecimentos de saúde e 1,3 milhão de CNPJ em beleza - **1 em cada 13 CNPJ ativo do país** está num dos dois setores. São os dois maiores serviços de mão do Brasil, e os dois crescem por motivos que ninguém controla: a beleza abriu **646 negócios por dia em 2025, alta de 18,5%**, e a saúde cresce pela demografia. **O mercado se abastece sozinho**, sem depender de ciclo econômico.","en":"Together, **1.9 million businesses**: 605,000 healthcare facilities and 1.3 million beauty companies - **1 in every 13 active companies in the country** sits in one of the two sectors. They are Brazil's two largest hands-on services, and both grow for reasons nobody controls: beauty opened **646 businesses a day in 2025, up 18.5%**, and healthcare grows through demographics. **The market restocks itself**, with no dependence on the economic cycle.","fonte":"IBGE CEMPRE 2024; Sebrae/Receita Federal 2026; CNES/DATASUS jun/2026"},{"id":"conta-pequena","secao":"#time","tags":["mercado","estrutura","estrategia"],"perguntas":["por que ninguem atende esse mercado","por que esta no papel ainda","qual a barreira","why is nobody there","why still on paper"],"pt":"Porque **vender de porta em porta custa mais do que a porta paga**. Em beleza, só **226 empresas no país inteiro** têm 20 pessoas ou mais; em saúde, só **1 em cada 19** tem porte que compra software. Não dá para sustentar equipe de vendas em cima disso - **é por isso que esse mercado continua no papel**, não por descuido. Quem entra tem que chegar **sem vendedor**, pela tela que o dono já abre todo dia, com custo de aquisição próximo de zero.","en":"Because **selling door to door costs more than the door pays**. In beauty, only **226 companies in the entire country** have 20 people or more; in healthcare, only **1 in every 19** is large enough to buy software. You cannot sustain a sales team on that - **which is why this market is still on paper**, not through neglect. Whoever gets in has to arrive **without a salesperson**, through the screen the owner already opens every day, at near-zero acquisition cost.","fonte":"IBGE PAS 2023; IBGE CEMPRE 2024"},{"id":"whatsapp-porta","secao":"#time","tags":["mercado","canal","whatsapp"],"perguntas":["por que WhatsApp","onde o comprador atende","como chegam no cliente","why whatsapp","where do buyers answer"],"pt":"**82% dos pequenos negócios do Brasil vendem pelo WhatsApp** - não por telefone, não por e-mail corporativo, não por anúncio. É a porta que a 3BRAIN abre e que o funil de ninguém alcança: ferramenta de vendas tradicional foi construída para caixa de entrada corporativa, e o dono de barbearia ou de clínica pequena não vive lá. **A pesquisa tem 8.200 entrevistados**, então não é impressão de mercado.","en":"**82% of Brazil's small businesses sell through WhatsApp** - not by phone, not by corporate e-mail, not through ads. It is the door 3BRAIN opens and nobody's funnel reaches: traditional sales tooling was built for the corporate inbox, and the owner of a barbershop or a small clinic does not live there. **The survey has 8,200 respondents**, so it is not a market impression.","fonte":"Sebrae, Pulso dos Pequenos Negócios, 12a edição"},{"id":"alcance-vs-comprador","secao":"#motor","tags":["mercado","metodo","tam"],"perguntas":["qual o mercado do motor","quantas empresas podem comprar","alcance ou comprador","reach vs buyer"],"pt":"Os dois números existem e **não são a mesma coisa**. Alcance: **10,6 milhões de organizações formais** no Brasil, todas com endereço em registro público. Comprador: **316.041 dessas empresas têm 10 ou mais pessoas e vendem para outra empresa**. Abaixo de dez, o dono prospecta sozinho e não compra ferramenta de prospecção. **Misturar alcance com comprador é o erro que infla mercado** - por isso publicamos os dois separados, e o comércio ficou de fora por prudência.","en":"Both numbers exist and **they are not the same thing**. Reach: **10.6 million formal organisations** in Brazil, every one with an address on a public register. Buyer: **316,041 of those have 10 or more people and sell to other businesses**. Below ten, the owner prospects alone and does not buy prospecting tooling. **Blending reach with buyer is the error that inflates a market** - which is why we publish the two separately, with retail excluded for prudence.","fonte":"IBGE CEMPRE 2024, comércio excluído: +200.274"},{"id":"custo-de-vendedor","secao":"#receita","tags":["mercado","custo","comparacao"],"perguntas":["por que nao contratar vendedor","quanto custa um SDR","vale mais a pena equipe de vendas","cost of a salesperson"],"pt":"Um profissional de prospecção com encargos custa entre **R$ 5,3 mil e R$ 6,2 mil por mês** para entregar de 10 a 20 reuniões - e um executivo de contas custa cerca de **R$ 154.800 por ano**. Contra isso, o nosso custo por comprador alcançado é de **R$ 0,008**. A comparação honesta não é essa, e sim **por reunião**: aí o motor empata com um vendedor mediano e **perde para um vendedor produtivo**. O que ele ganha não é no preço por reunião, é no **volume que um humano não alcança**. Levado a custo **por reunião**, com encargos calculados como salário médio × 1,65 a 2,00: um SDR mediano (10 reuniões/mês) sai a **R$ 674 a 817** (US$ 130 a 158) por reunião — empate técnico com o motor; um SDR produtivo (20 reuniões/mês) sai a **R$ 337 a 408** (US$ 65 a 79), e aí o motor perde. Dizemos as duas pontas: o canal próprio não vence em todo cenário. Em dólar, a mesma régua: contratar prospecção custa **US$ 1.020 a 1.200 por mês, por pessoa**.","en":"A prospecting professional with payroll costs runs **R$ 5.3k to R$ 6.2k a month** to deliver 10 to 20 meetings - and an account executive costs about **R$ 154,800 a year**. Against that, our cost per buyer reached is **R$ 0.008**. The honest comparison is not that one, though, it is **per meeting**: there the engine ties with a median salesperson and **loses to a productive one**. What it wins is not price per meeting, it is **volume a human cannot reach**. Reduced to cost **per meeting**, with payroll taxes computed as average salary × 1.65 to 2.00: a median SDR (10 meetings/month) comes to **US$ 130 to 158** per meeting — a technical tie with the engine; a productive SDR (20 meetings/month) comes to **US$ 65 to 79**, and there the engine loses. We state both ends: owning the channel does not win in every scenario. In dollars, the same rule: hiring prospecting costs **US$ 1,020–1,200 per month, per person**.","fonte":"Glassdoor Brasil e tabelas de encargos CLT; conta própria 3BRAIN"},{"id":"onde-roda-a-ia","secao":"#motor","tags":["tecnica","seguranca","ia"],"perguntas":["onde roda a IA","onde fica a chave","como voces protegem a chave","a chave esta no site","where does the AI run","api key security","onde ficam armazenados os dados","em que servidor isso roda"],"pt":"A chamada de IA sai de um **servidor próprio na Cloudflare**, nunca da página. A página é pública e qualquer um lê o código dela: chave que estiver ali está à vista de todos. O servidor guarda a chave, verifica de onde veio o pedido, aplica limite de uso e faz a cascata - se o modelo principal falhar, cai no segundo, e se os dois falharem a página responde pela base local. **Nenhuma dessas camadas cobra ao estourar: as três param.**","en":"The AI call leaves from **our own server on Cloudflare**, never from the page. The page is public and anyone can read its code: a key sitting there is a key in plain sight. The server holds the key, checks where the request came from, applies usage limits and runs the cascade - if the main model fails it drops to the second, and if both fail the page answers from its local base. **None of those layers bills on overage: all three simply stop.**","fonte":"Arquitetura 3BRAIN, ago/2026"},{"id":"assistente-como-funciona","secao":"#fontes","tags":["tecnica","assistente","metodo"],"perguntas":["como voce funciona","voce e um chatgpt","voce inventa resposta","de onde tira as respostas","how do you work","are you chatgpt"],"pt":"Sou uma **base curada com fonte**, e um modelo de linguagem que **só reformula o que ela já diz**. O mecanismo tem nome: **RAG** - a busca escolhe as entradas mais próximas da pergunta, e **só essas entradas viajam** como contexto para o modelo, que é instruído a não sair delas. É de propósito: modelo solto numa página de investidor **inventa número**, e esta página se sustenta em cada número ter fonte e denominador. Quando eu não sei, eu digo que não sei e encaminho para uma conversa.","en":"I am a **curated base with sources**, plus a language model that **only rephrases what the base already says**. The mechanism has a name: **RAG** - the search picks the entries closest to your question, and **only those entries travel** as context to the model, which is instructed not to stray from them. That is deliberate: a model running loose on an investor page **invents figures**, and this page stands on every number having a source and a denominator. When I do not know, I say so and route you to a conversation.","fonte":"Arquitetura do assistente 3BRAIN, ago/2026"},{"id":"stack-tecnica","secao":"#barbergo","tags":["tecnica","stack"],"perguntas":["que tecnologia usam","qual a stack","em que foi feito o app","e react native","what stack","tech stack"],"pt":"O BarberGO é **Flutter com Dart**, sobre Firebase - autenticação, banco em tempo real e armazenamento -, publicado nas duas lojas. **Não é React Native**, e documentação antiga que diz isso está errada. A camada de IA é servida por API, com a chave sempre no servidor. O motor de aquisição é Python puro sobre HTTP, sem serviço pago de automação. Quem escreve o código dos três é o próprio fundador técnico, o que mantém a distância entre ver um problema em campo e corrigi-lo em produção medida **em horas, não em trimestres**.","en":"BarberGO is **Flutter with Dart**, on Firebase - authentication, realtime database and storage -, published on both stores. **It is not React Native**, and older documentation saying so is wrong. The AI layer is served through an API, with the key always on the server. The acquisition engine is plain Python over HTTP, with no paid automation service. All three are written by the technical founder himself, which keeps the distance between spotting a problem in the field and fixing it in production measured **in hours, not quarters**.","fonte":"3BRAIN, ago/2026"},{"id":"preco-barbergo-plano","secao":"#barbergo","tags":["barbergo","preco","plano"],"perguntas":["vao aumentar o preco","o preco vai mudar","reajuste do barbergo","price increase","will pricing change","will the price go up","is there a price increase coming"],"pt":"O preço **público hoje** é Silver a R$ 14,90 e Gold a R$ 29,90 por mês, e é esse que vale para quem assina agora. Há um **reajuste decidido e ainda não publicado**, para R$ 29,90 e R$ 49,90, que eleva a margem de contribuição de 73% para 78% e **derruba o número de assinantes necessários para R$ 1 milhão de 4.296 para 2.322**. Enquanto não subir, o número que vale é o de hoje - **preço anunciado e preço cobrado têm de ser o mesmo**, sempre.","en":"The **price today** is Silver at R$ 14.90 and Gold at R$ 29.90 a month, and that is what applies to anyone subscribing now. There is a **decided but not yet shipped increase**, to R$ 29.90 and R$ 49.90, which lifts the contribution margin from 73% to 78% and **cuts the subscribers needed for R$ 1 million from 4,296 to 2,322**. Until it ships, the figure that counts is today's - **the advertised price and the charged price must be the same**, always.","fonte":"Preço público no app; decisão de preço 3BRAIN, ago/2026"},{"id":"porta-de-servico","secao":"#time","tags":["time","fosso","estrategia"],"perguntas":["por que voces dois","qual o diferencial do time","por que essa dupla","why you two","founder fit"],"pt":"Porque nos dois mercados **não se entra pela porta da frente**. Um técnico de enfermagem com nove anos de UTI, emergência e longa permanência sabe o que fica de fora do prontuário porque **já preencheu prontuário no fim do turno**. Um dono de barbearia com oito anos de casa própria sabe o que a cadeira parada custa porque **já fechou o mês com ela parada**. Nenhum dos dois produtos começou como pesquisa de mercado - e essa é a parte que um concorrente **não consegue contratar**.","en":"Because in both markets **you do not come in through the front door**. A nurse technician with nine years in ICU, emergency and long-term care knows what never makes it onto the chart because **he has filled in charts at the end of a shift**. A barbershop owner with eight years running his own place knows what an idle chair costs because **he has closed a month with it idle**. Neither product started as market research - and that is the part a competitor **cannot hire**.","fonte":"3BRAIN; COREN-SC 1305197"},{"id":"risco-copia","secao":"#porque","tags":["risco","concorrencia","fosso"],"perguntas":["e se copiarem","o que impede um concorrente","qual o fosso","what stops a competitor","e se um concorrente copiar","e se copiarem o produto","o que impede alguem de copiar","barreira de entrada","what if someone copies you","e se o google fizer isso","e se uma big tech copiar","what if google does this"],"pt":"O código é copiável e não adianta fingir que não. O que não se copia rápido são três coisas: **o acesso** - entrar numa instituição de saúde ou numa barbearia depende de ter estado lá dentro -, **a base extraída**, que são 2,1 milhões de contatos de registro público que custaram tempo de engenharia e não dinheiro, e **o custo de aquisição próximo de zero**, que só existe porque o canal é próprio. Um concorrente com dinheiro copia o produto em meses; para copiar o canal, tem que construir o canal.","en":"Code is copyable and pretending otherwise is useless. What is not quickly copied is three things: **access** - getting inside a healthcare institution or a barbershop depends on having been there -, **the extracted base**, 2.1 million contacts from public registers that cost engineering time rather than money, and **near-zero acquisition cost**, which exists only because the channel is our own. A funded competitor copies the product in months; to copy the channel, they have to build the channel.","fonte":"3BRAIN, ago/2026"},{"id":"o-que-nao-funciona","secao":"#porque","tags":["risco","honestidade","estagio"],"perguntas":["o que ainda nao funciona","o que falta","qual a parte fraca","seja honesto","what does not work yet","weakest part","o que nao funcionou ate agora"],"pt":"Em ordem de importância: **o SAVI não foi vendido** - há piloto, não há contrato; **o HuntAI nunca foi vendido a terceiro** - ele é canal interno, e a única prova de ponta a ponta é uma contratação; **o envio de e-mail está pausado** por decisão nossa até a reputação de IP melhorar; **a entrega de julho é desconhecida**; e o WhatsApp, que é o canal com mais conversa humana, **ainda não tem número auditável**. Nada disso é segredo: está escrito na página, com fonte.","en":"In order of importance: **SAVI has not been sold** - there is a pilot, not a contract; **HuntAI has never been sold to a third party** - it is an internal channel, and the only end-to-end proof is one hire; **e-mail sending is paused** by our own decision until IP reputation improves; **July's delivery is unknown**; and WhatsApp, the channel with the most human conversation, **still has no auditable figure**. None of this is a secret: it is written on the page, with sources.","fonte":"3BRAIN, ago/2026"},{"id":"como-verificar","secao":"#fontes","tags":["metodo","fontes","confianca"],"perguntas":["como confiro esses numeros","de onde vem os dados","posso verificar","as fontes sao publicas","can I verify","where do the numbers come from","por que eu deveria confiar","posso confiar em vocês","como sei que isso é verdade","dá pra confiar","por que confiar"],"pt":"Todos os números da página têm **fonte, denominador e, onde a medição é frágil, a ressalva escrita ao lado** - a seção Fontes lista um por um. Nenhum vem de relatório de consultoria sem metodologia pública. Os de mercado saem de IBGE, Sebrae, Receita Federal e CNES/DATASUS, que **qualquer um consulta**. Os nossos saem de ledger de operação e da API do provedor, com a data da medição. E os que a literatura consagrou mas não usamos, por fragilidade conhecida, estão listados também - **com o motivo**.","en":"Every number on the page has a **source, a denominator and, where the measurement is fragile, the caveat written beside it** - the Sources section lists them one by one. None comes from a paid research report without public methodology. Market figures come from IBGE, Sebrae, the federal tax registry and CNES/DATASUS, which **anyone can check**. Ours come from operation ledgers and the provider's API, with the measurement date. And the ones the literature made famous but we do not use, for known weaknesses, are listed too - **with the reason why**.","fonte":"Seção 07 - Fontes, página 3BRAIN"},{"id":"multiplo-de-saida","secao":"#receita","tags":["investidor","saida","multiplo"],"perguntas":["qual o multiplo de saida","como avaliam a empresa","quanto a empresa vale","que multiplo voces usam","por quanto voces sairiam","exit multiple","how do you value the company","multiplo de receita"],"pt":"Depende inteiramente da **categoria em que o mercado nos puser**, e a diferença é de mais de vinte vezes para a mesma empresa e o mesmo código. Software de lar de idosos negocia a **2,2x receita** (MatrixCare, 8-K da SEC); SaaS vertical com crescimento forte, a **cerca de 12,5x ARR**; escriba clínico, a **cerca de 45x ARR** no pico (Abridge, jun/2025). Para uma saída de US$ 100 milhões isso exigiria, respectivamente, **R$ 235,7 milhões**, **R$ 41,5 milhões** ou **R$ 11,5 milhões** de receita anual. E o que separa 2,2x de 12,5x **não é tecnologia: é validação externa publicada** - e nenhum concorrente que levantamos tem uma.","en":"It depends entirely on **which category the market puts us in**, and the spread is more than twentyfold for the same company and the same code. Senior-living software trades at **2.2x revenue** (MatrixCare, SEC 8-K); a fast-growing vertical SaaS at **about 12.5x ARR**; a clinical scribe at **about 45x ARR** at peak (Abridge, Jun 2025). For a US$100M exit that would require, respectively, **R$ 235.7M**, **R$ 41.5M** or **R$ 11.5M** in annual revenue. And what separates 2.2x from 12.5x **is not technology: it is published external validation** - and none of the competitors we surveyed has one.","fonte":"Estudo de mercado 3BRAIN, ago/2026; 8-K da SEC (MatrixCare); Abridge, jun/2025"},{"id":"venture-scale-honesto","secao":"#receita","tags":["investidor","saida","ressalva"],"perguntas":["isso e venture scale","da retorno de fundo","cabe num fundo de venture","voces sao caso de venture","da pra fazer 10x","is this venture scale","fund returner"],"pt":"**No recorte atual, não - e dizemos antes de perguntarem.** No múltiplo de software de lar de idosos, uma saída de US$ 100 milhões exigiria **R$ 235,7 milhões de receita anual**, e o mercado que contamos de baixo para cima não comporta isso. A trajetória base do SAVI - **R$ 3,93 milhões de ARR no ano 3** e **R$ 16,1 milhões no ano 6**, com churn estruturalmente baixo porque prontuário de residente não migra - é **um excelente resultado para dois fundadores** e **não é** o caso de um fundo que precisa de 10x sobre o cheque. As duas coisas são verdade ao mesmo tempo, e confundi-las é o que custa a rodada. Um investidor experiente faz essa divisão sozinho na segunda leitura: preferimos que ela já esteja escrita.","en":"**In the current framing, no - and we say it before being asked.** At the senior-living-software multiple, a US$100M exit would require **R$ 235.7M in annual revenue**, and the market we counted bottom-up does not support that. SAVI's base trajectory - **R$ 3.93M ARR in year 3** and **R$ 16.1M in year 6**, with structurally low churn because a resident's record does not migrate - is **an excellent outcome for two founders** and is **not** a case for a fund that needs 10x on its cheque. Both are true at once, and conflating them is what costs the round. An experienced investor does that division himself on the second read: we would rather it were already written down.","fonte":"Estudo de mercado 3BRAIN, cap. economia, ago/2026"},{"id":"condicoes-venture","secao":"#receita","tags":["investidor","saida","europa"],"perguntas":["o que mudaria esse veredito","o que faria virar venture","como isso fica grande","o que precisa acontecer pra escalar","what would change that","caminho para escala"],"pt":"Três condições, e são específicas. **Primeira:** o preço por leito precisa ser cerca de **3x o teto brasileiro**, e isso só se sustenta na Europa, onde cobrar por leito já é convenção declarada pelos próprios fornecedores. **Segunda:** Portugal não é o mercado, é a **prova** - o que ele sustenta é a referência auditável que abre Espanha, Reino Unido e Irlanda. **Terceira:** o rótulo de categoria vale mais que qualquer melhoria de produto, e o que muda o rótulo é validação externa publicada. **A lacuna que mais muda o veredito é nossa:** Espanha, Reino Unido e Irlanda **não foram dimensionados** com a mesma disciplina, e até que sejam, o número grande é conversa.","en":"Three conditions, and they are specific. **First:** the price per bed needs to be around **3x the Brazilian ceiling**, and that only holds in Europe, where charging per bed is already declared convention among vendors. **Second:** Portugal is not the market, it is the **proof** - what it sustains is the auditable reference that opens Spain, the UK and Ireland. **Third:** the category label is worth more than any product improvement, and what changes the label is published external validation. **The gap that most changes the verdict is ours:** Spain, the UK and Ireland **have not been sized** with the same discipline, and until they are, the big number is talk.","fonte":"Estudo de mercado 3BRAIN, cap. SAVI, ago/2026"},{"id":"criticos-adversariais","secao":"#fontes","tags":["metodo","estudo","investidor"],"perguntas":["como voces validaram o estudo","quem revisou esses numeros","como sabem que o estudo esta certo","tem revisao independente","how was the study reviewed","quem criticou o estudo"],"pt":"Treze frentes de pesquisa, quatro capítulos escritos sobre elas, e **um crítico adversarial por capítulo, instruído a derrubar o texto** - TAM inflado, conta que não fecha, conclusão que não decorre do dado. O achado mais útil foi o mesmo nos quatro, de forma **independente**: nenhum capítulo tinha uma linha de **imposto**, e toda margem bruta estava apresentada como se fosse operacional. Uma margem de 85% anunciada a investidor que vira 69% na diligência custa mais credibilidade do que os 16 pontos custam em dinheiro. Por isso as margens que publicamos já saem com o imposto dentro.","en":"Thirteen research fronts, four chapters written on top of them, and **one adversarial critic per chapter, instructed to knock the text down** - inflated TAM, arithmetic that does not close, conclusions that do not follow from the data. The most useful finding was the same in all four, **independently**: no chapter had a **tax** line, and every gross margin was presented as if it were operating margin. An 85% margin announced to an investor that becomes 69% in diligence costs more credibility than the 16 points cost in money. That is why the margins we publish already have tax inside.","fonte":"Estudo de mercado 3BRAIN, ago/2026"},{"id":"barbergo-conta-nao-fecha","secao":"#barbergo","tags":["barbergo","cac","ressalva"],"perguntas":["a conta do barbergo fecha","qual o CAC do barbergo","ltv cac do app","vale a pena comprar usuario","o app da lucro por assinante","unit economics barbergo","paga a aquisicao"],"pt":"**No preço de consumo, não fecha - e o número é nosso.** Com conversão de 1,5% e custo por instalação de R$ 2,00, o CAC por assinante fica em **R$ 133** e a razão **LTV:CAC em 0,80:1**: o produto **perde dinheiro em cada assinante comprado por mídia**. Nenhum ajuste de taxa de loja conserta isso, porque o problema não é a margem por assinante e sim o preço da aquisição contra o ticket escolhido. É por isso que a monetização se move para o **estabelecimento** - por aritmética, não por preferência. **Ressalva:** o custo por instalação usado é de referência de mercado; medir o nosso próprio é a lacuna mais cara desse capítulo.","en":"**At the consumer price it does not close - and the number is ours.** With 1.5% conversion and a R$ 2.00 cost per install, CAC per subscriber lands at **R$ 133** and the **LTV:CAC ratio at 0.80:1**: the product **loses money on every subscriber bought through paid media**. No store-fee adjustment fixes that, because the problem is not margin per subscriber but the price of acquisition against the chosen ticket. That is why monetisation moves to the **shop** - by arithmetic, not by preference. **Caveat:** the cost per install used is a market reference; measuring our own is the most expensive gap in that chapter.","fonte":"Estudo de mercado 3BRAIN, cap. BarberGO, ago/2026"},{"id":"barbergo-quem-paga","secao":"#barbergo","tags":["barbergo","modelo","preco"],"perguntas":["por que cobrar do estabelecimento","por que nao cobrar do barbeiro","quantos assinantes voces precisam","quantas barbearias pagam a equipe","why charge the shop","de que lado vem o dinheiro"],"pt":"Pela conta de quantas pessoas é preciso convencer. Para bancar uma **equipe de três pessoas** *seriam precisos* **3.666 assinantes de consumo** ou **527 estabelecimentos assinando** - números de META, não de base: hoje não há nenhum assinante pagante. O ticket do estabelecimento é cerca de cinco vezes maior, e a barbearia já compra software - paga **R$ 79,90 por mês na mediana** só por agenda. O lado do consumidor é justamente a ponta que este vertical já provou, em treze anos e centenas de milhões de agendamentos, que **não paga**: o maior player brasileiro não cobra um centavo do cliente final.","en":"By the arithmetic of how many people you must convince. To fund a **three-person team** you *would need* **3,666 consumer subscribers** or **527 subscribing shops** - these are TARGET figures, not a customer base: today there is no paying subscriber at all. The shop ticket is roughly five times larger, and the shop already buys software - it pays a **median R$ 79.90 a month** for scheduling alone. The consumer side is precisely the end this vertical has already proven, over thirteen years and hundreds of millions of bookings, **does not pay**: the largest Brazilian player charges the end customer nothing.","fonte":"Estudo de mercado 3BRAIN, cap. BarberGO, ago/2026"},{"id":"tam-que-nao-usamos","secao":"#fontes","tags":["metodo","tam","barbergo","ressalva"],"perguntas":["o mercado de beleza nao e de 200 bilhoes","e o numero do setor de beleza","por que nao usam o TAM do setor","abihpec","euromonitor","the beauty market is huge","mercado de beleza brasileiro"],"pt":"**Não usamos, e a razão é simples: aquele número mede outra coisa.** O TAM de cerca de R$ 200 bilhões que circula no setor mede **produto de beleza no varejo** - shampoo, cosmético, prateleira - e não **serviço de barbearia**. Usá-lo para dimensionar um software de barbearia queima a credibilidade da apresentação inteira em dois minutos, porque o investidor conhece a fonte. O nosso número é contado de baixo para cima e é muito menor: **900.868 CNPJs ativos** na atividade de cabeleireiro, barbeiro e manicure, dos quais **85 de cada 100 são MEI**, ou seja, uma pessoa só.","en":"**We do not use it, and the reason is simple: that number measures something else.** The roughly R$ 200bn TAM that circulates in the sector measures **retail beauty products** - shampoo, cosmetics, shelf space - not **barbershop services**. Using it to size barbershop software burns the credibility of the entire pitch in two minutes, because the investor knows the source. Our number is counted bottom-up and is far smaller: **900,868 active companies** in the hairdresser/barber/manicure activity, of which **85 in every 100 are sole traders**.","fonte":"Estudo de mercado 3BRAIN, ago/2026; Mapa de Empresas, 2o quad./2025"},{"id":"barbeiro-carteira-dois-numeros","secao":"#barbergo","tags":["barbergo","emprego","metodo"],"perguntas":["quantos barbeiros tem carteira assinada","o setor emprega quanto","quantos barbeiros sao empregados","por que dois numeros de emprego","how many barbers are employed","carteira assinada no setor"],"pt":"Dois números circulam e medem **coisas diferentes**, então publicamos os dois com o denominador. **210** é o número de **contratações** de barbeiro com carteira em doze meses no Brasil inteiro (Novo CAGED/MTE, CBO 516105, jul/25 a jun/26) - é um **fluxo**. **544** é o **estoque** de barbeiros com vínculo formal declarado (RAIS) - quantos existem, não quantos entraram. Os dois contam a mesma história por caminhos independentes: **o setor praticamente não emprega**, enquanto **768.830 pessoas** mantêm um MEI ativo na atividade. Somar fluxo com estoque seria o tipo de erro que derruba uma apresentação.","en":"Two figures circulate and they measure **different things**, so we publish both with the denominator. **210** is the number of formal **hires** of barbers in twelve months in all of Brazil (Novo CAGED/MTE, occupation code 516105, Jul/25 to Jun/26) - a **flow**. **544** is the **stock** of barbers with a declared formal contract (RAIS) - how many exist, not how many joined. Both tell the same story by independent routes: **the sector barely employs anyone**, while **768,830 people** keep an active sole-trader registration in the activity. Adding a flow to a stock is the kind of error that sinks a pitch.","fonte":"Novo CAGED/MTE, CBO 516105, jul/25 a jun/26; RAIS; Mapa de Empresas, 2o quad./2025"},{"id":"ipca-barbearia","secao":"#barbergo","tags":["barbergo","preco","macro"],"perguntas":["o barbeiro consegue repassar preco","a barbearia tem margem","o setor esta ganhando mais","inflacao do setor de barbearia","can barbers raise prices","poder de repasse"],"pt":"Há um sinal favorável que quase ninguém cita: o subitem **cabeleireiro e barbeiro** do IPCA subiu **7,71% em doze meses** contra **4,44%** da inflação cheia, e **8,05% em 2025** contra **4,26%**. Quem repassa preço acima da inflação **dois anos seguidos** tem margem para pagar mensalidade - e isso é mais forte do que qualquer pesquisa de intenção, porque é comportamento medido, não declaração. Vale junto com a ressalva do outro lado: o teto do MEI é de **R$ 6.750 por mês**, e é essa a caixa em que qualquer preço tem de caber.","en":"There is a favourable signal almost nobody cites: the IPCA sub-item for **hairdressers and barbers** rose **7.71% over twelve months** against **4.44%** for headline inflation, and **8.05% in 2025** against **4.26%**. Anyone passing on prices above inflation **two years running** has room to pay a subscription - and that is stronger than any intent survey, because it is measured behaviour, not a statement. It goes together with the caveat on the other side: the sole-trader ceiling is **R$ 6,750 a month**, and that is the box any price must fit into.","fonte":"IBGE/IPCA, subitem cabeleireiro e barbeiro, 12 meses até ago/2026; LC 123/2006"},{"id":"squire-custo-por-loja","secao":"#barbergo","tags":["barbergo","concorrencia","cac"],"perguntas":["quanto a squire gastou por barbearia","capital queimado pela squire","por que capital nao resolve","da pra comprar esse mercado","can you buy this market","custo por estabelecimento conquistado"],"pt":"A Squire é a prova documentada de que **não há saída por capital neste mercado**: cerca de **US$ 167 milhões levantados** para chegar a **cerca de 3.000 barbearias** - **US$ 55.667 de capital queimado por barbearia conquistada** - e cinco anos sem captação nova, com o valuation de US$ 750 milhões nunca remarcado. **A empresa não morreu:** ela atingiu o tamanho natural do mercado que escolheu. A leitura que tiramos é que dinheiro não compra este vertical, então a entrada tem de ser por canal próprio e ticket de estabelecimento - que é exatamente o que a nossa conta de aquisição já dizia.","en":"Squire is the documented proof that **there is no way to buy this market**: roughly **US$167M raised** to reach **about 3,000 barbershops** - **US$55,667 of capital burned per shop won** - and five years with no new round, its US$750M valuation never marked. **The company did not die:** it reached the natural size of the market it chose. Our reading is that money does not buy this vertical, so entry has to be through an owned channel and a shop-level ticket - which is exactly what our own acquisition arithmetic already said.","fonte":"Contrary Research e imprensa do setor; valores reportados, não auditados"},{"id":"demografia-ilpi","secao":"#savi","tags":["savi","mercado","demografia","timing"],"perguntas":["por que agora","por que esse mercado cresce","quantas pessoas moram em ILPI","o brasil esta envelhecendo","why now","qual o timing disso","quantos idosos institucionalizados"],"pt":"O argumento não é há muitos idosos - é que **a demanda descola do crescimento populacional**. No Brasil, **160.784 pessoas vivem em instituição de longa permanência** (Censo IBGE 2022), das quais **45,6% têm 80 anos ou mais**. A taxa de institucionalização é de **0,71% dos maiores de 65**, contra mediana de **3,5% na OCDE**. E o grupo de **80 anos ou mais cresce 2,80x até 2050**, enquanto a população total **para de crescer em 2041**. Ou seja: o país para de crescer e a faixa que consome cuidado quase triplica.","en":"The argument is not there are many elderly people - it is that **demand decouples from population growth**. In Brazil, **160,784 people live in long-term care institutions** (IBGE Census 2022), of whom **45.6% are 80 or older**. The institutionalisation rate is **0.71% of those over 65**, against an OECD median of **3.5%**. And the **80-plus group grows 2.80x by 2050**, while the total population **stops growing in 2041**. In short: the country stops growing while the band that consumes care nearly triples.","fonte":"Censo IBGE 2022; OCDE Health at a Glance; projeção IBGE"},{"id":"cadastro-ilpi-nao-existe","secao":"#savi","tags":["savi","ressalva","cac","mercado"],"perguntas":["como voces acham essas casas","existe lista de ILPI","de onde sai a lista de clientes","quantas ILPI privadas existem","is there a registry","por que o CAC e alto no brasil"],"pt":"**Não existe cadastro das casas privadas com fins lucrativos no Brasil, e isso encarece a venda.** A ILPI **não é tipo de estabelecimento no CNES**, e o último levantamento nacional é do IPEA com coleta de **2007-2009** - por isso as 3.548 casas que citamos são **piso**, não contagem atual. A consequência prática é que **o custo de achar o cliente é estruturalmente mais alto aqui**, porque a lista tem de ser construída. Em Portugal a lista **é pública**, e é uma das razões pelas quais o mercado de lá sai mais barato de alcançar apesar de ser trinta vezes menor.","en":"**There is no register of private for-profit homes in Brazil, and that makes selling more expensive.** Long-term care homes are **not an establishment type in CNES**, and the last national survey is IPEA's, collected in **2007-2009** - which is why the 3,548 homes we cite are a **floor**, not a current count. The practical consequence is that **the cost of finding the customer is structurally higher here**, because the list has to be built. In Portugal the list **is public**, and that is one reason that market is cheaper to reach despite being thirty times smaller.","fonte":"CNES/DATASUS; IPEA, coleta 2007-2009"},{"id":"por-que-portugal","secao":"#savi","tags":["savi","portugal","internacional"],"perguntas":["por que expandir para portugal","voces vao pra europa","o que portugal resolve","mercado portugues de vocês","why expand to portugal","expansao internacional","portugal e mercado ou prova"],"pt":"Porque **Portugal é a prova, não o mercado**. Um universo **trinta vezes menor** que o brasileiro produz **mais receita alcançável em três anos** - R$ 2,37 milhões contra R$ 1,56 milhão - por duas razões concretas: o **preço por unidade é 46% maior** e **a lista de clientes é pública**, o que derruba o custo de achar quem compra. O que Portugal sustenta sozinho é pequeno; o que ele sustenta de verdade é a **referência auditável** que abre Espanha, Reino Unido e Irlanda, onde cobrar por leito já é convenção. **Esses três ainda não foram dimensionados por nós**, e até que sejam, não afirmamos tamanho.","en":"Because **Portugal is the proof, not the market**. A universe **thirty times smaller** than Brazil's produces **more reachable revenue over three years** - R$ 2.37M against R$ 1.56M - for two concrete reasons: the **price per unit is 46% higher** and **the customer list is public**, which collapses the cost of finding buyers. What Portugal sustains on its own is small; what it really sustains is the **auditable reference** that opens Spain, the UK and Ireland, where per-bed pricing is already convention. **We have not sized those three**, and until we do, we claim no size.","fonte":"Estudo de mercado 3BRAIN, cap. SAVI, ago/2026"},{"id":"epic-sepsis","secao":"#savi","tags":["savi","ia","ressalva","predicao"],"perguntas":["e se a IA errar","por que nao prometem predicao","modelo preditivo funciona","ia clinica nao falha","alerta demais cansa a equipe","alert fatigue","what if the model is wrong","risco de falso alarme"],"pt":"**Hoje nós não prometemos predição, e o caso que explica o porquê é de outra empresa.** O que o SAVI afirma agora é **captura e vigilância do que ficou em branco ou fora de faixa**; a camada preditiva é etapa planejada, com registro sanitário antes da comercialização. O contraexemplo é o **Epic Sepsis Model, de terceiros**, embarcado em centenas de hospitais americanos: prometia AUC de 0,76 a 0,83 e entregou **0,63** na avaliação externa, com **sensibilidade de 33%** e **109 alertas para cada caso detectado** (JAMA Internal Medicine, 2021). **Esses números são do modelo da Epic, não do nosso.** A lição que tiramos: alerta que grita demais é desligado pela equipe, e aí o sistema piora o cuidado em vez de melhorar.","en":"**We do not promise prediction today, and the case that explains why belongs to another company.** What SAVI claims now is **capture and surveillance of what was left blank or out of range**; the predictive layer is a planned stage, with regulatory clearance before commercialisation. The counter-example is the **Epic Sepsis Model, a third party's**, embedded in hundreds of US hospitals: it promised an AUC of 0.76-0.83 and delivered **0.63** on external evaluation, with **33% sensitivity** and **109 alerts for every case detected** (JAMA Internal Medicine, 2021). **Those figures belong to Epic's model, not ours.** The lesson we draw: an alarm that cries wolf gets switched off by the staff, and then the system makes care worse rather than better.","fonte":"Wong et al., JAMA Internal Medicine, 2021 (Epic Sepsis Model)"},{"id":"base-nao-e-o-ativo","secao":"#motor","tags":["huntai","ativo","ressalva"],"perguntas":["a base de e-mails vale quanto","voces vendem a base","o ativo de voces e a lista","quanto vale essa base","por que nao vender a lista","is the list the asset","qual e o ativo do motor"],"pt":"**O ativo não é a base - e dizemos isso contra o nosso próprio interesse de apresentação.** O mercado já reprecificou lista de contatos verificados como **ativo em depreciação**: a ZoomInfo faz **US$ 1,25 bilhão de receita**, projeta **queda** e vale **0,90x receita**. Lista parada perde valor sozinha. **O ativo é a engenharia de entrega com limites medidos** - saber a que ritmo se pode operar sem ser estrangulado, e que o tipo de pedido pesa mais que o volume. Isso **não se copia num fim de semana**, e é a única coisa do motor sobre a qual se pode dizer isso.","en":"**The asset is not the list - and we say that against our own pitching interest.** The market has already repriced verified contact lists as a **depreciating asset**: ZoomInfo does **US$1.25bn in revenue**, projects a **decline** and trades at **0.90x revenue**. A static list loses value on its own. **The asset is the delivery engineering with measured limits** - knowing the rate at which you can operate without being throttled, and that the type of request weighs more than the volume. That **cannot be copied over a weekend**, and it is the only thing about the engine of which that can be said.","fonte":"ZoomInfo, resultados e projeção 2026; operação HuntAI"},{"id":"heyreach-precedente","secao":"#motor","tags":["huntai","risco","plataforma"],"perguntas":["e se a plataforma banir voces","ja aconteceu de alguem ser desligado","precedente de banimento","risco de depender de plataforma","what if you get banned","heyreach"],"pt":"Já aconteceu com um concorrente, e o precedente é recente: em **março de 2026 a HeyReach teve cerca de 30.000 usuários desligados num único dia**. Não houve tribunal nem aviso - a plataforma pode desligar a empresa e o fundador **em semanas, por contrato**. A lição que tiramos é a razão de o motor ser construído como é: **o que sobrevive é canal próprio** - domínio, IP e reputação de entrega nossos. Onde o motor encosta em plataforma de terceiro, ele trabalha **abaixo de limites medidos em operação**, e não de palpite, porque ali a regra é contrato e não lei.","en":"It already happened to a competitor, and the precedent is recent: in **March 2026 HeyReach had around 30,000 users cut off in a single day**. There was no court and no warning - the platform can switch off the company and the founder **within weeks, by contract**. The lesson we drew is the reason the engine is built the way it is: **what survives is an owned channel** - our own domain, IP and sending reputation. Where the engine touches a third-party platform it works **below limits measured in operation**, not guessed, because there the rule is contract, not law.","fonte":"Estudo de mercado 3BRAIN, cap. HuntAI, ago/2026; imprensa do setor, mar/2026"},{"id":"comparaveis-sem-capital","secao":"#motor","tags":["huntai","comparaveis","receita"],"perguntas":["alguem ganha dinheiro com isso","tem empresa parecida que deu certo","quem mais faz esse motor","da pra crescer sem levantar dinheiro","bootstrapped comparables","quanto essas empresas faturam","are there comparable companies","who else did this without funding"],"pt":"Sim, e o detalhe que importa é **como** elas chegaram lá. A Instantly fez **US$ 38 milhões de ARR** e a Smartlead **US$ 20 milhões**, ambas **sem levantar um dólar de investimento**. É o mesmo primitivo que o nosso motor usa - entrega em escala com reputação própria - e mostra que a categoria **paga a própria conta antes de precisar de capital**. Serve também de régua para a ambição: o alvo honesto aqui é uma empresa de **R$ 5 a 10 milhões por ano**, não um unicórnio, e essa é a mesma faixa em que essas duas operam.","en":"Yes, and the detail that matters is **how** they got there. Instantly reached **US$38M ARR** and Smartlead **US$20M**, both **without raising a dollar**. It is the same primitive our engine uses - delivery at scale on your own reputation - and it shows the category **pays its own way before needing capital**. It also sets the yardstick for ambition: the honest target here is a **R$ 5-10M a year** company, not a unicorn, and that is the same band those two operate in.","fonte":"ARR reportado por Instantly e Smartlead, 2024-2025"},{"id":"o-que-nao-sabemos","secao":"#fontes","tags":["ressalva","metodo","lacunas"],"perguntas":["o que voces nao sabem","quais sao as lacunas","o que falta medir","onde o estudo e fraco","what do you not know","quais as incertezas","o que voces ainda nao mediram"],"pt":"Estudo que esconde as próprias lacunas é pior que estudo curto, então aqui estão as nossas. **Não existe dimensionamento publicado** da categoria de ferramentas para candidato por nenhuma casa de research - todo tamanho ali e construção nossa. **Nenhum concorrente daquela camada divulga receita ou usuários**, nem os bem financiados. **Não confirmamos em fonte primaria se há reembolso** por software de cuidado no SUS, na ANS ou na Segurança Social portuguesa - se não houver, o teto de preço é a margem da própria casa. **O custo e o prazo de organismo notificado para marcação CE não foram fechados.** **Espanha, Reino Unido e Irlanda não foram dimensionados.** E o enquadramento por fator R **precisa de confirmação contábil**.","en":"A study that hides its own gaps is worse than a short study, so here are ours. **There is no published sizing** of the candidate-tools category by any research house - every figure there is our own construction. **No competitor in that layer discloses revenue or users**, not even the well-funded ones. **We have not confirmed in a primary source whether there is reimbursement** for care software under Brazil's public system, private health plans, or Portuguese social security - if there is none, the price ceiling is the home's own margin. **The cost and timeline of a notified body for CE marking are not settled.** **Spain, the UK and Ireland have not been sized.** And the tax-bracket classification **needs accounting confirmation**.","fonte":"Estudo de mercado 3BRAIN, ago/2026"},{"id":"onde-ficamos","tags":["empresa","localizacao","contato"],"perguntas":["onde vocês ficam?","de que cidade vocês são?","onde fica a empresa?","qual a sede de vocês?","vocês são de onde?","vocês são brasileiros?","tem escritório?","where are you based","vocês atendem presencialmente?"],"pt":"A 3BRAIN é brasileira e opera a partir da Grande Florianópolis, em Santa Catarina. O CNPJ 66.447.959/0001-88 foi aberto em abril de 2026, sob o regime Inova Simples. Não há escritório aberto ao público nem time comercial: são dois fundadores, e a porta de entrada é a conversa de 20 minutos desta página. O atendimento é remoto.","en":"3BRAIN is a Brazilian company and operates out of the Greater Florianópolis area, in Santa Catarina. Company ID (CNPJ) 66.447.959/0001-88 was registered in April 2026 under the Inova Simples regime. There is no office open to the public and no sales team: there are two founders, and the way in is the 20-minute conversation on this page. Support is remote.","fonte":"Cadastro CNPJ 66.447.959/0001-88, abril/2026; sede declarada da 3BRAIN","encaminha":"falar-com-fundador"}]};

/* ═══════════ ASSISTENTE LATERAL ═══════════
   Duas camadas. A base curada (window.BASE_3BRAIN, 78 entradas com fonte) e a verdade;
   o modelo so REFORMULA o que ela ja diz — e nunca inventa numero, porque nunca recebe
   liberdade para isso: candidatos() escolhe as entradas, o Worker manda so elas como
   contexto, e a instrucao la proibe sair delas. Isso se chama RAG.
   Se o Worker cair, faltar, demorar ou recusar, busca() responde como sempre respondeu.
   Nada aqui guarda chave: a pagina e publica e a chave mora no Worker. */
(function(){
  "use strict";
  var BASE = window.BASE_3BRAIN;
  if (!BASE) return;

  var raiz    = document.body;
  var abre    = document.getElementById('asAbre');
  var painel  = document.getElementById('asPainel');
  var fecha   = document.getElementById('asFecha');
  var fluxo   = document.getElementById('asFluxo');
  var chips   = document.getElementById('asChips');
  var form    = document.getElementById('asForm');
  var campo   = document.getElementById('asCampo');
  var veu     = document.createElement('div');
  veu.className = 'as-veu';
  document.body.appendChild(veu);

  var idioma = function(){ return raiz.classList.contains('lang-en') ? 'en' : 'pt'; };

  /* ── a ponte. Vazio = so base local, que e exatamente o comportamento de antes.
        Preencha com a URL do Worker depois do `wrangler deploy` (ver worker/README.md). */
  /* Dominio proprio. O workers.dev continua vivo e fixado no wrangler.jsonc,
     entao trocar aqui nao desliga nada -- so tira o endereco de terceiro da
     frente do visitante. */
  var API = 'https://api.3brain.com.br';
  /* Maior que o teto do Worker de proposito. O Worker gasta ate 6s na Groq e
     ate mais 6s na Workers AI antes de desistir; se a pagina desistisse aos 9s,
     ela mataria a queda no meio e o segundo motor nunca chegaria a tela. */
  var ESPERA_MS = 18000;

  var ocupado = false;      // trava de reentrancia: sem ela, tres perguntas voltam fora de ordem
  var historico = [];       // 6 mensagens = 3 turnos. Teto de token, nao de memoria

  /* ---------- normalizacao e similaridade ---------- */
  var PARAR = ('a o e de da do das dos que qual quais como para por com sem em no na nos nas um uma uns umas ' +
    'os as ao aos se ja eh eu tem ter ha sobre isso isto aquilo ' +
    /* MEDIDO em 27/08/2026, nao chutado: contei em quantas das 136 entradas cada
       ficha aparece nos gatilhos. "voces" esta em 71 delas -- 52% da base -- e
       mesmo assim pontuava com peso cheio, entao tres gatilhos com "voces" numa
       entrada bastavam para ela roubar pergunta de outra. Estas dizem o FORMATO
       da pergunta, nao o ASSUNTO: nao distinguem entrada nenhuma.

       "nao" e "ainda" ESTAVAM aqui e SAIRAM, medido: a base e construida sobre
       negativa honesta -- "o que nao funciona", "metricas que nao usamos", "o
       que nao sabemos ainda", "nao ha receita". Nesta base a negacao e palavra
       de CONTEUDO, e cala-la tirava a marca mais distintiva justamente das
       perguntas de investidor cetico. Medido: 2 de 8 em 1o lugar com "nao"
       calado, 4 de 8 com ele vivo. Frequente nao e o mesmo que pouco
       informativo -- e por isso lista de parada e feita POR CORPUS, nunca
       copiada. */
    'voces voce vcs pra pro esta estao sao esse essa esses essas muito mais '  +
    /* vcs e voces escrito depressa: e pronome, nao assunto. Sem isto, o portao
       de vocabulario de busca() -- que exige 60% de palavras conhecidas --
       REPROVAVA 'vcs tem cnpj' inteiro por causa de uma palavra de ligacao. */
    'tambem entao algum alguma alguns todas todos cada mesmo ' +
    'the of to in for on is are what how do does you your we our it that this a an and or ' +
    /* mesmas do portugues, do outro lado: dizem o FORMATO da pergunta.
       Entraram com o indice ingles, senao 'how much', 'where are' e 'do you'
       passariam a pontuar em metade da base. */
    'where when who why which there here about from with have has had been will '  +
    'would should could can may might must they them their its was were be being ' +
    'not no yes than then so such very more most any all each some other into out ' +
    'up down over under again just only also both same own too').split(' ');
  var PARA = {}; PARAR.forEach(function(p){ PARA[p] = 1; });

  function limpa(s){
    return String(s || '').toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9\s]/g, ' ')
      .replace(/\s+/g, ' ').trim();
  }
  /* TESTEI RADICALIZAR (cortar sufixo de flexao dos dois lados, indice e
     pergunta) para "faturam" encontrar "faturamento" e "usa" encontrar "usam".
     PIOROU, nas duas doses que tentei:

                          53      visitante(1o/top5)   piso
       lista larga       52/53        30 / 33         77/88
       so plural+mente   52/53        30 / 36         78/88
       sem radical       53/53        32 / 36         79/88

     Duas razoes, e as duas medidas: o TRIGRAMA ja cobre a variacao morfologica
     (compara pedaco, nao palavra inteira), entao o ganho e pequeno; e cortar
     sufixo JUNTA palavras que nao sao a mesma coisa, e esse erro fica invisivel
     porque a busca continua devolvendo alguma entrada. Somar peca sobre peca
     que faz a mesma coisa e como se acumula regressao silenciosa. */
  function fichas(s){
    return limpa(s).split(' ').filter(function(t){ return t.length > 2 && !PARA[t]; });
  }
  /* distancia de edicao curta, para tolerar erro de digitacao */
  function perto(a, b){
    if (a === b) return true;
    if (Math.abs(a.length - b.length) > 2) return false;
    if (a.length < 5 || b.length < 5) return a.slice(0,4) === b.slice(0,4);
    var m = a.length, n = b.length, d = [], i, j;
    for (i = 0; i <= m; i++) d[i] = [i];
    for (j = 0; j <= n; j++) d[0][j] = j;
    for (i = 1; i <= m; i++) for (j = 1; j <= n; j++)
      d[i][j] = Math.min(d[i-1][j] + 1, d[i][j-1] + 1, d[i-1][j-1] + (a[i-1] === b[j-1] ? 0 : 1));
    return d[m][n] <= (a.length > 7 ? 2 : 1);
  }

  /* SEMELHANCA POR TRIGRAMA DE CARACTERE. A contagem de palavra so casa palavra
     INTEIRA: "faturam" nao encontra "faturamento", "investir" nao encontra
     "investimento", "barbego" nao encontra "barbergo". Trigrama casa o PEDACO,
     entao pega erro de digitacao e variacao morfologica de graca, sem
     dicionario e sem modelo. E o barato que falta entre a contagem de palavra
     (cega a variacao) e o indice semantico (que ainda nao temos). */
  function trigramas(t){
    var s2 = ' ' + limpa(t) + ' ', m = {};
    for (var i = 0; i + 3 <= s2.length; i++) m[s2.slice(i, i + 3)] = 1;
    return m;
  }
  /* Cobertura: quanto da PERGUNTA aparece na entrada. Nao e Jaccard de
     proposito -- entrada longa nao pode ser punida por ser longa, e a pergunta
     e que precisa estar coberta. */
  function cobertura(triQ, nQ, triE){
    if (!nQ) return 0;
    var n = 0;
    for (var k in triQ) if (triE[k]) n++;
    return n / nQ;
  }

  /* indice: cada entrada vira um saco de fichas com peso, mais as frases inteiras */
  var INDICE = BASE.entradas.map(function(e){
    var saco = {};
    (e.perguntas || []).forEach(function(p){
      fichas(p).forEach(function(t){ saco[t] = (saco[t] || 0) + 2; });
    });
    (e.tags || []).forEach(function(t){
      fichas(t).forEach(function(x){ saco[x] = (saco[x] || 0) + 3; });
    });
    /* PESO 0,5 e MEDIDO, nao escolhido: testei 1,0 e o teste de exclusao
       melhorou 2 pontos (92% -> 94% chegando ao reordenador) mas as baterias
       principais PIORARAM -- dificeis de 96% para 90% no top 5 e visitante de
       32 para 30 em 1o lugar. Gatilho tem de continuar valendo mais que texto
       de resposta: o texto fala do assunto, o gatilho fala da PERGUNTA.
       Parei de afinar aqui de proposito -- ajustar um numero contra bateria
       pequena e como se fabrica sobreajuste. */
    fichas(e.pt).forEach(function(t){ saco[t] = (saco[t] || 0) + 0.5; });
    /* O e.en NUNCA entrava no indice. Medido em 27/08/2026 com 20 perguntas em
       ingles: 8 acertavam em 1o lugar contra 28 de 36 em portugues, e "is it
       secure" e "are you profitable" devolviam LISTA VAZIA. A pagina e bilingue
       e a metade inglesa dela era invisivel para a propria busca. Mesmo peso do
       pt: os dois sao texto de resposta, nenhum vale mais que o outro. */
    fichas(e.en || '').forEach(function(t){ saco[t] = (saco[t] || 0) + 0.5; });
    return {
      e: e,
      saco: saco,
      chaves: Object.keys(saco),
      /* dos GATILHOS e das TAGS, nao da resposta: e a pergunta do visitante que
         se quer parecida com a pergunta cadastrada. Medido em 27/08 no
         reordenador, a mesma licao: 2 de 18 vendo a resposta, 11 de 18 vendo a
         pergunta. */
      tri: trigramas((e.perguntas || []).join(' ') + ' ' + (e.tags || []).join(' ')),
      frases: (e.perguntas || []).map(limpa).filter(function(x){ return x.length > 3; })
    };
  });
  /* vocabulario de tudo que a base conhece — serve para detectar pergunta fora de escopo */
  var VOCAB = [];
  (function(){
    var visto = {};
    INDICE.forEach(function(it){ it.chaves.forEach(function(k){ visto[k] = 1; }); });
    VOCAB = Object.keys(visto);
  })();
  /* Em quantas entradas cada ficha aparece. Palavra que esta em meia base nao
     diz que a pergunta e nossa -- "quem", "foi" e "dor" existem aqui por acaso,
     e eram elas que faziam "quem foi napoleao bonaparte" passar pelo portao. */
  var DF = {};
  (function(){
    INDICE.forEach(function(it){
      /* SO os GATILHOS e as TAGS, nao o texto da resposta. Contar sobre o texto
         dava "foi" como palavra nossa -- ela aparece em poucas entradas por
         acaso, e por isso "quem foi napoleao bonaparte" passava pelo portao.
         O texto fala de tudo; o gatilho fala do que alguem pergunta AQUI. */
      var vis = {};
      (it.e.perguntas || []).forEach(function(x){ fichas(x).forEach(function(t){ vis[t] = 1; }); });
      (it.e.tags || []).forEach(function(x){ fichas(x).forEach(function(t){ vis[t] = 1; }); });
      for (var k in vis) DF[k] = (DF[k] || 0) + 1;
    });
  })();
  /* DISTINTIVA = existe na base E nao esta espalhada por ela. O teto de 25%
     saiu da contagem real: "voces" estava em 52% das entradas, "savi" em 25%,
     "risco" em 16%. Nome de produto tem de passar; palavra de ligacao, nao. */
  function distintiva(t){
    var n = DF[t] || 0;
    return n > 0 && n / INDICE.length <= 0.25;
  }

  function conhecida(t){
    if (VOCAB.indexOf(t) >= 0) return true;
    for (var i = 0; i < VOCAB.length; i++) if (perto(t, VOCAB[i])) return true;
    return false;
  }

  function busca(texto){
    var frase = limpa(texto);
    var q = fichas(texto);
    if (!q.length) return null;

    /* 1a) frase identica a uma variante cadastrada — resposta direta */
    for (var i = 0; i < INDICE.length; i++) {
      var fr = INDICE[i].frases;
      for (var j = 0; j < fr.length; j++) if (fr[j] === frase) return INDICE[i].e;
    }
    /* 1b) uma contem a outra — so vale se a MENOR das duas ja for especifica.
           Sem isso, uma variante curta como "o savi" casaria dentro de
           "quanto custa o savi" e devolveria a entrada errada. */
    /* ATALHO AMBIGUO NAO DECIDE. Ate 27/08/2026 este laco devolvia a PRIMEIRA
       entrada que casasse, e a ordem do arquivo passava a decidir conteudo:
       "qual o maior risco" -- um dos seis botoes de sugestao da pagina -- cabe
       dentro de "qual o maior risco desse canal" (HuntAI) e de "qual o maior
       risco do negocio" (o certo), e ganhava o que estivesse mais acima.
       Agora, com mais de um casamento, o atalho se cala e deixa a pontuacao
       decidir entre os que casaram. Um atalho so pode valer quando e unico. */
    var casaram = [];
    for (var i2 = 0; i2 < INDICE.length; i2++) {
      var fr2 = INDICE[i2].frases;
      for (var j2 = 0; j2 < fr2.length; j2++) {
        var v = fr2[j2];
        var menor = v.length < frase.length ? v.length : frase.length;
        if (menor < 16) continue;
        if (v.indexOf(frase) >= 0 || frase.indexOf(v) >= 0) { casaram.push(INDICE[i2]); break; }
      }
    }
    if (casaram.length === 1) return casaram[0].e;

    /* 2) se a maior parte das palavras nao existe na base, e pergunta de outro assunto.
          E o que impede "receita de bolo de cenoura" de cair na entrada de faturamento. */
    var dentro = 0;
    q.forEach(function(t){ if (conhecida(t)) dentro++; });
    if (q.length >= 2 && dentro / q.length < 0.6) return null;

    /* 3) pontuacao por sobreposicao, exigindo mais de uma palavra casada em pergunta longa */
    var melhor = null;
    /* Se o atalho achou varios, so eles disputam: a pergunta ja se declarou
       daquele grupo, e deixar a base inteira concorrer perderia essa evidencia. */
    (casaram.length ? casaram : INDICE).forEach(function(it){
      var s = 0, casados = 0;
      q.forEach(function(t){
        if (it.saco[t]) { s += it.saco[t]; casados++; return; }
        for (var k = 0; k < it.chaves.length; k++) {
          if (perto(t, it.chaves[k])) { s += it.saco[it.chaves[k]] * 0.6; casados++; return; }
        }
      });
      s = s / Math.sqrt(q.length);
      if (q.length >= 3 && casados < 2) return;      // uma palavra so nao decide pergunta longa
      if (!melhor || s > melhor.s) melhor = { it: it, s: s, casados: casados };
    });
    if (!melhor) return null;
    var minimo = q.length <= 2 ? 1.3 : 2.0;          // pergunta curta ja e especifica por si
    if (melhor.s < minimo) return null;
    return melhor.it.e;
  }

  /* Os n melhores candidatos, SEM os pisos de pontuacao — quem julga relevancia e o modelo.
     A rejeicao fora-de-vocabulario continua valendo, so que mais frouxa: se a pergunta nao
     e sobre a 3BRAIN, ele recebe contexto VAZIO e a instrucao manda dizer que nao tem o
     dado. E o que impede o modelo de florear em cima de entrada irrelevante. */
  /* CONVERSA SOCIAL antes de qualquer busca. "oba", "to te testando" e "valeu" nao
     sao perguntas sobre a 3BRAIN: candidatos() devolve vazio, o modelo recebe
     contexto vazio e responde "nao tenho esse dado" -- tecnicamente correto e
     parecendo quebrado para quem so disse oi. Aqui a conversa e recebida e a
     pessoa e orientada sobre o que da para perguntar. */
  /* AS TRES ANCORAM AS DUAS PONTAS, de proposito. Ancorar so o inicio fazia
     "oi quanto custa o savi" virar um "oi" e nada mais; e a palavra "funciona"
     solta, sem ancora nenhuma, sequestrava "como funciona o savi" -- das
     perguntas mais comuns da pagina -- para uma resposta pronta de teste.
     Social so quando a mensagem INTEIRA e social. Na duvida cai na busca, que
     e o erro barato: pergunta social respondida com dado incomoda menos do que
     pergunta de produto respondida com "pode testar a vontade".

     E o motivo de nao usar \b aqui: "obrigado" nao casava com /^(obrigad)\b/,
     porque depois de "obrigad" vem "o", que e caractere de palavra e portanto
     nao e fronteira. Ancora de fim resolve os dois casos de uma vez. */
  var SOCIAL = {
    saudacao: /^(oi+|ola+|opa+|oba+|eae?|e ai|salve|hey+|hi+|hello+|yo|bom dia|boa tarde|boa noite|tudo bem|tudo bom|blz|beleza|good (morning|afternoon|evening))( (tudo bem|tudo bom|beleza|blz|gente|pessoal|ai))?$/,
    agradece: /^(muito )?(obrigad[oa]?|valeu|vlw|brigad[oa]?|thanks|thank you|ty|tks)( mesmo| ai| gente| pela ajuda)?$/,
    teste:    /^(ping|teste|testes|testando|testar|so testando|so um teste|to testando|to te testando|ta funcionando|esta funcionando|nao ta funcionando|nao funciona|ta on|ta vivo)$/
  };
  /* ENTRADA DEGENERADA. Medido em 27/08/2026: "?????", "aaaaaaa", "..." e "1"
     mandavam SESSENTA candidatos ao modelo -- gasto e risco, para uma coisa que
     nem pergunta e. E a resposta que sobrava era "nao tenho essa resposta", que
     faz o assistente parecer quebrado quando o quebrado foi o teclado. Aqui
     recebe-se e orienta-se, como ja se faz com "oi". */
  function degenerada(t){
    var letras = t.replace(/[^a-z]/g, '');
    if (letras.length < 2) return true;                 // "?????", "...", "1"
    if (/^(.)\1+$/.test(letras)) return true;           // "aaaaaaa"
    return false;
  }
  function ehSocial(texto){
    var t = limpa(texto);
    if (!t) return 'confuso';           // so pontuacao, so emoji: limpa para nada
    if (t.split(' ').length > 5) return null;
    if (degenerada(t)) return 'confuso';
    if (SOCIAL.agradece.test(t)) return 'agradece';
    if (SOCIAL.saudacao.test(t)) return 'saudacao';
    if (SOCIAL.teste.test(t))    return 'teste';
    return null;
  }
  var FALA = {
    saudacao: {
      pt: 'Oi! Eu respondo sobre a **3BRAIN** com fonte: os dois produtos (SAVI Saude e BarberGO), o motor de aquisicao, os numeros desta pagina e o time. Pode perguntar o que quiser — ou tocar numa das sugestoes.',
      en: 'Hi! I answer about **3BRAIN**, with sources: the two products (SAVI Saude and BarberGO), the acquisition engine, the numbers on this page and the team. Ask me anything — or tap one of the suggestions.'
    },
    agradece: {
      pt: 'De nada. Se quiser ir fundo em algum numero, e so perguntar — cada um aqui tem fonte e denominador.',
      en: 'You are welcome. If you want to go deep on any figure, just ask — every one here has a source and a denominator.'
    },
    confuso: {
      pt: 'Nao entendi essa. Pode escrever com outras palavras? Eu respondo sobre a **3BRAIN**: os dois produtos (SAVI Saude e BarberGO), o motor de aquisicao, os numeros desta pagina, o time e a rodada.',
      en: 'I did not get that one. Could you put it in other words? I answer about **3BRAIN**: the two products (SAVI Saude and BarberGO), the acquisition engine, the numbers on this page, the team and the round.'
    },
    teste: {
      pt: 'Pode testar a vontade. Eu respondo **so com o que esta medido nesta pagina** — e o que eu nao souber, eu digo que nao sei, em vez de inventar. Tenta perguntar o que e o SAVI, quanto custa, ou qual o maior risco.',
      en: 'Test away. I answer **only from what is measured on this page** — and what I do not know, I say I do not know instead of inventing it. Try asking what SAVI is, how much it costs, or what the biggest risk is.'
    }
  };

  function candidatos(texto, n){
    var q = fichas(texto);
    if (!q.length) return [];
    var dentro = 0;
    q.forEach(function(t){ if (conhecida(t)) dentro++; });
    if (q.length >= 2 && dentro / q.length < 0.4) return [];

    var pontos = [];
    INDICE.forEach(function(it){
      var sc = 0;
      q.forEach(function(t){
        if (it.saco[t]) { sc += it.saco[t]; return; }
        for (var k = 0; k < it.chaves.length; k++) {
          if (perto(t, it.chaves[k])) { sc += it.saco[it.chaves[k]] * 0.6; return; }
        }
      });
      if (sc > 0) pontos.push({ e: it.e, s: sc });
    });
    pontos.sort(function(a, b){ return b.s - a.s; });
    return pontos.slice(0, n || 3).map(function(p){ return p.e; });
  }

  /* O texto que o REORDENADOR le -- e que NAO e o mesmo que o modelo usa para
     fundamentar. Medido em 27/08/2026 com o alvo plantado num contexto de 60:
     vendo a RESPOSTA, o reordenador achava a entrada certa 2 vezes em 18;
     vendo a PERGUNTA cadastrada, 11 em 18. Cinco vezes e meia melhor.

     A razao aparece depois de vista: a pergunta do visitante parece com a
     PERGUNTA, nao com a RESPOSTA. "how much does it cost" nao se parece com um
     paragrafo sobre R$ 99 por leito; parece com "quanto custa?". Casar pergunta
     com pergunta e o que o reordenador sabe fazer bem.

     Por isso viajam DOIS campos por candidato: `busca`, para escolher, e
     `texto`, para fundamentar. Misturar os dois foi o erro de origem. */
  function textoDeBusca(e, l){
    var perg = (e.perguntas || []).join('. ');
    var tags = (e.tags || []).join(' ');
    var corpo = (e[l] || e.pt || '').slice(0, 260);
    return (perg + '. ' + tags + '. ' + corpo).replace(/\s+/g, ' ').trim().slice(0, 420);
  }

  /* A peneira lexical erra por FALTA: medido, em 17% das perguntas dificeis a
     entrada certa nem pontuava, e ai nenhuma reordenacao a resgata -- ela nunca
     chega ao Worker. Como o reordenador passou a saber achar entre 60, sai mais
     barato completar a lista do que deixar a vaga vazia: as que pontuaram vao
     primeiro, na ordem delas, e o resto entra atras so para ter chance.
     Pergunta fora de escopo continua devolvendo vazio: completar ali seria dar
     contexto a quem perguntou de outro assunto, e o modelo florearia em cima. */
  /* Os n mais parecidos por TRIGRAMA, pulando os que ja entraram. Serve a dois
     donos: completar a peneira, e responder sozinha quando a pergunta nao tem
     nenhuma palavra de conteudo. Se `l` vier, devolve ja no formato do Worker. */
  function porTrigrama(pergunta, pular, n, l){
    var triQ = trigramas(pergunta), nQ = 0;
    for (var k in triQ) nQ++;
    var resto = [];
    for (var i = 0; i < INDICE.length; i++) {
      if (pular[INDICE[i].e.id]) continue;
      resto.push({ e: INDICE[i].e, s: cobertura(triQ, nQ, INDICE[i].tri) });
    }
    resto.sort(function(a, b){ return b.s - a.s; });
    var fora = resto.slice(0, n).map(function(x){ return x.e; });
    return l ? fora.map(function(e){ return paraCandidato(e, l); }) : fora;
  }

  function paraCandidato(e, l){
    return {
      texto: (e[l] || e.pt || '').slice(0, 700),
      fonte: e.fonte || '',
      busca: textoDeBusca(e, l)
    };
  }

  /* PERGUNTA COMPOSTA: "quanto custa E voces ja tem cliente" sao DUAS
     perguntas num campo so, e precisam de DUAS entradas entre as cinco que
     fundamentam. Pontuada inteira, ela vira um saco de fichas onde a metade
     mais "pesada" abafa a outra -- medido, o alvo da segunda metade caia em 8o.

     Aqui as metades sao pontuadas SEPARADAS e as listas INTERCALADAS, para que
     o topo tenha as duas. Nao decide resposta: decide quem chega na frente.

     So parte quando as duas metades tem substancia (2+ fichas cada): "preco e
     prazo" nao e pergunta composta, e partir ali so faria ruido. */
  function metades(pergunta){
    var partes = limpa(pergunta).split(/\s+e\s+|\s*[;,?]\s*/).filter(function(x){ return x.trim(); });
    if (partes.length < 2) return null;
    var boas = partes.filter(function(x){ return fichas(x).length >= 1; });
    return boas.length >= 2 ? boas.slice(0, 3) : null;
  }

  function intercala(listas){
    var fora = [], visto = {}, i = 0, restam = true;
    while (restam) {
      restam = false;
      for (var k = 0; k < listas.length; k++) {
        var e = listas[k][i];
        if (!e) continue;
        restam = true;
        if (!visto[e.id]) { visto[e.id] = 1; fora.push(e); }
      }
      i++;
    }
    return fora;
  }

  /* SEGUIMENTO SEM ASSUNTO. "por que" e "como assim" nao dizem de que falam --
     o assunto ficou na pergunta anterior. Medido em 27/08/2026: as duas
     mandavam 60 candidatos ao acaso, porque nenhuma ficha delas pontua.

     A pagina ja guarda o historico e ja o envia ao modelo; o que faltava era a
     BUSCA olhar para ele. So se usa quando a pergunta nova nao tem NENHUMA
     palavra distintiva -- "e o savi" tem, e nao precisa de muleta; "por que"
     nao tem, e sem a anterior nao ha o que buscar.

     A pergunta que vai ao reordenador continua a ser a NOVA: e ela que o
     visitante fez. A anterior serve so para escolher onde procurar. */
  function paraOWorker(pergunta, l, anterior){
    /* DOIS jeitos de a peneira voltar vazia, e eles pedem tratamento oposto:
         (a) a pergunta e de outro assunto  -> contexto vazio, e o modelo diz que
             nao tem o dado. Contexto irrelevante aqui so daria material para
             florear em cima.
         (b) a pergunta e nossa e a busca falhou  -> completar ate 60 e deixar o
             reordenador achar. "is it secure" tem UMA ficha, nenhuma entrada
             pontua, e mesmo assim e pergunta de visitante nosso.
       O portao so julga escopo quando ha PALAVRA SUFICIENTE para julgar: com
       uma ou duas fichas ele calava perguntas legitimas. */
    /* PORTAO DE ESCOPO. Medido em 27/08/2026 com 18 perguntas de outro assunto:
       ele barrava 3. Eu proprio o tinha afrouxado duas vezes nesse dia, e no
       mesmo dia tornei a recusa do modelo "ultimo recurso" -- as duas mudancas
       somam-se, e sobrava o modelo como unica defesa contra florear em cima de
       60 entradas irrelevantes. Com fonte ao lado, que e o pior modo de errar
       nesta pagina.

       Duas correcoes, as duas medidas:

       1. Para julgar ESCOPO, o vocabulario conta SO casamento EXATO. A
          tolerancia a erro de digitacao dava "ganhou" como conhecida (casa com
          "ganham", distancia 2) e "quem ganhou a copa" passava. Tolerar erro de
          digitacao ao PONTUAR esta certo; ao decidir se a pergunta e nossa,
          nao -- ali o parecido nao e prova.

       2. Pergunta de DUAS fichas exige as DUAS conhecidas. Com o piso de 40%,
          uma em duas ja dava 50% e passava: "capital da mongolia" entrava
          porque "capital" existe na base. Com uma ficha so nao ha o que julgar
          -- "e caro", "e seguro" e "is it secure" sao nossas -- entao ali nunca
          se barra. */
    var q = fichas(pergunta);
    /* Seguimento CURTO: a nova pergunta e a nova+anterior sao pontuadas
       SEPARADAS e depois intercaladas, como se faz com a pergunta composta.
       Somar as duas num texto so deixaria a anterior dominar quando fosse mais
       longa -- assim o que o visitante acabou de escrever nunca e deslocado, e
       o assunto da anterior entra atras.

       O limite de 3 fichas e o que separa seguimento de pergunta inteira:
       "por que", "como assim" e "e quanto custa" dependem do que veio antes;
       "quanto custa o savi barbergo" nao depende de nada. */
    var comAnterior = (anterior && q.length <= 3) ? anterior + ' ' + pergunta : '';
    var busca = pergunta;
    /* Pergunta SEM NENHUMA ficha propria ("por que", "como assim"): ali a
       anterior deixa de ser muleta e passa a SER a pergunta. Sem isto, o
       atalho de ficha vazia (logo abaixo) mandava para o trigrama e o historico
       nunca era olhado -- medido, "quanto custa o savi" seguido de "por que"
       devolvia por-que-ilpi em 1o e o preco em 52o. */
    if (!q.length && comAnterior) {
      busca = comAnterior;
      q = fichas(busca);
      comAnterior = '';
    }
    /* FICHA VAZIA NAO E FORA DE ESCOPO. "what do you do" e "ja esta no ar?" sao
       feitas SO de palavra de parada, e devolviam ZERO candidatos -- a versao
       inglesa do primeiro botao de sugestao respondia "nao tenho essa
       resposta". A contagem de palavra nao tem o que contar, mas o TRIGRAMA
       tem: ele compara caractere, e nao depende de sobrar palavra de conteudo.
       Manda os 60 mais parecidos e deixa o reordenador julgar. */
    if (!q.length) return porTrigrama(busca, {}, 60, l);
    var exatas = 0, proprias = 0;
    q.forEach(function(t){
      if (VOCAB.indexOf(t) >= 0) exatas++;
      if (distintiva(t)) proprias++;
    });
    /* A pergunta tem de trazer PELO MENOS UMA palavra que seja nossa. Sem
       isso, o que existe e coincidencia de vocabulario generico -- e foi assim
       que "quem foi napoleao bonaparte" e "who won the world cup" entravam. */
    if (q.length >= 2 && proprias === 0) return [];
    if (q.length >= 3 && exatas / q.length < 0.4) return [];
    /* Com duas fichas: passa se as DUAS existirem, ou se UMA for distintiva.
       Exigir as duas barrava "voces seguem a lgpd" -- "seguem" nao esta no
       indice e "lgpd" e inequivocamente nossa. Uma palavra forte vale mais que
       duas fracas, e e assim que a pergunta curta de visitante e feita. */
    if (q.length === 2 && exatas < 2 && proprias === 0) return [];

    /* Testei reservar 6 das 60 vagas para o trigrama, para nenhum sinal encher
       a lista sozinho. Medido no teste de exclusao (259 gatilhos retirados um a
       um): IDENTICO com e sem -- 238 chegando ao reordenador nos dois casos.
       Custava 6 candidatos lexicais e nao devolvia nada, entao saiu. */
    var partes = metades(busca);
    /* A ORDEM DAS LISTAS SEGUE ONDE ESTA O SINAL. Se a pergunta nova nao tem
       nenhuma palavra distintiva ("por que", "como assim"), ela sozinha nao
       sabe de nada e quem lidera e a lista com a anterior; se tem ("e quanto
       custa"), lidera a nova e a anterior entra atras so para desempatar.
       Medido: liderando sempre a nova, 3 de 5; assim, 4 de 5. */
    var cega = comAnterior && !q.some(distintiva);
    var listas = cega ? [candidatos(comAnterior, 60), candidatos(busca, 30)]
                      : [candidatos(busca, 60)];
    if (partes) partes.forEach(function(x){ listas.push(candidatos(x, 30)); });
    if (comAnterior && !cega) listas.push(candidatos(comAnterior, 30));
    var achados = listas.length > 1
      ? intercala(listas).slice(0, 60)
      : listas[0];
    if (achados.length < 60) {
      /* O PREENCHIMENTO NAO PODE SER PELA ORDEM DO ARQUIVO. Era, ate agora, e
         isso dava vantagem permanente a quem esta no comeco do ficheiro: se a
         contagem de palavra nao pontuasse nada, as ultimas entradas nunca eram
         vistas pelo reordenador. Ordem arbitraria e ordem, e o reordenador
         confia na lista que recebe.

         Aqui entra o trigrama: ordena o resto por quanto da pergunta aparece
         nos gatilhos da entrada. Nao decide resposta -- decide quem tem direito
         de ser considerado. */
      var tem = {};
      achados.forEach(function(e){ tem[e.id] = 1; });
      var extra = porTrigrama(busca, tem, 60 - achados.length, null);
      for (var j = 0; j < extra.length; j++) achados.push(extra[j]);
    }
    return achados.map(function(e){ return paraCandidato(e, l); });
  }

  /* ---------- fala ---------- */
  function escapa(s){
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  }
  function forte(s){   // deixa **assim** virar negrito, e so isso
    return escapa(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  }
  function diz(quem, html){
    var d = document.createElement('div');
    d.className = 'as-msg ' + quem;
    d.innerHTML = html;
    fluxo.appendChild(d);
    fluxo.scrollTop = fluxo.scrollHeight;
    return d;
  }
  function sorteia(a){ return a[Math.floor(Math.random() * a.length)]; }

  /* A pergunta atual JA esta no historico quando responder() corre (o submit
     empilha antes de chamar), entao a anterior e o penultimo 'user'. */
  function perguntaAnterior(){
    var us = historico.filter(function(m){ return m.r === 'user'; });
    return us.length >= 2 ? String(us[us.length - 2].t || '') : '';
  }

  function lembra(texto){
    historico.push({ r: 'assistant', t: texto });
    if (historico.length > 12) historico = historico.slice(-12);
  }

  function pensando(){
    var d = document.createElement('div');
    d.className = 'as-msg ela as-pensa';
    d.setAttribute('aria-hidden', 'true');          // leitor de tela nao anuncia reticencia
    d.innerHTML = '<span></span><span></span><span></span>';
    fluxo.appendChild(d);
    fluxo.scrollTop = fluxo.scrollHeight;
    return d;
  }

  /* O timeout nao e refinamento: sem ele, um Worker mudo trava a conversa para sempre e o
     piso local nunca chega a rodar. O timeout E o gatilho do fallback. */
  function perguntaAoWorker(pergunta, l, ctx){
    if (!API) return Promise.resolve(null);
    var rel = new AbortController();
    var t = setTimeout(function(){ rel.abort(); }, ESPERA_MS);
    return fetch(API, {
      method: 'POST',
      signal: rel.signal,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        pergunta: pergunta,
        idioma: l,
        historico: historico.slice(-6),
        contexto: ctx
      })
    }).then(function(r){
      if (!r.ok) return null;                        // 429, 503, 403 — todos caem no piso local
      return r.json();
    }).then(function(d){
      return (d && d.texto) ? d : null;
    }).catch(function(){
      return null;                                   // rede, CORS, timeout — mesmo caminho
    }).finally(function(){ clearTimeout(t); });
  }
  function rolaFim(){ requestAnimationFrame(function(){ fluxo.scrollTop = fluxo.scrollHeight; }); }

  /* Era codigo repetido tres vezes dentro de responder() */
  function botaoIr(msg, rotulo, hash){
    var b = document.createElement('button');
    b.className = 'as-ir';
    b.textContent = rotulo;
    b.addEventListener('click', function(){ irPara(hash); });
    msg.appendChild(b);
    rolaFim();
  }

  async function responder(pergunta){
    if (ocupado) return;
    ocupado = true;
    var envia = form.querySelector('.as-envia');
    if (envia) envia.disabled = true;
    /* CAPTURA O IDIOMA UMA VEZ SO. idioma() le o DOM na hora da chamada: se a pessoa trocar
       de lingua com a resposta em voo, uma leitura tardia devolve o idioma novo e a resposta
       sai misturada. */
    var l = idioma();

    var soc = ehSocial(pergunta);
    if (soc){
      lembra(FALA[soc][l] || FALA[soc].pt);
      diz('ela', forte(FALA[soc][l] || FALA[soc].pt));
      montaChips();
      ocupado = false;
      if (envia) envia.disabled = false;
      return;
    }

    var reticencia = pensando();
    var respondido = false;
    try {
      /* 60, nao 5. A busca por palavra deixou de ESCOLHER e passou a PENEIRAR:
         quem escolhe as 5 que fundamentam a resposta e o reordenador, no Worker,
         que le pergunta e trecho juntos. Medido: a entrada certa aparecia em 8o,
         17o e ate 43o lugar nesta ordem -- dentro de 60, fora de 5. */
      var ctx = paraOWorker(pergunta, l, perguntaAnterior());
      var r = await perguntaAoWorker(pergunta, l, ctx);
      if (r && r.texto) {
        lembra(r.texto);
        reticencia.remove();
        reticencia = null;
        /* forte() escapa ANTES de virar negrito. O texto do modelo e conteudo nao confiavel:
           entrando por innerHTML cru, abriria um XSS que a base local nunca teve. */
        var mr = diz('ela', forte(r.texto));
        /* A base local sempre mostrou a fonte embaixo; a resposta do modelo nao
           mostrava — e nesta pagina numero sem fonte e o pecado capital. A fonte
           sai DAQUI, das entradas que fundamentaram a resposta, e nao do texto do
           modelo, que poderia inventa-la. */
        if (r.motor !== 'sem-contexto') {
          /* A fonte vem do Worker: sao as entradas que o REORDENADOR escolheu.
             Usar as da peneira seria mostrar a fonte de uma entrada que talvez
             nem tenha fundamentado a resposta. So caimos na lista local se o
             Worker for antigo e nao mandar fontes. */
          var fs = [];
          if (r.fontes && r.fontes.length) {
            fs = r.fontes.slice(0, 2);
          } else {
            ctx.slice(0, 5).forEach(function(e){
              if (e.fonte && fs.indexOf(e.fonte) < 0 && fs.length < 2) fs.push(e.fonte);
            });
          }
          if (fs.length) {
            var df = document.createElement('div');
            df.className = 'as-fonte';
            df.textContent = fs.join(' · ');
            mr.appendChild(df);
          }
        }
        botaoIr(mr, l === 'pt' ? 'Falar com o fundador' : 'Talk to the founder', '#contato');
        respondido = true;
      }
    } catch (err) {
      /* nada a fazer aqui: o piso local resolve embaixo */
    } finally {
      ocupado = false;
      if (envia) envia.disabled = false;
      if (reticencia) reticencia.remove();
    }
    if (!respondido) responderLocal(pergunta, l);
  }

  function responderLocal(pergunta, l){
    var e = busca(pergunta);
    lembra(e ? (e[l] || e.pt) : (l === 'pt' ? 'Nao tenho esse dado.' : 'I do not have that figure.'));
    if (!e) {
      var sem = BASE.semResposta.naoSei[l];
      var d = diz('ela', forte(sorteia(sem)));
      botaoIr(d, l === 'pt' ? 'Falar com o fundador' : 'Talk to the founder', '#contato');
      return;
    }
    var txt = forte(e[l] || e.pt);
    if (e.fonte) txt += '<div class="as-fonte">' + escapa(e.fonte) + '</div>';
    var msg = diz('ela', txt);
    if (e.encaminha === 'falar-com-fundador') {
      botaoIr(msg, l === 'pt' ? 'Falar com o fundador' : 'Talk to the founder', '#contato');
    } else if (e.encaminha === 'ver-secao' && e.secao) {
      botaoIr(msg, l === 'pt' ? 'Ver na página' : 'See it on the page', e.secao);
    }
  }

  function irPara(hash){
    var alvo = document.querySelector(hash);
    if (!alvo) return;
    esconde();
    setTimeout(function(){ alvo.scrollIntoView({behavior:'smooth', block:'start'}); }, 260);
  }

  /* ---------- chips de partida ---------- */
  function montaChips(){
    var l = idioma();
    chips.innerHTML = '';
    (BASE.sugestoes || []).slice(0, 6).forEach(function(s){
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'as-chip';
      b.textContent = s[l] || s.pt;
      b.addEventListener('click', function(){
        diz('eu', escapa(b.textContent));
        chips.style.display = 'none';
        historico.push({ r: 'user', t: b.textContent });
    responder(b.textContent);
      });
      chips.appendChild(b);
    });
    chips.style.display = '';
  }

  /* ---------- abrir e fechar ---------- */
  var aberto = false, jaSaudou = false;
  function mostra(){
    if (aberto) return;
    aberto = true;
        requestAnimationFrame(function(){ painel.classList.add('on'); veu.classList.add('on'); });
    abre.setAttribute('aria-expanded', 'true');
    if (!jaSaudou) {
      jaSaudou = true;
      var l = idioma();
      diz('ela', forte(l === 'pt'
        ? 'Pergunte o que quiser sobre a 3BRAIN, os produtos ou os números da página. **Toda resposta vem com a fonte** — e o que eu não souber, eu digo que não sei.'
        : 'Ask anything about 3BRAIN, the products or the numbers on this page. **Every answer carries its source** — and what I do not know, I say I do not know.'));
      montaChips();
    }
    setTimeout(function(){ campo.focus(); }, 380);
  }
  function esconde(){
    if (!aberto) return;
    aberto = false;
    painel.classList.remove('on'); veu.classList.remove('on');
    abre.setAttribute('aria-expanded', 'false');
    abre.focus();
  }

  abre.addEventListener('click', mostra);
  fecha.addEventListener('click', esconde);
  veu.addEventListener('click', esconde);
  document.addEventListener('keydown', function(ev){ if (ev.key === 'Escape' && aberto) esconde(); });

  form.addEventListener('submit', function(ev){
    ev.preventDefault();
    var t = campo.value.trim();
    if (!t) return;
    diz('eu', escapa(t));
    campo.value = '';
    chips.style.display = 'none';
    historico.push({ r: 'user', t: t });
    responder(t);
  });

  /* placeholder segue o idioma da pagina */
  function idiomaMudou(){
    campo.placeholder = idioma() === 'pt' ? 'Escreva sua dúvida' : 'Type your question';
    if (chips.style.display !== 'none' && chips.children.length) montaChips();
  }
  idiomaMudou();
  var btnLang = document.getElementById('langBtn');
  if (btnLang) btnLang.addEventListener('click', function(){ setTimeout(idiomaMudou, 60); });

  /* quem chega pelo e-mail encontra a barra ja aberta */
  var p = new URLSearchParams(location.search);
  if (p.get('de') === 'email' || p.get('from') === 'email' || location.hash === '#duvidas') {
    setTimeout(mostra, 900);
  }
})();
